void testHIRDeadLocalDeclarationCleanupSkipsOpaqueStatements() {
  auto expression = [](crossgl::HIRExpressionKind kind, std::string value,
                       crossgl::HIRType type) {
    crossgl::HIRExpression result;
    result.kind = kind;
    result.value = std::move(value);
    result.type = std::move(type);
    return result;
  };
  auto literal = [&](std::string value, std::string typeName) {
    return expression(crossgl::HIRExpressionKind::Literal, std::move(value),
                      crossgl::HIRType{std::move(typeName), std::nullopt});
  };
  auto declaration = [&](std::string name, crossgl::HIRExpression value) {
    crossgl::HIRStatement statement;
    statement.kind = crossgl::HIRStatementKind::Declaration;
    statement.declaredType = value.type;
    statement.name = std::move(name);
    statement.value = std::move(value);
    return statement;
  };
  auto token = [](crossgl::TokenKind kind, std::string text) {
    crossgl::Token result;
    result.kind = kind;
    result.text = std::move(text);
    return result;
  };

  crossgl::HIRModule module = simpleModule();
  std::vector<crossgl::HIRStatement> &body =
      module.stages.front().functions.front().body;
  body.push_back(declaration("deadBeforeRaw", literal("1", "int")));

  crossgl::HIRStatement raw;
  raw.kind = crossgl::HIRStatementKind::Raw;
  raw.rawTokens.push_back(token(crossgl::TokenKind::Identifier, "while"));
  body.push_back(std::move(raw));

  body.push_back(declaration("deadBeforeRawUpdate", literal("2", "int")));
  crossgl::HIRStatement loop;
  loop.kind = crossgl::HIRStatementKind::For;
  loop.value = literal("true", "bool");
  loop.updateTokens = {token(crossgl::TokenKind::Identifier, "i"),
                       token(crossgl::TokenKind::Operator, "++")};
  body.push_back(std::move(loop));

  crossgl::DiagnosticEngine diagnostics;
  const crossgl::HIRPassPipelineResult result =
      crossgl::runHIRPassPipeline(module, diagnostics);
  expect(hasDiagnosticCode(diagnostics.diagnostics(),
                           "opt.hir-raw-statement-backend-input"),
         "HIR dead local cleanup opaque-statement fixture fails closed before "
         "backend input");
  const crossgl::HIRPassResult *deadLocalPass =
      findHIRPassResult(result, "hir.optimize.cleanup-dead-local-declarations");
  expect(deadLocalPass != nullptr && !deadLocalPass->changed &&
             hirBlockContainsDeclaration(body, "deadBeforeRaw") &&
             hirBlockContainsDeclaration(body, "deadBeforeRawUpdate"),
         "HIR dead local cleanup pass skips functions with raw statements or "
         "unparsed loop updates");
}

void testHIRDeadPureExpressionStatementCleanupPass() {
  constexpr std::string_view source = R"(
shader DeadExpressionCleanupShader {
  float helper(float value) {
    return value;
  }

  float loopTick(float value) {
    return value;
  }

  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values;
    layout(set = 0, binding = 1) uniform sampler2D colorMap;
    layout(set = 0, binding = 2) uniform image2D sideEffects;
    void main() {
      float unusedExpressionInput = 1.0;
      sin(unusedExpressionInput);
      unusedExpressionInput + 2.0;
      helper(values[0]);
      imageLoad(sideEffects, ivec2(0, 0));
      imageStore(sideEffects, ivec2(0, 0), vec4(1.0, 0.0, 0.0, 0.0));
      texture(colorMap, vec2(0.5, 0.5));
      textureCompareKernel(ivec2(0, 0), 0.40);
      for (int i = 0; i < 1; loopTick(0.0)) {
      }
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "dead expression cleanup source builds HIR");
  if (!hir.has_value()) {
    return;
  }

  crossgl::DiagnosticEngine diagnostics;
  const crossgl::HIRPassPipelineResult result =
      crossgl::runHIRPassPipeline(*hir, diagnostics);
  expect(!diagnostics.hasErrors(),
         "HIR dead expression cleanup pass accepts valid modules");
  const crossgl::HIRPassResult *deadLocalPass =
      findHIRPassResult(result, "hir.optimize.cleanup-dead-local-declarations");
  expect(deadLocalPass != nullptr && deadLocalPass->changed,
         "HIR dead expression cleanup reports removed expression statements");

  const std::vector<crossgl::HIRStatement> &body =
      hir->stages.front().functions.front().body;
  expect(!hirBlockContainsDeclaration(body, "unusedExpressionInput") &&
             !hirBlockContainsExpressionStatementValue(body, "sin") &&
             !hirBlockContainsExpressionStatementValue(body, "+") &&
             hirBlockContainsExpressionStatementValue(body, "helper") &&
             hirBlockContainsExpressionStatementValue(body, "imageLoad") &&
             hirBlockContainsExpressionStatementValue(body, "imageStore") &&
             hirBlockContainsExpressionStatementValue(body, "texture") &&
             hirBlockContainsExpressionStatementValue(
                 body, "textureCompareKernel") &&
             hirBlockContainsExpressionStatementValue(body, "loopTick"),
         "HIR dead expression cleanup removes only standalone pure expression "
         "statements and keeps unknown calls, resource effects, structural "
         "builders, and loop-header updates");
}

void testHIRDeadLocalStoreCleanupPass() {
  constexpr std::string_view source = R"(
shader DeadLocalStoreCleanupShader {
  float helper(float value) {
    return value;
  }

  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values;
    layout(set = 0, binding = 1) uniform sampler2D colorMap;
    layout(set = 0, binding = 2) uniform image2D sideEffects;
    void main() {
      float overwritten = values[0];
      overwritten = 1.0;
      overwritten = 2.0;
      values[0] = overwritten;

      float compound = values[0];
      compound += 1.0;
      values[1] = compound;

      float keptCallStore = 0.0;
      keptCallStore = helper(values[0]);
      keptCallStore = 3.0;
      values[2] = keptCallStore;

      float pureCallStore = 0.0;
      pureCallStore = sin(values[0]);
      pureCallStore = 9.0;
      values[6] = pureCallStore;

      float keptImageLoadStore = 0.0;
      keptImageLoadStore = imageLoad(sideEffects, ivec2(0, 0)).x;
      keptImageLoadStore = 10.0;
      values[7] = keptImageLoadStore;

      float keptTextureStore = 0.0;
      keptTextureStore = texture(colorMap, vec2(0.5, 0.5)).x;
      keptTextureStore = 4.0;
      values[3] = keptTextureStore;

      float branchValue = values[0];
      if (values[0] > 0.0) {
        branchValue = 5.0;
        branchValue = 6.0;
        values[4] = branchValue;
      }
      values[5] = branchValue;

      for (int i = 0; i < 1; i = i + 1) {
        branchValue = 7.0;
        branchValue = 8.0;
      }

      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "dead local store cleanup source builds HIR");
  if (!hir.has_value()) {
    return;
  }

  crossgl::DiagnosticEngine diagnostics;
  const crossgl::HIRPassPipelineResult result =
      crossgl::runHIRPassPipeline(*hir, diagnostics);
  const crossgl::HIRPassResult *pass =
      findHIRPassResult(result, "hir.optimize.cleanup-dead-local-stores");
  expect(!diagnostics.hasErrors(),
         "HIR dead local store cleanup pass accepts valid modules");
  expect(pass != nullptr && pass->changed,
         "HIR dead local store cleanup pass reports removed stores");

  const std::vector<crossgl::HIRStatement> &body =
      hir->stages.front().functions.front().body;
  const crossgl::HIRStatement *overwritten =
      findHIRBlockDeclaration(body, "overwritten");
  const crossgl::HIRStatement *compound =
      findHIRBlockDeclaration(body, "compound");
  const crossgl::HIRStatement *keptCallStore =
      findHIRBlockDeclaration(body, "keptCallStore");
  const crossgl::HIRStatement *pureCallStore =
      findHIRBlockDeclaration(body, "pureCallStore");
  const crossgl::HIRStatement *keptImageLoadStore =
      findHIRBlockDeclaration(body, "keptImageLoadStore");

  expect(overwritten != nullptr &&
             overwritten->value.kind == crossgl::HIRExpressionKind::Empty &&
             !hirBlockContainsAssignmentToIdentifier(body, "overwritten",
                                                     "1.0") &&
             hirBlockContainsAssignmentToIdentifier(body, "overwritten",
                                                     "2.0"),
         "HIR dead local store cleanup clears dead declaration initializers and "
         "removes overwritten pure assignments");
  expect(compound != nullptr &&
             compound->value.kind != crossgl::HIRExpressionKind::Empty &&
             hirBlockContainsAssignmentToIdentifier(body, "compound"),
         "HIR dead local store cleanup keeps compound assignments that read the "
         "previous local value");
  expect(keptCallStore != nullptr &&
             keptCallStore->value.kind == crossgl::HIRExpressionKind::Empty &&
             hirBlockContainsAssignmentToIdentifier(body, "keptCallStore",
                                                     "helper") &&
             pureCallStore != nullptr &&
             pureCallStore->value.kind == crossgl::HIRExpressionKind::Empty &&
             !hirBlockContainsAssignmentToIdentifier(body, "pureCallStore",
                                                     "sin") &&
             hirBlockContainsAssignmentToIdentifier(body, "pureCallStore",
                                                     "9.0") &&
             keptImageLoadStore != nullptr &&
             keptImageLoadStore->value.kind ==
                 crossgl::HIRExpressionKind::Empty &&
             hirBlockContainsAssignmentValueKind(
                 body, "keptImageLoadStore",
                 crossgl::HIRExpressionKind::MemberAccess) &&
             hirBlockContainsAssignmentToIdentifier(body, "keptImageLoadStore",
                                                    "10.0") &&
             hirBlockContainsAssignmentValueKind(
                 body, "keptTextureStore",
                 crossgl::HIRExpressionKind::TextureSample) &&
             !hirBlockContainsAssignmentToIdentifier(body, "branchValue",
                                                      "5.0") &&
             hirBlockContainsAssignmentToIdentifier(body, "branchValue",
                                                     "6.0") &&
             !hirBlockContainsAssignmentToIdentifier(body, "branchValue",
                                                      "7.0") &&
             !hirBlockContainsAssignmentToIdentifier(body, "branchValue",
                                                      "8.0"),
         "HIR dead local store cleanup prunes pure intrinsic stores while "
         "keeping impure stores and removing unobserved loop-body stores");
}

