void testHIRIntrinsicFoldingSkipsManualTextureCompareKernels() {
  auto type = [](std::string name) {
    return crossgl::HIRType{std::move(name), std::nullopt};
  };
  auto expression = [](crossgl::HIRExpressionKind kind, std::string value,
                       crossgl::HIRType expressionType) {
    crossgl::HIRExpression result;
    result.kind = kind;
    result.value = std::move(value);
    result.type = std::move(expressionType);
    return result;
  };
  auto identifier = [&](std::string value, crossgl::HIRType identifierType) {
    return expression(crossgl::HIRExpressionKind::Identifier, std::move(value),
                      std::move(identifierType));
  };
  auto literal = [&](std::string value, crossgl::HIRType literalType) {
    return expression(crossgl::HIRExpressionKind::Literal, std::move(value),
                      std::move(literalType));
  };
  auto ivec2 = [&](std::string x, std::string y) {
    crossgl::HIRExpression result =
        expression(crossgl::HIRExpressionKind::Constructor, "ivec2",
                   type("ivec2"));
    result.children.push_back(literal(std::move(x), type("int")));
    result.children.push_back(literal(std::move(y), type("int")));
    return result;
  };

  crossgl::HIRExpression lengthWeight =
      expression(crossgl::HIRExpressionKind::Call, "length", type("float"));
  crossgl::HIRExpression weightVector =
      expression(crossgl::HIRExpressionKind::Constructor, "vec2", type("vec2"));
  weightVector.children.push_back(literal("0.3", type("float")));
  weightVector.children.push_back(literal("0.4", type("float")));
  lengthWeight.children.push_back(std::move(weightVector));

  crossgl::HIRExpression tapList =
      expression(crossgl::HIRExpressionKind::Call, "textureCompareKernel",
                 type("textureCompareKernel"));
  tapList.children.push_back(ivec2("0", "0"));
  tapList.children.push_back(std::move(lengthWeight));
  tapList.children.push_back(ivec2("1", "0"));
  tapList.children.push_back(literal("0.5", type("float")));

  crossgl::HIRExpression manualCompare = expression(
      crossgl::HIRExpressionKind::TextureCompareLodManual,
      "textureCompareLodManualKernel", type("float"));
  manualCompare.children = {
      identifier("shadowMap", type("sampler2DShadow")),
      identifier("rawShadowSampler", type("sampler")),
      identifier("uv", type("vec2")),
      literal("0.25", type("float")),
      literal("2.0", type("float")),
      identifier("less_equal", type("compare_func")),
      std::move(tapList),
  };

  crossgl::HIRStatement statement;
  statement.kind = crossgl::HIRStatementKind::Expression;
  statement.value = std::move(manualCompare);

  crossgl::HIRModule module = simpleModule();
  module.stages.front().functions.front().body.push_back(std::move(statement));

  const crossgl::HIRPass *foldPass = nullptr;
  for (const crossgl::HIRPass &pass : crossgl::defaultHIRPassPipeline()) {
    if (pass.name == "hir.optimize.fold-constant-intrinsics") {
      foldPass = &pass;
      break;
    }
  }
  crossgl::DiagnosticEngine diagnostics;
  const bool changed = foldPass != nullptr && foldPass->run != nullptr
                           ? foldPass->run(module, diagnostics)
                           : false;
  const crossgl::HIRExpression &foldedManual =
      module.stages.front().functions.front().body.front().value;
  const crossgl::HIRExpression &foldedWeight =
      foldedManual.children.back().children[1];
  expect(foldPass != nullptr && !diagnostics.hasErrors() && !changed &&
             foldedWeight.kind == crossgl::HIRExpressionKind::Call &&
             foldedWeight.value == "length",
         "HIR intrinsic folding pass preserves manual texture compare kernel "
         "weight expressions");
}

std::vector<crossgl::Diagnostic>
collectVulkanPrototypeDiagnostics(std::string_view source) {
  crossgl::DiagnosticEngine diagnostics;
  crossgl::Lexer lexer("<unit>", source, diagnostics);
  std::vector<crossgl::Token> tokens = lexer.lex();
  crossgl::Parser parser(tokens, diagnostics);
  std::optional<crossgl::ShaderModule> ast = parser.parseModule();
  if (ast && !diagnostics.hasErrors()) {
    std::optional<crossgl::HIRModule> hir = crossgl::buildHIR(*ast, diagnostics);
    if (hir && !diagnostics.hasErrors()) {
      (void)crossgl::generateVulkanPrototypeAssembly(*hir, diagnostics);
    }
  }
  return diagnostics.diagnostics();
}

bool hasDiagnostic(const std::vector<crossgl::Diagnostic> &diagnostics,
                   std::string_view code) {
  for (const crossgl::Diagnostic &diagnostic : diagnostics) {
    if (diagnostic.code == code) {
      return true;
    }
  }
  return false;
}

const crossgl::Diagnostic *
findDiagnostic(const std::vector<crossgl::Diagnostic> &diagnostics,
               std::string_view code) {
  for (const crossgl::Diagnostic &diagnostic : diagnostics) {
    if (diagnostic.code == code) {
      return &diagnostic;
    }
  }
  return nullptr;
}

bool hasDiagnosticMessageFragment(
    const std::vector<crossgl::Diagnostic> &diagnostics, std::string_view code,
    std::string_view fragment) {
  for (const crossgl::Diagnostic &diagnostic : diagnostics) {
    if (diagnostic.code == code &&
        diagnostic.message.find(fragment) != std::string::npos) {
      return true;
    }
  }
  return false;
}

void testExpressionParserRejectsMalformedTokens() {
  struct MalformedExpressionCase {
    std::string_view label;
    std::string_view source;
    std::string_view messageFragment;
  };

  const MalformedExpressionCase cases[] = {
      {"trailing declaration initializer",
       R"(
shader BadTrailingInitializerShader {
  compute {
    void main() {
      float x = 1.0;
      float y = x 2.0;
      return;
    }
  }
}
)",
       "trailing token"},
      {"missing binary right operand",
       R"(
shader BadMissingOperandShader {
  compute {
    void main() {
      float x = 1.0;
      float y = x +;
      return;
    }
  }
}
)",
       "expected expression operand"},
      {"trailing call argument token",
       R"(
shader BadCallArgumentShader {
  compute {
    void main() {
      float x = 1.0;
      float y = clamp(x 0.0, 0.0, 1.0);
      return;
    }
  }
}
)",
       "trailing token"},
      {"trailing index token",
       R"(
shader BadIndexExpressionShader {
  compute {
    layout(set = 0, binding = 0) buffer float* values;
    void main() {
      float y = values[0 1];
      return;
    }
  }
}
)",
       "trailing token"}};

  for (const MalformedExpressionCase &testCase : cases) {
    const std::vector<crossgl::Diagnostic> diagnostics =
        collectDiagnostics(testCase.source);
    expect(hasDiagnosticMessageFragment(diagnostics, "sema.expression-parse",
                                        testCase.messageFragment),
           std::string(testCase.label) +
               " reports an expression parse diagnostic");
    expect(!parseHIR(testCase.source).has_value(),
           std::string(testCase.label) +
               " does not build partial HIR after expression parse failure");
  }
}

