void testSPIRVModuleBuilder() {
  crossgl::SPIRVModule module;
  const crossgl::SPIRVId tmp = module.nextResultId("tmp");
  const crossgl::SPIRVId merge = module.nextLabelId("if_merge");
  const crossgl::SPIRVId tmpLabel = module.nextLabelId("tmp");
  expect(tmp.str() == "%tmp_0", "SPIR-V module builder allocates temp ids");
  expect(merge.str() == "%if_merge_0",
         "SPIR-V module builder allocates label ids");
  expect(tmpLabel.str() == "%tmp_1",
         "SPIR-V module builder shares the result/label id namespace");

  crossgl::SPIRVModule reservedModule;
  reservedModule.defineType(crossgl::SPIRVModule::id("%tmp_0"), "OpTypeVoid");
  expect(reservedModule.nextResultId("tmp").str() == "%tmp_1",
         "SPIR-V module builder avoids caller-defined result ids");

  crossgl::SPIRVModule duplicateSectionModule;
  const crossgl::SPIRVId duplicateId =
      crossgl::SPIRVModule::id("%duplicate_id");
  duplicateSectionModule.defineType(duplicateId, "OpTypeVoid");
  bool rejectedDuplicateSectionId = false;
  try {
    duplicateSectionModule.defineConstant(duplicateId, duplicateId, "0");
  } catch (const std::logic_error &) {
    rejectedDuplicateSectionId = true;
  }
  expect(rejectedDuplicateSectionId,
         "SPIR-V module builder rejects duplicate caller-defined result ids "
         "across sections");

  const crossgl::SPIRVId voidType = crossgl::SPIRVModule::id("%void");
  const crossgl::SPIRVId functionType = crossgl::SPIRVModule::id("%fn_void");
  const crossgl::SPIRVId mainFunction = crossgl::SPIRVModule::id("%main");

  module.addCapability("Shader");
  module.addExtension("SPV_EXT_descriptor_indexing");
  module.addExtInstImport(crossgl::SPIRVModule::id("%glsl_std_450"),
                          "GLSL.std.450");
  module.addExtInstImport(crossgl::SPIRVModule::id("%glsl_std_450"),
                          "GLSL.std.450");
  expect(module.extInstImports().size() == 1,
         "SPIR-V module builder deduplicates extended instruction imports");
  expect(module.extInstImports().front().result.str() == "%glsl_std_450" &&
             module.extInstImports().front().instructionSet == "GLSL.std.450",
         "SPIR-V module builder exposes extended instruction imports");
  module.setMemoryModel(crossgl::SPIRVAddressingModel::Logical,
                        crossgl::SPIRVMemoryModel::GLSL450);
  module.addEntryPoint(crossgl::SPIRVExecutionModel::GLCompute, mainFunction,
                       "main", {});
  module.addExecutionMode(mainFunction, "LocalSize", {"1", "1", "1"});
  module.defineType(voidType, "OpTypeVoid");
  module.defineType(functionType, "OpTypeFunction", {voidType.str()});

  crossgl::SPIRVFunctionDefinition function;
  function.id = mainFunction;
  function.returnType = voidType;
  function.functionType = functionType;
  function.entryLabel = "%entry_main";
  module.addFunction(std::move(function));

  const std::string expected =
      "OpCapability Shader\n"
      "OpExtension \"SPV_EXT_descriptor_indexing\"\n"
      "%glsl_std_450 = OpExtInstImport \"GLSL.std.450\"\n"
      "OpMemoryModel Logical GLSL450\n"
      "OpEntryPoint GLCompute %main \"main\"\n"
      "OpExecutionMode %main LocalSize 1 1 1\n"
      "%void = OpTypeVoid\n"
      "%fn_void = OpTypeFunction %void\n"
      "%main = OpFunction %void None %fn_void\n"
      "%entry_main = OpLabel\n"
      "OpReturn\n"
      "OpFunctionEnd\n";
  expect(module.render() == expected,
         "SPIR-V module builder renders ordered module sections");

  crossgl::SPIRVModule typedResourceModule;
  const crossgl::SPIRVId uintType = crossgl::SPIRVModule::id("%uint");
  const crossgl::SPIRVId floatType = crossgl::SPIRVModule::id("%float");
  const crossgl::SPIRVId length = crossgl::SPIRVModule::id("%const_uint_4");
  const crossgl::SPIRVId runtimeArray =
      crossgl::SPIRVModule::id("%runtimearr_float");
  const crossgl::SPIRVId fixedArray =
      crossgl::SPIRVModule::id("%arr_float_4");
  const crossgl::SPIRVId blockType =
      crossgl::SPIRVModule::id("%StorageBuffer_float");
  const crossgl::SPIRVId pointerType = crossgl::SPIRVModule::id(
      "%ptr_StorageBuffer_StorageBuffer_float");
  const crossgl::SPIRVId variable =
      crossgl::SPIRVModule::id("%resource_values");
  typedResourceModule.decorateArrayStride(runtimeArray, 16);
  typedResourceModule.decorateMemberOffset(blockType, 0, 0);
  typedResourceModule.decorateBlock(blockType);
  typedResourceModule.decorateDescriptorSetBinding(variable, 2, 3);
  typedResourceModule.defineType(uintType, "OpTypeInt", {"32", "0"});
  typedResourceModule.defineType(floatType, "OpTypeFloat", {"32"});
  typedResourceModule.defineRuntimeArrayType(runtimeArray, floatType);
  typedResourceModule.defineConstant(length, uintType, "4");
  typedResourceModule.defineArrayType(fixedArray, floatType, length);
  typedResourceModule.defineStructType(blockType, {runtimeArray});
  typedResourceModule.definePointerType(pointerType,
                                        crossgl::SPIRVStorageClass::StorageBuffer,
                                        blockType);
  typedResourceModule.defineGlobalVariable(
      variable, pointerType, crossgl::SPIRVStorageClass::StorageBuffer);

  const std::string expectedTypedResource =
      "OpDecorate %runtimearr_float ArrayStride 16\n"
      "OpMemberDecorate %StorageBuffer_float 0 Offset 0\n"
      "OpDecorate %StorageBuffer_float Block\n"
      "OpDecorate %resource_values DescriptorSet 2\n"
      "OpDecorate %resource_values Binding 3\n"
      "%uint = OpTypeInt 32 0\n"
      "%float = OpTypeFloat 32\n"
      "%runtimearr_float = OpTypeRuntimeArray %float\n"
      "%arr_float_4 = OpTypeArray %float %const_uint_4\n"
      "%StorageBuffer_float = OpTypeStruct %runtimearr_float\n"
      "%ptr_StorageBuffer_StorageBuffer_float = OpTypePointer StorageBuffer "
      "%StorageBuffer_float\n"
      "%const_uint_4 = OpConstant %uint 4\n"
      "%resource_values = OpVariable "
      "%ptr_StorageBuffer_StorageBuffer_float StorageBuffer\n";
  expect(typedResourceModule.render() == expectedTypedResource,
         "SPIR-V module builder renders typed storage-buffer resource "
         "declarations");

  crossgl::SPIRVModule unresolvedReferenceModule;
  unresolvedReferenceModule.addCapability("Shader");
  unresolvedReferenceModule.addEntryPoint(
      crossgl::SPIRVExecutionModel::GLCompute,
      crossgl::SPIRVModule::id("%missing_main"), "main",
      {crossgl::SPIRVModule::id("%missing_interface")});
  std::string unresolvedReferenceMessage;
  try {
    static_cast<void>(unresolvedReferenceModule.render());
  } catch (const std::logic_error &error) {
    unresolvedReferenceMessage = error.what();
  }
  expect(unresolvedReferenceMessage ==
             "SPIR-V module references undefined result ids: %missing_main, "
             "%missing_interface",
         "SPIR-V module builder reports undefined references deterministically");

  crossgl::SPIRVRenderOptions partialRenderOptions;
  partialRenderOptions.validateReferences = false;
  expect(unresolvedReferenceModule.render(partialRenderOptions)
             .find("OpEntryPoint GLCompute %missing_main \"main\" "
                   "%missing_interface") != std::string::npos,
         "SPIR-V module builder can render partial assembly when validation is "
         "disabled");

  crossgl::SPIRVModule invalidFunctionModule;
  crossgl::SPIRVFunctionDefinition invalidFunction;
  invalidFunction.id = crossgl::SPIRVModule::id("%missing_label");
  invalidFunction.returnType = voidType;
  invalidFunction.functionType = functionType;
  bool rejectedMissingLabel = false;
  try {
    invalidFunctionModule.addFunction(std::move(invalidFunction));
  } catch (const std::logic_error &) {
    rejectedMissingLabel = true;
  }
  expect(rejectedMissingLabel,
         "SPIR-V module builder rejects function bodies without entry labels");

  crossgl::SPIRVModule duplicateLabelModule;
  duplicateLabelModule.defineType(duplicateId, "OpTypeVoid");
  crossgl::SPIRVFunctionDefinition duplicateLabelFunction;
  duplicateLabelFunction.id = crossgl::SPIRVModule::id("%label_collision_main");
  duplicateLabelFunction.returnType = voidType;
  duplicateLabelFunction.functionType = functionType;
  duplicateLabelFunction.entryLabel = duplicateId.str();
  bool rejectedDuplicateEntryLabel = false;
  try {
    duplicateLabelModule.addFunction(std::move(duplicateLabelFunction));
  } catch (const std::logic_error &) {
    rejectedDuplicateEntryLabel = true;
  }
  expect(rejectedDuplicateEntryLabel,
         "SPIR-V module builder rejects entry labels that collide with "
         "caller-defined result ids");
}

void testVulkanSPIRVImportMetadataCanonicalization() {
  const std::vector<crossgl::VulkanSPIRVImport> canonical =
      crossgl::canonicalizeVulkanSPIRVImports({
          {"%debug_printf", "NonSemantic.DebugPrintf"},
          {"%glsl_std_450", "GLSL.std.450"},
          {"%debug_printf", "NonSemantic.DebugPrintf"},
          {"%shader_debug_info", "NonSemantic.Shader.DebugInfo.100"},
          {"%glsl_std_450", "GLSL.std.450"},
      });
  expect(canonical.size() == 3,
         "Vulkan SPIR-V import metadata canonicalization removes exact repeats");
  if (canonical.size() == 3) {
    expect(canonical[0].resultId == "%glsl_std_450" &&
               canonical[0].instructionSet == "GLSL.std.450" &&
               canonical[1].resultId == "%debug_printf" &&
               canonical[1].instructionSet == "NonSemantic.DebugPrintf" &&
               canonical[2].resultId == "%shader_debug_info" &&
               canonical[2].instructionSet ==
                   "NonSemantic.Shader.DebugInfo.100",
           "Vulkan SPIR-V import metadata canonicalization sorts "
           "dependencies deterministically");
  }

  auto rejectsImportMetadata =
      [](std::vector<crossgl::VulkanSPIRVImport> imports) {
        try {
          static_cast<void>(
              crossgl::canonicalizeVulkanSPIRVImports(std::move(imports)));
        } catch (const std::logic_error &) {
          return true;
        }
        return false;
      };
  expect(rejectsImportMetadata({{"%a", "GLSL.std.450"},
                                {"%b", "GLSL.std.450"}}),
         "Vulkan SPIR-V import metadata rejects repeated instruction sets "
         "with different result ids");
  expect(rejectsImportMetadata({{"%shared", "GLSL.std.450"},
                                {"%shared", "NonSemantic.DebugPrintf"}}),
         "Vulkan SPIR-V import metadata rejects result ids reused for "
         "different instruction sets");
  expect(rejectsImportMetadata({{"", "GLSL.std.450"}}),
         "Vulkan SPIR-V import metadata rejects empty result ids");
  expect(rejectsImportMetadata({{"%missing_set", ""}}),
         "Vulkan SPIR-V import metadata rejects empty instruction sets");
}

void testBackendIRContracts() {
  const crossgl::HIRModule module = simpleModule();
  const std::string metal =
      crossgl::printBackendIR(module, crossgl::TargetKind::Metal);
  expect(metal.find("vertex VertexOutput vertex_main") != std::string::npos,
         "Metal backend IR emits a vertex entry point");

  const std::string vulkan =
      crossgl::printBackendIR(module, crossgl::TargetKind::Vulkan);
  expect(vulkan.find("backend lowering for vulkan") != std::string::npos,
         "Vulkan backend reports planned lowering");
  expect(vulkan.find("vulkan.module @UnitShader") != std::string::npos,
         "Vulkan backend emits descriptor scaffolding module");
  expect(vulkan.find("spirv.module @UnitShader") != std::string::npos,
         "Vulkan backend emits textual SPIR-V module skeleton");
  expect(vulkan.find("spirv.EntryPoint Vertex @vertex_main \"main\"") !=
             std::string::npos,
         "Vulkan backend emits vertex entry point skeleton");
  expect(vulkan.find("crossgl.module @UnitShader") != std::string::npos,
         "Vulkan placeholder includes CrossGL IR");

  const std::string directx =
      crossgl::printBackendIR(module, crossgl::TargetKind::DirectX);
  expect(directx.find("backend lowering for directx") != std::string::npos,
         "DirectX backend reports planned lowering");
  expect(directx.find("crossgl.module @UnitShader") != std::string::npos,
         "DirectX placeholder includes CrossGL IR");

  const std::string opengl =
      crossgl::printBackendIR(module, crossgl::TargetKind::OpenGL);
  expect(opengl.find("backend lowering for opengl") != std::string::npos,
         "OpenGL backend reports planned lowering");
  expect(opengl.find("crossgl.module @UnitShader") != std::string::npos,
         "OpenGL placeholder includes CrossGL IR");
}

void testDirectXOpenGLComputeBackendScaffolds() {
  constexpr std::string_view source = R"(
shader ComputeBackendScaffoldShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values;
    void main() {
      float x = 1.0 + 2.0;
      values[0] = x;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "compute backend scaffold source builds HIR");
  if (!hir) {
    return;
  }

  const std::string directx =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::DirectX);
  expect(directx.find("RWStructuredBuffer<float> values : register(u0, "
                      "space0);") != std::string::npos,
         "DirectX backend scaffold emits storage buffer binding");
  expect(directx.find("[numthreads(1, 1, 1)]") != std::string::npos,
         "DirectX backend scaffold emits threadgroup size");
  expect(directx.find("void compute_main(uint3 crossgl_GlobalInvocationID : "
                      "SV_DispatchThreadID)") != std::string::npos,
         "DirectX backend scaffold emits compute entry point");
  expect(directx.find("float x = 1.0 + 2.0;") != std::string::npos &&
             directx.find("values[0] = x;") != std::string::npos,
         "DirectX backend scaffold emits straight-line body");
  expect(directx.find("crossgl.module @ComputeBackendScaffoldShader") !=
             std::string::npos,
         "DirectX backend scaffold keeps CrossGL IR appendix");

  const crossgl::ReflectionDocument scaffoldDirectXReflection =
      crossgl::buildReflectionDocument(*hir, crossgl::TargetKind::DirectX,
                                       "/tmp/ComputeBackendScaffoldShader.dxil");
  const auto *scaffoldDirectXValues =
      findTargetResourceBinding(scaffoldDirectXReflection, "values");
  expect(scaffoldDirectXValues != nullptr &&
             scaffoldDirectXValues->descriptorType == "UAV" &&
             scaffoldDirectXValues->hlslType.has_value() &&
             *scaffoldDirectXValues->hlslType == "RWStructuredBuffer<float>",
         "DirectX reflection records scalar storage-buffer HLSL type");

  const std::string opengl =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::OpenGL);
  expect(opengl.find("#version 450") != std::string::npos,
         "OpenGL backend scaffold emits GLSL version");
  expect(opengl.find("layout(local_size_x = 1, local_size_y = 1, "
                     "local_size_z = 1) in;") != std::string::npos,
         "OpenGL backend scaffold emits local size");
  expect(opengl.find("// CrossGL set 0, binding 0") != std::string::npos &&
             opengl.find("layout(binding = 0, std430) buffer "
                         "values_Buffer") != std::string::npos,
         "OpenGL backend scaffold emits std430 storage buffer binding");
  expect(opengl.find("float values[];") != std::string::npos &&
             opengl.find("values[0] = x;") != std::string::npos,
         "OpenGL backend scaffold emits straight-line body");
  expect(opengl.find("crossgl.module @ComputeBackendScaffoldShader") !=
             std::string::npos,
         "OpenGL backend scaffold keeps CrossGL IR appendix");

  const std::vector<crossgl::TargetCapability> directxMissing =
      crossgl::missingTargetCapabilities(*hir, crossgl::TargetKind::DirectX);
  expect(!hasCapability(directxMissing, crossgl::TargetKind::DirectX,
                        "backend", "hlsl-lowering"),
         "DirectX satisfied textual lowering is removed from missing capabilities");
  expect(!hasCapability(directxMissing, crossgl::TargetKind::DirectX, "stage",
                        "compute-kernel"),
         "DirectX satisfied compute stage is removed from missing capabilities");
  expect(hasCapability(directxMissing, crossgl::TargetKind::DirectX,
                       "backend", "native-dxil-package"),
         "DirectX native package emission remains a missing capability");

  const std::vector<crossgl::TargetCapability> openglMissing =
      crossgl::missingTargetCapabilities(*hir, crossgl::TargetKind::OpenGL);
  expect(!hasCapability(openglMissing, crossgl::TargetKind::OpenGL, "backend",
                        "glsl-lowering"),
         "OpenGL satisfied textual lowering is removed from missing capabilities");
  expect(hasCapability(openglMissing, crossgl::TargetKind::OpenGL, "backend",
                       "native-glsl-package"),
         "OpenGL native package emission remains a missing capability");

  constexpr std::string_view vectorSource = R"(
shader ComputeVectorBackendScaffoldShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer vec4* values;
    void main() {
      vec4 color = values[0];
      vec4 lifted = color + vec4(0.5, 0.5, 0.5, 0.0);
      values[1] = lifted;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> vectorHir = parseHIR(vectorSource);
  expect(vectorHir.has_value(), "vector backend scaffold source builds HIR");
  if (!vectorHir) {
    return;
  }

  const std::string vectorDirectX =
      crossgl::printBackendIR(*vectorHir, crossgl::TargetKind::DirectX);
  expect(vectorDirectX.find("RWStructuredBuffer<float4> values") !=
             std::string::npos,
         "DirectX backend scaffold emits vector storage buffer binding");
  expect(vectorDirectX.find("float4 color = values[0];") != std::string::npos &&
             vectorDirectX.find(
                 "float4 lifted = color + float4(0.5, 0.5, 0.5, 0.0);") !=
                 std::string::npos &&
             vectorDirectX.find("values[1] = lifted;") != std::string::npos,
         "DirectX backend scaffold emits vector load/local/store body");

  const crossgl::ReflectionDocument vectorDirectXReflection =
      crossgl::buildReflectionDocument(
          *vectorHir, crossgl::TargetKind::DirectX,
          "/tmp/ComputeVectorBackendScaffoldShader.dxil");
  const auto *vectorDirectXValues =
      findTargetResourceBinding(vectorDirectXReflection, "values");
  expect(vectorDirectXValues != nullptr &&
             vectorDirectXValues->descriptorType == "UAV" &&
             vectorDirectXValues->hlslType.has_value() &&
             *vectorDirectXValues->hlslType == "RWStructuredBuffer<float4>",
         "DirectX reflection records vector storage-buffer HLSL type");

  const std::string vectorOpenGL =
      crossgl::printBackendIR(*vectorHir, crossgl::TargetKind::OpenGL);
  expect(vectorOpenGL.find("vec4 values[];") != std::string::npos,
         "OpenGL backend scaffold emits vector storage buffer binding");
  expect(vectorOpenGL.find("vec4 color = values[0];") != std::string::npos &&
             vectorOpenGL.find(
                 "vec4 lifted = color + vec4(0.5, 0.5, 0.5, 0.0);") !=
                 std::string::npos &&
             vectorOpenGL.find("values[1] = lifted;") != std::string::npos,
         "OpenGL backend scaffold emits vector load/local/store body");

  const std::vector<crossgl::TargetCapability> vectorDirectXMissing =
      crossgl::missingTargetCapabilities(*vectorHir,
                                         crossgl::TargetKind::DirectX);
  expect(!hasCapability(vectorDirectXMissing, crossgl::TargetKind::DirectX,
                        "layout", "vector-storage-buffer"),
         "DirectX vector storage-buffer scaffold satisfies layout capability");
  expect(!hasCapability(vectorDirectXMissing, crossgl::TargetKind::DirectX,
                        "operation", "storage-buffer-read"),
         "DirectX scaffold satisfies storage-buffer read capability");
  expect(!hasCapability(vectorDirectXMissing, crossgl::TargetKind::DirectX,
                        "operation", "storage-buffer-write"),
         "DirectX scaffold satisfies storage-buffer write capability");
  expect(!hasCapability(vectorDirectXMissing, crossgl::TargetKind::DirectX,
                        "operation", "vector-constructor"),
         "DirectX scaffold satisfies vector constructor capability");
  expect(!hasCapability(vectorDirectXMissing, crossgl::TargetKind::DirectX,
                        "operation", "vector-arithmetic"),
         "DirectX scaffold satisfies vector arithmetic capability");

  const std::vector<crossgl::TargetCapability> vectorOpenGLMissing =
      crossgl::missingTargetCapabilities(*vectorHir,
                                         crossgl::TargetKind::OpenGL);
  expect(!hasCapability(vectorOpenGLMissing, crossgl::TargetKind::OpenGL,
                        "operation", "storage-buffer-read"),
         "OpenGL scaffold satisfies storage-buffer read capability");
  expect(!hasCapability(vectorOpenGLMissing, crossgl::TargetKind::OpenGL,
                        "operation", "vector-arithmetic"),
         "OpenGL scaffold satisfies vector arithmetic capability");

  constexpr std::string_view readModifySource = R"(
shader ComputeReadModifyBackendScaffoldShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values;
    void main() {
      values[0] = values[0] + 1.0;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> readModifyHir =
      parseHIR(readModifySource);
  expect(readModifyHir.has_value(),
         "read-modify backend scaffold source builds HIR");
  if (!readModifyHir) {
    return;
  }
  const std::string readModifyDirectX =
      crossgl::printBackendIR(*readModifyHir, crossgl::TargetKind::DirectX);
  const std::string readModifyOpenGL =
      crossgl::printBackendIR(*readModifyHir, crossgl::TargetKind::OpenGL);
  expect(readModifyDirectX.find("values[0] = values[0] + 1.0;") !=
             std::string::npos,
         "DirectX backend scaffold emits read-modify-write body");
  expect(readModifyOpenGL.find("values[0] = values[0] + 1.0;") !=
             std::string::npos,
         "OpenGL backend scaffold emits read-modify-write body");

  constexpr std::string_view ifSource = R"(
shader ComputeIfBackendScaffoldShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values;
    void main() {
      float x = values[0];
      float y = 0.0;
      if (x > 0.0) {
        float scaled = x * 2.0;
        y = scaled;
      } else {
        y = -x;
      }
      values[1] = y;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> ifHir = parseHIR(ifSource);
  expect(ifHir.has_value(), "if backend scaffold source builds HIR");
  if (!ifHir) {
    return;
  }

  const std::string ifDirectX =
      crossgl::printBackendIR(*ifHir, crossgl::TargetKind::DirectX);
  expect(ifDirectX.find("if (x > 0.0) {") != std::string::npos &&
             ifDirectX.find("float scaled = x * 2.0;") != std::string::npos &&
             ifDirectX.find("} else {") != std::string::npos &&
             ifDirectX.find("y = -x;") != std::string::npos,
         "DirectX backend scaffold emits structured if/else body");

  const std::string ifOpenGL =
      crossgl::printBackendIR(*ifHir, crossgl::TargetKind::OpenGL);
  expect(ifOpenGL.find("if (x > 0.0) {") != std::string::npos &&
             ifOpenGL.find("float scaled = x * 2.0;") != std::string::npos &&
             ifOpenGL.find("} else {") != std::string::npos &&
             ifOpenGL.find("values[1] = y;") != std::string::npos,
         "OpenGL backend scaffold emits structured if/else body");

  const std::vector<crossgl::TargetCapability> ifDirectXMissing =
      crossgl::missingTargetCapabilities(*ifHir, crossgl::TargetKind::DirectX);
  expect(!hasCapability(ifDirectXMissing, crossgl::TargetKind::DirectX,
                        "controlFlow", "structured-selection"),
         "DirectX if scaffold satisfies structured-selection capability");

  const std::vector<crossgl::TargetCapability> ifOpenGLMissing =
      crossgl::missingTargetCapabilities(*ifHir, crossgl::TargetKind::OpenGL);
  expect(!hasCapability(ifOpenGLMissing, crossgl::TargetKind::OpenGL,
                        "controlFlow", "structured-selection"),
         "OpenGL if scaffold satisfies structured-selection capability");

  constexpr std::string_view selectSource = R"(
shader ComputeSelectOpenGLScaffoldShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values;
    void main() {
      float x = values[0];
      float selected = x > 0.0 ? x : -x;
      values[1] = selected;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> selectHir = parseHIR(selectSource);
  expect(selectHir.has_value(), "select scaffold source builds HIR");
  if (!selectHir) {
    return;
  }

  expect(crossgl::directxTextualBackendSupported(*selectHir),
         "DirectX textual backend supports dynamic select expressions");
  const std::string selectDirectX = crossgl::generateDirectXSource(*selectHir);
  expect(selectDirectX.find("float selected = (x > 0.0 ? x : -x);") !=
                 std::string::npos &&
             selectDirectX.find("values[1] = selected;") != std::string::npos,
         "DirectX backend lowers select expressions as HLSL ternaries");

  const std::vector<crossgl::TargetCapability> selectDirectXMissing =
      crossgl::missingTargetCapabilities(*selectHir,
                                         crossgl::TargetKind::DirectX);
  expect(!hasCapability(selectDirectXMissing, crossgl::TargetKind::DirectX,
                        "backend", "hlsl-lowering"),
         "DirectX select scaffold satisfies HLSL lowering");

  expect(crossgl::openglTextualBackendSupported(*selectHir),
         "OpenGL textual backend supports dynamic select expressions");
  const std::string selectOpenGL = crossgl::generateOpenGLSource(*selectHir);
  expect(selectOpenGL.find("float selected = (x > 0.0 ? x : -x);") !=
                 std::string::npos &&
             selectOpenGL.find("values[1] = selected;") != std::string::npos,
         "OpenGL backend lowers select expressions as GLSL ternaries");

  const std::vector<crossgl::TargetCapability> selectOpenGLMissing =
      crossgl::missingTargetCapabilities(*selectHir,
                                         crossgl::TargetKind::OpenGL);
  expect(!hasCapability(selectOpenGLMissing, crossgl::TargetKind::OpenGL,
                        "backend", "glsl-lowering"),
         "OpenGL select scaffold satisfies GLSL lowering");

  constexpr std::string_view loopSource = R"(
shader ComputeLoopBackendScaffoldShader {
  const int STEP = 2;
  const int SELECTED_STEP = true ? STEP : 1;

  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values;
    void main() {
      int stride = SELECTED_STEP;
      for (int i = 0; i < 8; i += stride) {
        float x = values[i];
        values[i] = x + 1.0;
      }
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> loopHir = parseHIR(loopSource);
  expect(loopHir.has_value(), "loop backend scaffold source builds HIR");
  if (!loopHir) {
    return;
  }

  const std::string loopDirectX =
      crossgl::printBackendIR(*loopHir, crossgl::TargetKind::DirectX);
  expect(loopDirectX.find("static const int STEP = 2;") !=
                 std::string::npos &&
             loopDirectX.find("static const int SELECTED_STEP = 2;") !=
                 std::string::npos &&
             loopDirectX.find("for (int i = 0; i < 8; i+=stride)") !=
                 std::string::npos &&
             loopDirectX.find("values[i] = x + 1.0;") != std::string::npos,
         "DirectX backend scaffold emits structured for loop and constants");

  const std::string loopOpenGL =
      crossgl::printBackendIR(*loopHir, crossgl::TargetKind::OpenGL);
  expect(loopOpenGL.find("const int STEP = 2;") != std::string::npos &&
             loopOpenGL.find("const int SELECTED_STEP = 2;") !=
                 std::string::npos &&
             loopOpenGL.find("for (int i = 0; i < 8; i+=stride)") !=
                 std::string::npos &&
             loopOpenGL.find("float x = values[i];") != std::string::npos,
         "OpenGL backend scaffold emits structured for loop and constants");

  const std::vector<crossgl::TargetCapability> loopDirectXMissing =
      crossgl::missingTargetCapabilities(*loopHir, crossgl::TargetKind::DirectX);
  expect(!hasCapability(loopDirectXMissing, crossgl::TargetKind::DirectX,
                        "controlFlow", "structured-loop"),
         "DirectX loop scaffold satisfies structured-loop capability");

  const std::vector<crossgl::TargetCapability> loopOpenGLMissing =
      crossgl::missingTargetCapabilities(*loopHir, crossgl::TargetKind::OpenGL);
  expect(!hasCapability(loopOpenGLMissing, crossgl::TargetKind::OpenGL,
                        "controlFlow", "structured-loop"),
         "OpenGL loop scaffold satisfies structured-loop capability");

  constexpr std::string_view textureLodSource = R"(
shader ComputeTextureLodBackendScaffoldShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer vec4* values;
    layout(set = 0, binding = 2) uniform sampler2D colorMap;
    layout(set = 0, binding = 5) sampler linearSampler;
    void main() {
      vec4 color = textureLod(colorMap, linearSampler, vec2(0.25, 0.75), 1.0);
      values[0] = color;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> textureLodHir =
      parseHIR(textureLodSource);
  expect(textureLodHir.has_value(),
         "textureLod backend scaffold source builds HIR");
  if (!textureLodHir) {
    return;
  }

  const std::string textureLodDirectX =
      crossgl::printBackendIR(*textureLodHir, crossgl::TargetKind::DirectX);
  expect(textureLodDirectX.find(
             "Texture2D<float4> colorMap : register(t2, space0);") !=
                 std::string::npos &&
             textureLodDirectX.find(
                 "SamplerState linearSampler : register(s5, space0);") !=
                 std::string::npos &&
             textureLodDirectX.find(
                 "float4 color = colorMap.SampleLevel(linearSampler, "
                 "float2(0.25, 0.75), 1.0);") != std::string::npos,
         "DirectX backend scaffold emits explicit LOD texture sampling");

  const std::string textureLodOpenGL =
      crossgl::printBackendIR(*textureLodHir, crossgl::TargetKind::OpenGL);
  expect(textureLodOpenGL.find("layout(binding = 2) uniform texture2D "
                               "colorMap;") != std::string::npos &&
             textureLodOpenGL.find("layout(binding = 5) uniform sampler "
                                   "linearSampler;") != std::string::npos &&
             textureLodOpenGL.find(
                 "vec4 color = textureLod(sampler2D(colorMap, linearSampler), "
                 "vec2(0.25, 0.75), 1.0);") != std::string::npos,
         "OpenGL backend scaffold emits explicit LOD texture sampling");

  const std::vector<crossgl::TargetCapability> textureDirectXMissing =
      crossgl::missingTargetCapabilities(*textureLodHir,
                                         crossgl::TargetKind::DirectX);
  expect(!hasCapability(textureDirectXMissing, crossgl::TargetKind::DirectX,
                        "resource", "sampled-texture") &&
             !hasCapability(textureDirectXMissing, crossgl::TargetKind::DirectX,
                            "resource", "sampler-state") &&
             !hasCapability(textureDirectXMissing, crossgl::TargetKind::DirectX,
                            "operation", "texture-explicit-lod"),
         "DirectX textureLod scaffold satisfies texture resource capabilities");

  const std::vector<crossgl::TargetCapability> textureOpenGLMissing =
      crossgl::missingTargetCapabilities(*textureLodHir,
                                         crossgl::TargetKind::OpenGL);
  expect(!hasCapability(textureOpenGLMissing, crossgl::TargetKind::OpenGL,
                        "operation", "texture-sample") &&
             !hasCapability(textureOpenGLMissing, crossgl::TargetKind::OpenGL,
                            "operation", "texture-explicit-lod"),
         "OpenGL textureLod scaffold satisfies texture sampling capabilities");
}

void testGraphicsABIIOContractTextBackends() {
  constexpr std::string_view source = R"(
shader GraphicsABIIOContractShader {
  struct Transform {
    vec4 offset;
    vec4 tint;
  }

  struct Material {
    vec4 baseColor;
  }

  struct VertexInput {
    vec3 position;
    vec2 texCoord;
  }

  struct VertexOutput {
    vec2 uv;
    vec4 tint;
    vec4 position;
  }

  struct FragmentInput {
    vec2 uv;
    vec4 tint;
  }

  struct FragmentOutput {
    vec4 color;
  }

  vertex {
    layout(set = 0, binding = 0) uniform Transform transform;

    VertexOutput main(VertexInput input) {
      VertexOutput output;
      output.uv = input.texCoord;
      output.tint = transform.tint;
      output.position = vec4(input.position + transform.offset.xyz, 1.0);
      return output;
    }
  }

  fragment {
    layout(set = 0, binding = 1) uniform Material material;
    layout(set = 0, binding = 2) uniform sampler2D colorMap;
    layout(set = 0, binding = 3) sampler linearSampler;

    FragmentOutput main(FragmentInput input) {
      FragmentOutput output;
      vec4 sampled = textureLod(colorMap, linearSampler, input.uv, 0.0);
      output.color = sampled * input.tint * material.baseColor;
      return output;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "graphics ABI IO contract fixture builds HIR");
  if (!hir) {
    return;
  }

  const std::string opengl = crossgl::generateOpenGLSource(*hir);
  expect(
      containsInOrder(opengl,
                      {"layout(location = 0) in vec3 crossgl_attr_position;",
                       "layout(location = 1) in vec2 crossgl_attr_texCoord;",
                       "layout(location = 0) out vec2 crossgl_varying_uv;",
                       "layout(location = 1) out vec4 crossgl_varying_tint;"}),
      "OpenGL graphics ABI emits deterministic vertex input and varying "
      "locations");
  expect(containsInOrder(opengl,
                         {"gl_Position = crossgl_vertex_output.position;",
                          "layout(location = 0) in vec2 crossgl_varying_uv;",
                          "layout(location = 1) in vec4 crossgl_varying_tint;",
                          "layout(location = 0) out vec4 crossgl_out_color;"}),
         "OpenGL graphics ABI emits vertex position builtin and fragment IO "
         "locations");

  const std::string directx = crossgl::generateDirectXSource(*hir);
  expect(containsInOrder(directx,
                         {"struct crossgl_vertex_input {",
                          "float3 position : POSITION0;",
                          "float2 texCoord : TEXCOORD1;",
                          "struct crossgl_vertex_output {",
                          "float2 uv : TEXCOORD0;",
                          "float4 tint : TEXCOORD1;",
                          "float4 position : SV_Position;"}),
         "DirectX graphics ABI emits deterministic vertex input, varying, and "
         "position semantics");
  expect(containsInOrder(directx,
                         {"struct crossgl_fragment_input {",
                          "float2 uv : TEXCOORD0;",
                          "float4 tint : TEXCOORD1;",
                          "struct crossgl_fragment_output {",
                          "float4 color : SV_Target0;"}),
         "DirectX graphics ABI emits deterministic fragment input and output "
         "semantics");

  constexpr std::string_view simpleSource = R"(
shader GraphicsSimpleIOContractShader {
  struct VertexInput {
    vec3 position;
    vec2 texCoord;
  }

  struct VertexOutput {
    vec2 uv;
    vec4 position;
  }

  struct FragmentInput {
    vec2 uv;
  }

  struct FragmentOutput {
    vec4 color;
  }

  vertex {
    VertexOutput main(VertexInput input) {
      VertexOutput output;
      output.uv = input.texCoord;
      output.position = vec4(input.position, 1.0);
      return output;
    }
  }

  fragment {
    FragmentOutput main(FragmentInput input) {
      FragmentOutput output;
      output.color = vec4(input.uv, 0.0, 1.0);
      return output;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> simpleHir = parseHIR(simpleSource);
  expect(simpleHir.has_value(),
         "simple graphics ABI IO contract fixture builds HIR");
  if (!simpleHir) {
    return;
  }

  const std::string metal = crossgl::generateMetalSource(*simpleHir);
  expect(containsInOrder(metal,
                         {"struct VertexInput {",
                          "float3 position [[attribute(0)]];",
                          "float2 texCoord [[attribute(1)]];",
                          "struct VertexOutput {",
                          "float2 uv;",
                          "float4 position [[position]];"}),
         "Metal graphics ABI emits deterministic vertex attributes, varying "
         "field, and position builtin");
  expect(containsInOrder(metal,
                         {"struct FragmentOutput {",
                          "float4 color [[color(0)]];",
                          "vertex VertexOutput vertex_main("
                          "VertexInput input [[stage_in]])",
                          "fragment FragmentOutput fragment_main("
                          "FragmentInput input [[stage_in]])"}),
         "Metal graphics ABI emits stage_in inputs and fragment color output");

  crossgl::DiagnosticEngine vulkanDiagnostics;
  const std::string vulkanAssembly =
      crossgl::generateVulkanPrototypeAssembly(*simpleHir, vulkanDiagnostics);
  expect(!vulkanAssembly.empty() && !vulkanDiagnostics.hasErrors(),
         "simple graphics ABI IO contract Vulkan prototype assembly has no "
         "diagnostics");
  expect(vulkanAssembly.find("OpEntryPoint Vertex") != std::string::npos &&
             vulkanAssembly.find("OpEntryPoint Fragment") != std::string::npos,
         "Vulkan graphics ABI emits vertex and fragment entry points");
  expect(vulkanAssembly.find("\"crossgl_attr_position\"") !=
                 std::string::npos &&
             vulkanAssembly.find("\"crossgl_attr_texCoord\"") !=
                 std::string::npos &&
             vulkanAssembly.find("\"crossgl_varying_uv\"") !=
                 std::string::npos &&
             vulkanAssembly.find("\"crossgl_out_color\"") !=
                 std::string::npos,
         "Vulkan graphics ABI emits deterministic generated IO names");
  expect(vulkanAssembly.find("OpDecorate ") != std::string::npos &&
             vulkanAssembly.find(" Location 0") != std::string::npos &&
             vulkanAssembly.find(" Location 1") != std::string::npos &&
             vulkanAssembly.find("BuiltIn Position") != std::string::npos,
         "Vulkan graphics ABI emits location decorations and position builtin");
}

void testBackendIntrinsicCallLowering() {
  constexpr std::string_view source = R"(
shader ComputeIntrinsicBackendShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* scalars;
    layout(set = 0, binding = 1) buffer vec4* vectors;
    layout(set = 0, binding = 2) buffer vec3* axes;
    void main() {
      float slope = atan(scalars[0]);
      float angle = atan(scalars[0], scalars[1]);
      vec4 vectorAngle = atan(vectors[0], vectors[1]);
      float cosine = cos(scalars[2]);
      float tangent = tan(scalars[3]);
      float floored = floor(scalars[0]);
      float ceiled = ceil(scalars[1]);
      float clamped = clamp(cosine + tangent, 0.0, 1.0);
      vec3 crossed = cross(axes[0], axes[1]);
      float gap = distance(axes[0], axes[1]);
      vec3 limited = clamp(crossed, -1.0, 1.0);
      scalars[2] = angle + slope + clamped + gap + floored + ceiled;
      vectors[2] = vectorAngle;
      axes[2] = limited;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "intrinsic backend source builds HIR");
  if (!hir) {
    return;
  }

  const std::vector<crossgl::HIRStatement> &body =
      hir->stages.front().functions.front().body;
  expect(body.size() >= 11 &&
             body[0].value.kind == crossgl::HIRExpressionKind::Call &&
             body[1].value.kind == crossgl::HIRExpressionKind::Call &&
             body[2].value.kind == crossgl::HIRExpressionKind::Call &&
             body[3].value.kind == crossgl::HIRExpressionKind::Call &&
             body[7].value.kind == crossgl::HIRExpressionKind::Call &&
             body[8].value.kind == crossgl::HIRExpressionKind::Call &&
             body[9].value.kind == crossgl::HIRExpressionKind::Call,
         "intrinsic backend source preserves call expressions");
  if (body.size() < 11) {
    return;
  }

  expect(crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::DirectX,
                                              body[0].value) == "atan" &&
             crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::DirectX,
                                                  body[1].value) == "atan2" &&
             crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::Metal,
                                                  body[1].value) == "atan2" &&
             crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::OpenGL,
                                                  body[1].value) == "atan",
         "backend intrinsic mapper renames only target-specific atan overloads");
  expect(crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::DirectX,
                                              body[3].value) == "cos" &&
             crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::OpenGL,
                                                  body[7].value) == "clamp" &&
             crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::Metal,
                                                  body[8].value) == "cross" &&
             crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::DirectX,
                                                  body[9].value) == "distance",
         "backend intrinsic mapper exposes shared compat intrinsic names");

  crossgl::HIRExpression invalidMin =
      crossgl::HIRExpression{crossgl::HIRExpressionKind::Call,
                             crossgl::HIRType{"float", std::nullopt}, "min"};
  invalidMin.children.push_back(
      crossgl::HIRExpression{crossgl::HIRExpressionKind::Literal,
                             crossgl::HIRType{"float", std::nullopt}, "0.0"});
  invalidMin.children.push_back(
      crossgl::HIRExpression{crossgl::HIRExpressionKind::Literal,
                             crossgl::HIRType{"vec3", std::nullopt}, "0.0"});
  crossgl::HIRExpression invalidDot =
      crossgl::HIRExpression{crossgl::HIRExpressionKind::Call,
                             crossgl::HIRType{"float", std::nullopt}, "dot"};
  invalidDot.children.push_back(
      crossgl::HIRExpression{crossgl::HIRExpressionKind::Literal,
                             crossgl::HIRType{"vec2", std::nullopt}, "0.0"});
  invalidDot.children.push_back(
      crossgl::HIRExpression{crossgl::HIRExpressionKind::Literal,
                             crossgl::HIRType{"vec3", std::nullopt}, "0.0"});
  expect(!crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::DirectX,
                                               invalidMin)
              .has_value() &&
             !crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::OpenGL,
                                                   invalidDot)
                  .has_value(),
         "backend intrinsic mapper rejects invalid intrinsic signatures");

  auto intrinsicCall = [](std::string name,
                          std::vector<crossgl::HIRType> argumentTypes) {
    crossgl::HIRExpression call{crossgl::HIRExpressionKind::Call,
                                crossgl::HIRType{"float", std::nullopt},
                                std::move(name)};
    for (const crossgl::HIRType &argumentType : argumentTypes) {
      call.children.push_back(
          crossgl::HIRExpression{crossgl::HIRExpressionKind::Literal,
                                 argumentType, "0.0"});
    }
    return call;
  };
  const crossgl::HIRExpression scalarLength =
      intrinsicCall("length", {crossgl::HIRType{"float", std::nullopt}});
  const crossgl::HIRExpression vectorLength =
      intrinsicCall("length", {crossgl::HIRType{"vec4", std::nullopt}});
  expect(crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::DirectX,
                                              scalarLength) == "length" &&
             crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::OpenGL,
                                                  scalarLength) == "length" &&
             crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::Metal,
                                                  scalarLength) == "length" &&
             crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::DirectX,
                                                  vectorLength) == "length" &&
             crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::OpenGL,
                                                  vectorLength) == "length" &&
             crossgl::backendIntrinsicNameForCall(crossgl::TargetKind::Metal,
                                                  vectorLength) == "length",
         "backend intrinsic mapper treats scalar and vector length as shared "
         "valid intrinsic calls");

  expect(crossgl::directxTextualBackendSupported(*hir) &&
             crossgl::openglTextualBackendSupported(*hir),
         "textual backends accept known scalar/vector intrinsic calls");

  const std::string directx =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::DirectX);
  expect(directx.find("float slope = atan(scalars[0]);") !=
                 std::string::npos &&
             directx.find("float angle = atan2(scalars[0], scalars[1]);") !=
                 std::string::npos &&
             directx.find(
                 "float4 vectorAngle = atan2(vectors[0], vectors[1]);") !=
                 std::string::npos,
         "DirectX backend lowers one-arg atan directly and two-arg atan as atan2");
  expect(directx.find("float cosine = cos(scalars[2]);") !=
                 std::string::npos &&
             directx.find("float tangent = tan(scalars[3]);") !=
                 std::string::npos &&
             directx.find("float floored = floor(scalars[0]);") !=
                 std::string::npos &&
             directx.find("float ceiled = ceil(scalars[1]);") !=
                 std::string::npos &&
             directx.find("float clamped = clamp(") != std::string::npos &&
             directx.find("float3 crossed = cross(axes[0], axes[1]);") !=
                 std::string::npos &&
             directx.find("float gap = distance(axes[0], axes[1]);") !=
                 std::string::npos,
         "DirectX backend dumps compat intrinsic calls with HLSL names");

  const std::string opengl =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::OpenGL);
  expect(opengl.find("float slope = atan(scalars[0]);") != std::string::npos &&
             opengl.find("float angle = atan(scalars[0], scalars[1]);") !=
                 std::string::npos &&
             opengl.find(
                 "vec4 vectorAngle = atan(vectors[0], vectors[1]);") !=
                 std::string::npos,
         "OpenGL backend keeps GLSL atan overload spelling");
  expect(opengl.find("float cosine = cos(scalars[2]);") !=
                 std::string::npos &&
             opengl.find("float tangent = tan(scalars[3]);") !=
                 std::string::npos &&
             opengl.find("float floored = floor(scalars[0]);") !=
                 std::string::npos &&
             opengl.find("float ceiled = ceil(scalars[1]);") !=
                 std::string::npos &&
             opengl.find("float clamped = clamp(") != std::string::npos &&
             opengl.find("vec3 crossed = cross(axes[0], axes[1]);") !=
                 std::string::npos &&
             opengl.find("float gap = distance(axes[0], axes[1]);") !=
                 std::string::npos,
         "OpenGL backend dumps compat intrinsic calls with GLSL names");

  const std::string metal = crossgl::generateMetalSource(*hir);
  expect(metal.find("float slope = atan(scalars[0]);") != std::string::npos &&
             metal.find("float angle = atan2(scalars[0], scalars[1]);") !=
                 std::string::npos &&
             metal.find(
                 "float4 vectorAngle = atan2(vectors[0], vectors[1]);") !=
                 std::string::npos,
         "Metal backend lowers two-arg atan as atan2");
  expect(metal.find("float cosine = cos(scalars[2]);") != std::string::npos &&
             metal.find("float tangent = tan(scalars[3]);") !=
                 std::string::npos &&
             metal.find("float floored = floor(scalars[0]);") !=
                 std::string::npos &&
             metal.find("float ceiled = ceil(scalars[1]);") !=
                 std::string::npos &&
             metal.find("float clamped = clamp(") != std::string::npos &&
             metal.find("float3 crossed = cross(axes[0], axes[1]);") !=
                 std::string::npos &&
             metal.find("float gap = distance(axes[0], axes[1]);") !=
                 std::string::npos,
         "Metal backend dumps compat intrinsic calls with MSL names");

  const std::string vulkan =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::Vulkan);
  expect(vulkan.find("cos(scalars[2])") != std::string::npos &&
             vulkan.find("clamp(") != std::string::npos &&
             vulkan.find("cross(axes[0], axes[1])") != std::string::npos &&
             vulkan.find("distance(axes[0], axes[1])") != std::string::npos,
         "Vulkan backend dump preserves compat intrinsic source shape");
}

void testDirectXOpenGLSourcePackages() {
  constexpr std::string_view source = R"(
shader ComputeSourcePackageShader {
  const vec3 PACKAGE_AXIS = vec3(1.0, 2.0, 2.0);
  const vec2 PACKAGE_DIR = vec2(3.0, 4.0);
  compute {
    layout(local_size_x = 4, local_size_y = 1, local_size_z = 1) in;
    layout(set = 1, binding = 2) buffer vec4* values;
    void main() {
      vec4 color = values[0];
      float axisDot = dot(PACKAGE_AXIS, PACKAGE_AXIS);
      float axisLength = length(PACKAGE_AXIS);
      float rootedAxisDot = sqrt(axisDot);
      float foldedBinary = (2.0 + 3.0) * 4.0;
      float foldedSelect = false ? values[0].x : 7.0;
      float axisZ = PACKAGE_AXIS.z;
      vec2 dirYX = PACKAGE_DIR.yx;
      vec2 normalizedDir = normalize(PACKAGE_DIR);
      float normalizedLength = length(normalizedDir);
      float normalizedY = normalizedDir.y;
      float selectedColor = true ? color.x : 0.0;
      vec2 reflectedDir = reflect(vec2(1.0, -1.0), vec2(0.0, 1.0));
      vec3 mixedAxis = mix(vec3(0.0, 2.0, 4.0),
                           vec3(10.0, 6.0, 8.0), 0.5);
      float dirLength = length(normalize(PACKAGE_DIR));
      float reflectDot = dot(reflect(vec2(1.0, -1.0), vec2(0.0, 1.0)),
                             vec2(1.0, 1.0));
      float mixDot = dot(mix(vec3(0.0, 2.0, 4.0),
                             vec3(10.0, 6.0, 8.0), 0.5),
                         vec3(1.0, 1.0, 1.0));
      vec4 lifted = color + vec4(axisDot + dirLength,
                                 axisLength + reflectDot,
                                 mixDot,
                                 0.0);
      values[1] = lifted;
      return;
    }
  }
}
)";

  const std::filesystem::path inputPath =
      unitTestTempDirectoryPath() /
      "crossgl-directx-opengl-source-package.cgl";
  const std::filesystem::path directxOutputPath =
      unitTestTempDirectoryPath() /
      "crossgl-directx-source-package.cglb";
  const std::filesystem::path openglOutputPath =
      unitTestTempDirectoryPath() /
      "crossgl-opengl-source-package.cglb";

  std::error_code error;
  std::filesystem::remove(inputPath, error);
  std::filesystem::remove_all(directxOutputPath, error);
  std::filesystem::remove_all(openglOutputPath, error);
  {
    std::ofstream input(inputPath, std::ios::binary);
    input << source;
  }

  crossgl::CompileRequest directxRequest;
  directxRequest.inputPath = inputPath;
  directxRequest.outputPath = directxOutputPath;
  directxRequest.target = crossgl::TargetKind::DirectX;
  const crossgl::CompileResult directxResult = crossgl::compile(directxRequest);
  expect(directxResult.success,
         "DirectX textual compute subset builds a source package");

  const std::filesystem::path hlslPath =
      directxOutputPath / "backend" / "directx" /
      "ComputeSourcePackageShader.hlsl";
  const std::filesystem::path dxilPlaceholder =
      directxOutputPath / "backend" / "directx" /
      "ComputeSourcePackageShader.dxil";
  const bool dxilEmitted = std::filesystem::exists(dxilPlaceholder);
  expect(hasDiagnostic(directxResult.diagnostics, "directx.source-package-only") ||
             hasDiagnostic(directxResult.diagnostics, "directx.dxil-emitted") ||
             hasDiagnostic(directxResult.diagnostics, "directx.dxc-failed"),
         "DirectX source package records native package status diagnostic");
  expect(std::filesystem::exists(hlslPath),
         "DirectX source package writes HLSL source");
  const std::string hlsl = readTextFileOrEmpty(hlslPath);
  expect(hlsl.find("RWStructuredBuffer<float4> values : register(u2, "
                   "space1);") != std::string::npos,
         "DirectX package source records buffer register and space");
  expect(hlsl.find("[numthreads(4, 1, 1)]") != std::string::npos,
         "DirectX package source records workgroup size");
  expect(hlsl.find("static const float3 PACKAGE_AXIS = "
                   "float3(1.0, 2.0, 2.0);") != std::string::npos &&
             hlsl.find("static const float2 PACKAGE_DIR = "
                       "float2(3.0, 4.0);") != std::string::npos &&
             hlsl.find("float axisDot =") == std::string::npos &&
             hlsl.find("float axisLength =") == std::string::npos &&
             hlsl.find("float rootedAxisDot =") == std::string::npos &&
             hlsl.find("float foldedBinary =") == std::string::npos &&
             hlsl.find("float foldedSelect =") == std::string::npos &&
             hlsl.find("float axisZ =") == std::string::npos &&
             hlsl.find("float2 dirYX =") == std::string::npos &&
             hlsl.find("float2 normalizedDir =") == std::string::npos &&
             hlsl.find("float normalizedLength =") == std::string::npos &&
             hlsl.find("float normalizedY =") == std::string::npos &&
             hlsl.find("float selectedColor =") == std::string::npos &&
             hlsl.find("float2 reflectedDir =") == std::string::npos &&
             hlsl.find("float3 mixedAxis =") == std::string::npos &&
             hlsl.find("float dirLength =") == std::string::npos &&
             hlsl.find("float reflectDot =") == std::string::npos &&
             hlsl.find("float mixDot = 15;") != std::string::npos &&
             hlsl.find("float4 lifted = color + "
                       "float4(10, 5, mixDot, 0.0);") !=
                 std::string::npos,
         "DirectX package source records named vector constants, removes dead "
         "folded locals, and keeps folded values still referenced by dynamic "
         "code");

  const std::string directxManifest =
      readTextFileOrEmpty(directxOutputPath / "manifest.json");
  expect(directxManifest.find("\"backendSource\"") != std::string::npos &&
             directxManifest.find(
                 "backend/directx/ComputeSourcePackageShader.hlsl") !=
                 std::string::npos,
         "DirectX manifest records backend source");
  const std::string expectedDirectXNativeStatus =
      dxilEmitted ? "\"nativeBinaryStatus\": \"emitted\""
                  : "\"nativeBinaryStatus\": \"planned\"";
  expect(directxManifest.find(expectedDirectXNativeStatus) !=
             std::string::npos &&
             directxManifest.find(
                 "backend/directx/ComputeSourcePackageShader.dxil") !=
                 std::string::npos,
         "DirectX manifest records native binary status");
  const std::string directxDescriptor = readTextFileOrEmpty(
      directxOutputPath / "backend" / "directx" /
      "ComputeSourcePackageShader.native-artifact.json");
  expect(directxDescriptor.find(expectedDirectXNativeStatus) !=
             std::string::npos &&
             (dxilEmitted
                  ? directxDescriptor.find("\"artifactPath\"") !=
                        std::string::npos
                  : directxDescriptor.find("\"artifactPath\"") ==
                        std::string::npos),
         "DirectX native artifact descriptor consumes legalization artifact "
         "requirements for planned native binaries");
  const std::string directxReflection =
      readTextFileOrEmpty(directxOutputPath / "reflection.json");
  expect(directxReflection.find("\"target\":\"directx\"") != std::string::npos &&
             directxReflection.find(
                 "backend/directx/ComputeSourcePackageShader.dxil") !=
                 std::string::npos,
         "DirectX reflection records planned native binary path");

  crossgl::CompileRequest openglRequest;
  openglRequest.inputPath = inputPath;
  openglRequest.outputPath = openglOutputPath;
  openglRequest.target = crossgl::TargetKind::OpenGL;
  const crossgl::CompileResult openglResult = crossgl::compile(openglRequest);
  expect(openglResult.success,
         "OpenGL textual compute subset builds a source package");

  const std::filesystem::path glslPath =
      openglOutputPath / "backend" / "opengl" /
      "ComputeSourcePackageShader.comp.glsl";
  const std::filesystem::path glslPlaceholder =
      openglOutputPath / "backend" / "opengl" /
      "ComputeSourcePackageShader.glsl";
  const bool glslValidated = std::filesystem::exists(glslPlaceholder);
  expect(hasDiagnostic(openglResult.diagnostics, "opengl.source-package-only") ||
             hasDiagnostic(openglResult.diagnostics, "opengl.glsl-validated") ||
             hasDiagnostic(openglResult.diagnostics, "opengl.glslang-failed"),
         "OpenGL source package records validation status diagnostic");
  expect(std::filesystem::exists(glslPath),
         "OpenGL source package writes GLSL source");
  const std::string glsl = readTextFileOrEmpty(glslPath);
  expect(glsl.find("#version 450") != std::string::npos,
         "OpenGL package source records GLSL version");
  expect(glsl.find("layout(local_size_x = 4, local_size_y = 1, "
                   "local_size_z = 1) in;") != std::string::npos,
         "OpenGL package source records local size");
  expect(glsl.find("// CrossGL set 1, binding 2") != std::string::npos &&
             glsl.find("layout(binding = 1026, std430) buffer "
                       "values_Buffer") != std::string::npos &&
             glsl.find("vec4 values[];") != std::string::npos,
         "OpenGL package source records flattened storage buffer binding");
  expect(glsl.find("const vec3 PACKAGE_AXIS = "
                   "vec3(1.0, 2.0, 2.0);") != std::string::npos &&
             glsl.find("const vec2 PACKAGE_DIR = "
                       "vec2(3.0, 4.0);") != std::string::npos &&
             glsl.find("float axisDot =") == std::string::npos &&
             glsl.find("float axisLength =") == std::string::npos &&
             glsl.find("float rootedAxisDot =") == std::string::npos &&
             glsl.find("float foldedBinary =") == std::string::npos &&
             glsl.find("float foldedSelect =") == std::string::npos &&
             glsl.find("float axisZ =") == std::string::npos &&
             glsl.find("vec2 dirYX =") == std::string::npos &&
             glsl.find("vec2 normalizedDir =") == std::string::npos &&
             glsl.find("float normalizedLength =") == std::string::npos &&
             glsl.find("float normalizedY =") == std::string::npos &&
             glsl.find("float selectedColor =") == std::string::npos &&
             glsl.find("vec2 reflectedDir =") == std::string::npos &&
             glsl.find("vec3 mixedAxis =") == std::string::npos &&
             glsl.find("float dirLength =") == std::string::npos &&
             glsl.find("float reflectDot =") == std::string::npos &&
             glsl.find("float mixDot = 15;") != std::string::npos &&
             glsl.find("vec4 lifted = color + "
                       "vec4(10, 5, mixDot, 0.0);") !=
                 std::string::npos,
         "OpenGL package source records named vector constants, removes dead "
         "folded locals, and keeps folded values still referenced by dynamic "
         "code");

  const std::string openglManifest =
      readTextFileOrEmpty(openglOutputPath / "manifest.json");
  expect(openglManifest.find("\"backendSource\"") != std::string::npos &&
             openglManifest.find(
                 "backend/opengl/ComputeSourcePackageShader.comp.glsl") !=
                 std::string::npos,
         "OpenGL manifest records backend source");
  const std::string expectedOpenGLNativeStatus =
      glslValidated ? "\"nativeBinaryStatus\": \"validated\""
                    : "\"nativeBinaryStatus\": \"planned\"";
  expect(openglManifest.find(expectedOpenGLNativeStatus) !=
             std::string::npos &&
             openglManifest.find(
                 "backend/opengl/ComputeSourcePackageShader.glsl") !=
                 std::string::npos,
         "OpenGL manifest records native source validation status");
  const std::string openglDescriptor = readTextFileOrEmpty(
      openglOutputPath / "backend" / "opengl" /
      "ComputeSourcePackageShader.native-artifact.json");
  expect(openglDescriptor.find(expectedOpenGLNativeStatus) !=
             std::string::npos &&
             (glslValidated
                  ? openglDescriptor.find("\"artifactPath\"") !=
                        std::string::npos
                  : openglDescriptor.find("\"artifactPath\"") ==
                        std::string::npos),
         "OpenGL native artifact descriptor consumes legalization artifact "
         "requirements for planned native binaries");
  const std::string openglReflection =
      readTextFileOrEmpty(openglOutputPath / "reflection.json");
  expect(openglReflection.find("\"target\":\"opengl\"") != std::string::npos &&
             openglReflection.find(
                 "backend/opengl/ComputeSourcePackageShader.glsl") !=
                 std::string::npos,
         "OpenGL reflection records planned native binary path");
  expect(openglReflection.find("\"targetResourceBindings\"") !=
                 std::string::npos &&
             openglReflection.find("\"bindingClass\":\"storage-buffer\"") !=
                 std::string::npos &&
             openglReflection.find("\"argumentIndex\":1026") !=
                 std::string::npos,
         "OpenGL reflection records flattened target resource binding");

  std::filesystem::remove(inputPath, error);
  std::filesystem::remove_all(directxOutputPath, error);
  std::filesystem::remove_all(openglOutputPath, error);
}

void testOpenGLSourcePackageSupportPredicate() {
  constexpr std::string_view supportedSource = R"(
shader OpenGLSourcePredicateSupportedShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer vec4* values;
    void main() {
      vec4 color = values[0];
      values[1] = color + vec4(1.0);
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> supportedHir =
      parseHIR(supportedSource);
  expect(supportedHir.has_value(),
         "OpenGL source package predicate supported fixture builds HIR");
  if (supportedHir) {
    crossgl::DiagnosticEngine diagnostics;
    expect(crossgl::openGLSourcePackageSupported(*supportedHir, diagnostics),
           "OpenGL source package predicate accepts supported source package "
           "module");
    expect(!diagnostics.hasErrors() && diagnostics.diagnostics().empty(),
           "OpenGL source package predicate emits no diagnostics for supported "
           "modules");
    const crossgl::TargetPackageDecision decision =
        crossgl::targetPackageDecision(*supportedHir,
                                       crossgl::TargetKind::OpenGL);
    expect(!decision.nativeImplemented && decision.sourcePackageSupported &&
               decision.packageBuildSupported &&
               decision.packageMode == "source-package" &&
               decision.packageDecisionReason == "source-package-available" &&
               decision.packageRankScore == 1 &&
               hasCapability(decision.missingCapabilities,
                             crossgl::TargetKind::OpenGL, "backend",
                             "native-glsl-package") &&
               !hasCapability(decision.missingCapabilities,
                              crossgl::TargetKind::OpenGL, "backend",
                              "glsl-lowering"),
           "shared package decision preserves accepted OpenGL source packages");
    const crossgl::TargetLegalizationResult legalization =
        crossgl::legalizeTarget(*supportedHir, crossgl::TargetKind::OpenGL);
    const crossgl::TargetLegalizationContract contract =
        crossgl::targetLegalizationContract(legalization);
    expect(crossgl::targetLegalizationContractInvariantDiagnostics(contract)
               .empty(),
           "OpenGL source-package legalization contract satisfies shared "
           "invariants");
    expectSourcePackageProjectionFields(
        crossgl::targetLegalizationContractProjection(contract),
        crossgl::TargetKind::OpenGL, "opengl.backend.native-glsl-package",
        "opengl.toolchain.opengl-driver",
        "opengl.validation.glsl-program-validation",
        "OpenGL source-package legalization projection");
  }

  constexpr std::string_view storageBufferElementSource = R"(
shader OpenGLSourcePredicateUnsupportedStorageElementShader {
  struct Particle {
    double transform;
    float mass;
  }
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer Particle* particles;
    void main() {
      float mass = particles[0].mass;
      particles[1].mass = mass + 1.0;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> storageBufferElementHir =
      parseHIR(storageBufferElementSource);
  expect(storageBufferElementHir.has_value(),
         "OpenGL source package predicate storage element fixture builds HIR");
  if (storageBufferElementHir) {
    crossgl::DiagnosticEngine diagnostics;
    expect(!crossgl::openGLSourcePackageSupported(*storageBufferElementHir,
                                                  diagnostics),
           "OpenGL source package predicate rejects unsupported storage-buffer "
           "element type");
    expect(hasDiagnosticMessageFragment(
               diagnostics.diagnostics(),
               "opengl.unsupported-storage-buffer-element-type",
               "particles (Particle)"),
           "OpenGL source package predicate preserves storage-buffer element "
           "diagnostic ID and resource detail");
    const crossgl::TargetPackageDecision decision =
        crossgl::targetPackageDecision(*storageBufferElementHir,
                                       crossgl::TargetKind::OpenGL);
    expect(!decision.nativeImplemented && !decision.sourcePackageSupported &&
               !decision.packageBuildSupported &&
               decision.packageMode == "unsupported" &&
               decision.packageDecisionReason == "unsupported" &&
               decision.packageRankScore == 2 &&
               hasCapability(decision.missingCapabilities,
                             crossgl::TargetKind::OpenGL, "backend",
                             "glsl-lowering") &&
               hasCapability(decision.missingCapabilities,
                             crossgl::TargetKind::OpenGL, "diagnostic",
                             "opengl.unsupported-storage-buffer-element-type"),
           "shared package decision records OpenGL predicate diagnostics for "
           "unsupported source packages");
    const crossgl::TargetExplanationDocument explanation =
        crossgl::buildTargetExplanationDocument(*storageBufferElementHir);
    const auto openglRecord = std::find_if(
        explanation.targets.begin(), explanation.targets.end(),
        [](const crossgl::TargetExplanationTargetRecord &record) {
          return record.target == "opengl";
        });
    expect(openglRecord != explanation.targets.end() &&
               !openglRecord->packageBuildSupported &&
               openglRecord->packageMode == "unsupported" &&
               hasString(openglRecord->missingCapabilities,
                         "opengl.diagnostic."
                         "opengl.unsupported-storage-buffer-element-type"),
           "target explanation records OpenGL source-package rejection "
           "diagnostics");
    const crossgl::DebugMetadataDocument debugDocument =
        crossgl::buildDebugMetadataDocument(*storageBufferElementHir,
                                            crossgl::TargetKind::OpenGL);
    expect(debugDocument.targetDecision.selectedTarget == "opengl" &&
               !debugDocument.targetDecision
                    .selectedTargetPackageBuildSupported &&
               debugDocument.targetDecision.selectedTargetPackageMode ==
                   "unsupported" &&
               hasString(debugDocument.targetDecision
                             .selectedTargetMissingCapabilities,
                         "opengl.diagnostic."
                         "opengl.unsupported-storage-buffer-element-type"),
           "debug metadata records OpenGL source-package rejection diagnostics");
  }

  constexpr std::string_view shadowCompareLodSource = R"(
shader OpenGLSourcePredicateShadowLodShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values;
    layout(set = 0, binding = 2) uniform sampler2DShadow shadowMap;
    layout(set = 0, binding = 3) uniform samplerCubeShadow shadowCubes[2];
    layout(set = 0, binding = 4) sampler shadowSamplers[2];
    void main() {
      float supported =
          textureCompareLod(shadowMap, shadowSamplers[0],
                            vec2(0.5, 0.5), 0.25, 0.0);
      float unsupported =
          textureCompareLod(shadowCubes[1], shadowSamplers[0],
                            vec3(0.0, 1.0, 0.0), 0.75, 3.0);
      values[0] = supported + unsupported;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> shadowCompareLodHir =
      parseHIR(shadowCompareLodSource);
  expect(shadowCompareLodHir.has_value(),
         "OpenGL source package predicate shadow LOD fixture builds HIR");
  if (shadowCompareLodHir) {
    crossgl::DiagnosticEngine diagnostics;
    expect(crossgl::openGLSourcePackageSupported(*shadowCompareLodHir,
                                                 diagnostics),
           "OpenGL source package predicate accepts descriptor-array shadow "
           "explicit-LOD shapes");
    expect(!hasDiagnostic(
               diagnostics.diagnostics(),
               "opengl.unsupported-shadow-compare-explicit-lod-shape"),
           "OpenGL source package predicate no longer reports the old shadow "
           "explicit-LOD shape diagnostic");
    const crossgl::TargetPackageDecision decision =
        crossgl::targetPackageDecision(*shadowCompareLodHir,
                                       crossgl::TargetKind::OpenGL);
    expect(decision.sourcePackageSupported && decision.packageBuildSupported &&
               !hasCapability(decision.missingCapabilities,
                              crossgl::TargetKind::OpenGL, "diagnostic",
                              "opengl.unsupported-shadow-compare-explicit-lod-shape"),
           "shared package decision accepts OpenGL shadow explicit-LOD "
           "descriptor arrays");
  }
}

void testDirectXSourcePackageSupportPredicate() {
  constexpr std::string_view supportedSource = R"(
shader DirectXSourcePackagePredicateSupportedShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values;
    void main() {
      float value = values[0];
      values[1] = value + 1.0;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> supportedHir =
      parseHIR(supportedSource);
  expect(supportedHir.has_value(),
         "DirectX source-package support predicate supported source builds HIR");
  if (!supportedHir) {
    return;
  }

  const std::filesystem::path supportedSideEffectPath =
      unitTestTempDirectoryPath() /
      "crossgl-directx-source-package-predicate-supported-side-effect.cglb";
  std::error_code error;
  std::filesystem::remove_all(supportedSideEffectPath, error);

  crossgl::DiagnosticEngine supportedDiagnostics;
  expect(crossgl::directxSourcePackageSupported(*supportedHir,
                                                supportedDiagnostics),
         "DirectX source-package support predicate accepts source-package "
         "compute subset");
  expect(!supportedDiagnostics.hasErrors() &&
             !hasDiagnostic(supportedDiagnostics.diagnostics(),
                            "directx.source-package-only") &&
             !hasDiagnostic(supportedDiagnostics.diagnostics(),
                            "directx.dxil-emitted") &&
             !hasDiagnostic(supportedDiagnostics.diagnostics(),
                            "directx.dxc-failed"),
         "DirectX source-package support predicate emits no package or dxc "
         "diagnostics for supported shaders");
  expect(!std::filesystem::exists(supportedSideEffectPath),
         "DirectX source-package support predicate does not create package "
         "output for supported shaders");

  auto expectUnsupported =
      [](std::string_view source, std::string_view expectedCode,
         std::string_view expectedFragment, std::string_view label) {
        std::optional<crossgl::HIRModule> hir = parseHIR(source);
        expect(hir.has_value(),
               std::string(label) +
                   " DirectX predicate unsupported source builds HIR");
        if (!hir) {
          return;
        }

        crossgl::DiagnosticEngine firstDiagnostics;
        const bool firstSupported =
            crossgl::directxSourcePackageSupported(*hir, firstDiagnostics);
        crossgl::DiagnosticEngine secondDiagnostics;
        const bool secondSupported =
            crossgl::directxSourcePackageSupported(*hir, secondDiagnostics);
        const crossgl::Diagnostic *firstDiagnostic =
            findDiagnostic(firstDiagnostics.diagnostics(), expectedCode);
        const crossgl::Diagnostic *secondDiagnostic =
            findDiagnostic(secondDiagnostics.diagnostics(), expectedCode);

        expect(!firstSupported && !secondSupported,
               std::string(label) +
                   " DirectX source-package support predicate rejects "
                   "unsupported source");
        expect(firstDiagnostic != nullptr && secondDiagnostic != nullptr &&
                   firstDiagnostic->severity ==
                       crossgl::DiagnosticSeverity::Error &&
                   secondDiagnostic->severity ==
                       crossgl::DiagnosticSeverity::Error &&
                   firstDiagnostic->message == secondDiagnostic->message &&
                   firstDiagnostic->message.find(expectedFragment) !=
                       std::string::npos,
               std::string(label) +
                   " DirectX source-package support predicate preserves stable "
                   "diagnostic id and message");
        expect(!hasDiagnostic(firstDiagnostics.diagnostics(),
                              "directx.source-package-only") &&
                   !hasDiagnostic(firstDiagnostics.diagnostics(),
                                  "directx.dxil-emitted") &&
                   !hasDiagnostic(firstDiagnostics.diagnostics(),
                                  "directx.dxc-failed"),
               std::string(label) +
                   " DirectX source-package support predicate does not invoke "
                   "dxc or emit package status diagnostics");
      };

  constexpr std::string_view mixedSamplerSource = R"(
shader DirectXSourcePackagePredicateMixedSamplerShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer vec4* values;
    layout(set = 0, binding = 1) uniform sampler2D colorMap;
    layout(set = 0, binding = 2) uniform sampler2DShadow shadowMap;
    layout(set = 0, binding = 3) sampler sharedSampler;
    void main() {
      vec4 color = textureLod(colorMap, sharedSampler, vec2(0.25, 0.75), 1.0);
      float visibility =
          textureCompare(shadowMap, sharedSampler, vec2(0.5, 0.5), 0.25);
      values[0] = color + vec4(visibility, visibility, 0.0, 1.0);
      return;
    }
  }
}
)";
  std::optional<crossgl::HIRModule> mixedSamplerHir =
      parseHIR(mixedSamplerSource);
  expect(mixedSamplerHir.has_value(),
         "DirectX mixed sampler predicate source builds HIR");
  if (mixedSamplerHir) {
    crossgl::DiagnosticEngine mixedSamplerDiagnostics;
    expect(crossgl::directxSourcePackageSupported(
               *mixedSamplerHir, mixedSamplerDiagnostics),
           "DirectX source-package support predicate accepts scalar mixed "
           "ordinary/comparison sampler usage");
    expect(!mixedSamplerDiagnostics.hasErrors() &&
               !hasDiagnostic(mixedSamplerDiagnostics.diagnostics(),
                              "directx.source-package-only") &&
               !hasDiagnostic(mixedSamplerDiagnostics.diagnostics(),
                              "directx.dxil-emitted") &&
               !hasDiagnostic(mixedSamplerDiagnostics.diagnostics(),
                              "directx.dxc-failed"),
           "DirectX mixed sampler predicate does not invoke dxc or emit "
           "package status diagnostics");
  }

  constexpr std::string_view runtimeResourceArraySource = R"(
shader DirectXSourcePackagePredicateRuntimeResourceArrayShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values;
    layout(set = 0, binding = 1) uniform sampler2D maps[];
    layout(set = 0, binding = 3) uniform sampler2D detailMaps[];
    layout(set = 0, binding = 2) sampler linearSampler;
    void main() {
      values[0] = 1.0;
      return;
    }
  }
}
)";
  expectUnsupported(runtimeResourceArraySource,
                    "directx.unsupported-runtime-resource-array", "maps",
                    "multiple runtime texture arrays in one register class");

  constexpr std::string_view storageElementSource = R"(
shader DirectXSourcePackagePredicateStorageElementShader {
  struct Particle {
    float mass;
    float weights[];
  }
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer Particle* particles;
    void main() {
      float mass = particles[0].mass;
      particles[1].mass = mass + 1.0;
      return;
    }
  }
}
)";
  expectUnsupported(storageElementSource,
                    "directx.unsupported-storage-buffer-element-type",
                    "particles (Particle)", "storage-buffer element");

  constexpr std::string_view graphicsResourceSource = R"(
shader DirectXSourcePackagePredicateGraphicsResourceShader {
  struct VertexInput {
    vec3 position;
    vec2 texCoord;
  }
  struct VertexOutput {
    vec2 uv;
    vec4 position;
  }
  struct FragmentInput {
    vec2 uv;
  }
  struct FragmentOutput {
    vec4 color;
  }
  vertex {
    VertexOutput main(VertexInput input) {
      VertexOutput output;
      output.uv = input.texCoord;
      output.position = vec4(input.position, 1.0);
      return output;
    }
  }
  fragment {
    layout(set = 0, binding = 4) uniform image2D debugValues;
    FragmentOutput main(FragmentInput input) {
      FragmentOutput output;
      output.color = vec4(input.uv, 0.0, 1.0);
      return output;
    }
  }
}
)";
  std::optional<crossgl::HIRModule> graphicsResourceHir =
      parseHIR(graphicsResourceSource);
  expect(graphicsResourceHir.has_value(),
         "DirectX graphics resource diagnostic fixture builds HIR");
  if (graphicsResourceHir) {
    crossgl::DiagnosticEngine diagnostics;
    expect(!crossgl::directxSourcePackageSupported(*graphicsResourceHir,
                                                   diagnostics),
           "DirectX source-package support predicate rejects unsupported "
           "graphics-stage resource kind");
    expect(hasDiagnosticMessageFragment(
               diagnostics.diagnostics(),
               "directx.unsupported-graphics-resource",
               "stage 'fragment' resource 'debugValues'"),
           "DirectX graphics resource diagnostic names the stage and resource");
    expect(hasDiagnosticMessageFragment(
               diagnostics.diagnostics(),
               "directx.unsupported-graphics-resource",
               "kind storage-image"),
           "DirectX graphics resource diagnostic names the resource kind");
    expect(hasDiagnosticMessageFragment(
               diagnostics.diagnostics(),
               "directx.unsupported-graphics-resource",
               "type image2D"),
           "DirectX graphics resource diagnostic names the resource type");
    expect(hasDiagnosticMessageFragment(
               diagnostics.diagnostics(),
               "directx.unsupported-graphics-resource",
               "set 0"),
           "DirectX graphics resource diagnostic names the descriptor set");
    expect(hasDiagnosticMessageFragment(
               diagnostics.diagnostics(),
               "directx.unsupported-graphics-resource",
               "binding 4"),
           "DirectX graphics resource diagnostic names the binding");
  }

  constexpr std::string_view graphicsResourceConflictSource = R"(
shader DirectXSourcePackagePredicateGraphicsResourceConflictShader {
  struct Transform {
    vec4 offset;
  }
  struct Material {
    vec4 baseColor;
  }
  struct VertexInput {
    vec3 position;
  }
  struct VertexOutput {
    vec2 uv;
    vec4 position;
  }
  struct FragmentInput {
    vec2 uv;
  }
  struct FragmentOutput {
    vec4 color;
  }
  vertex {
    layout(set = 0, binding = 0) uniform Transform sharedParams;
    VertexOutput main(VertexInput input) {
      VertexOutput output;
      output.uv = input.position.xy;
      output.position = vec4(input.position + sharedParams.offset.xyz, 1.0);
      return output;
    }
  }
  fragment {
    layout(set = 0, binding = 0) uniform Material material;
    layout(set = 0, binding = 1) uniform Material sharedParams;
    FragmentOutput main(FragmentInput input) {
      FragmentOutput output;
      output.color = material.baseColor + vec4(input.uv, 0.0, 0.0);
      return output;
    }
  }
}
)";
  std::optional<crossgl::HIRModule> graphicsResourceConflictHir =
      parseHIR(graphicsResourceConflictSource);
  expect(graphicsResourceConflictHir.has_value(),
         "DirectX graphics resource conflict diagnostic fixture builds HIR");
  if (graphicsResourceConflictHir) {
    crossgl::DiagnosticEngine diagnostics;
    expect(!crossgl::directxSourcePackageSupported(
               *graphicsResourceConflictHir, diagnostics),
           "DirectX source-package support predicate rejects graphics resource "
           "name and register conflicts");
    expect(hasDiagnosticMessageFragment(
               diagnostics.diagnostics(),
               "directx.unsupported-graphics-resource",
               "name conflict for resource 'sharedParams'"),
           "DirectX graphics resource conflict diagnostic names resource "
           "name conflicts");
    expect(hasDiagnosticMessageFragment(
               diagnostics.diagnostics(),
               "directx.unsupported-graphics-resource",
               "register conflict for register(b0, space0)"),
           "DirectX graphics resource conflict diagnostic names register "
           "conflicts");
    expect(hasDiagnosticMessageFragment(
               diagnostics.diagnostics(),
               "directx.unsupported-graphics-resource",
               "stage 'vertex' resource 'sharedParams'"),
           "DirectX graphics resource conflict diagnostic names vertex "
           "resource details");
    expect(hasDiagnosticMessageFragment(
               diagnostics.diagnostics(),
               "directx.unsupported-graphics-resource",
               "stage 'fragment' resource 'material'"),
           "DirectX graphics resource conflict diagnostic names fragment "
           "resource details");
  }

  constexpr std::string_view finalPolicySource = R"(
shader DirectXSourcePackagePredicateFinalPolicyShader {
  compute {
    layout(set = 0, binding = 0) buffer float* values;
    void main() {
      values[0] = 1.0;
      return;
    }
  }
}
)";
  expectUnsupported(finalPolicySource, "directx.source-unsupported",
                    "one compute stage", "final source policy");
}

void testDirectXSourcePackageRequiresLegalizedResourceBindings() {
  constexpr std::string_view source = R"(
shader DirectXLegalizedBindingRequiredShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values;
    void main() {
      values[0] = 1.0;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(),
         "DirectX legalized-binding requirement fixture builds HIR");
  if (!hir) {
    return;
  }

  const crossgl::TargetLegalizationResult legalization =
      crossgl::legalizeTarget(*hir, crossgl::TargetKind::DirectX);
  expect(legalization.resourceBindings.target ==
             crossgl::TargetKind::DirectX &&
             legalization.resourceBindings.complete &&
             legalization.resourceBindings.requiredRecordCount == 1 &&
             legalization.resourceBindings.records.size() == 1,
         "DirectX legalized-binding requirement fixture has one complete "
         "legalization binding record");
  if (legalization.resourceBindings.records.empty()) {
    return;
  }

  auto expectPackageBuildRejected =
      [&](crossgl::TargetLegalizationResourceBindingFacts resourceBindings,
          std::string_view expectedFragment, std::string_view label) {
        const std::filesystem::path outputPath =
            unitTestTempDirectoryPath() /
            ("crossgl-directx-legalized-binding-required-" +
             std::string(label) + ".cglb");
        std::error_code error;
        std::filesystem::remove_all(outputPath, error);

        crossgl::DiagnosticEngine diagnostics;
        const crossgl::DirectXSourcePackageResult result =
            crossgl::buildDirectXSourcePackage(
                *hir, outputPath, diagnostics, resourceBindings);
        expect(!result.success && diagnostics.hasErrors() &&
                   hasDiagnosticMessageFragment(
                       diagnostics.diagnostics(),
                       "directx.legalized-resource-binding-missing",
                       expectedFragment),
               "DirectX source-package emission rejects " +
                   std::string(label) +
                   " legalization resource-binding facts");
        expect(!std::filesystem::exists(outputPath / "backend" / "directx" /
                                        "DirectXLegalizedBindingRequiredShader."
                                        "hlsl"),
               "DirectX source-package emission does not write HLSL after " +
                   std::string(label) +
                   " legalization resource-binding rejection");
        std::filesystem::remove_all(outputPath, error);
      };

  crossgl::TargetLegalizationResourceBindingFacts incompleteFacts =
      legalization.resourceBindings;
  incompleteFacts.complete = false;
  expectPackageBuildRejected(incompleteFacts, "complete legalized registerBinding",
                             "incomplete");

  crossgl::TargetLegalizationResourceBindingFacts missingRecordFacts =
      legalization.resourceBindings;
  missingRecordFacts.records.clear();
  expectPackageBuildRejected(missingRecordFacts, "resource 'values'",
                             "missing-record");
}

