void testTextureCompareLodHIRAndNativeBackends() {
  constexpr std::string_view source = R"(
shader TextureCompareLodShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values;
    layout(set = 0, binding = 2) uniform sampler2DShadow shadowMap;
    layout(set = 0, binding = 3) uniform samplerCubeArrayShadow shadowCubes;
    layout(set = 0, binding = 5) sampler shadowSampler;

    void main() {
      float visibility =
          textureCompareLod(shadowMap, shadowSampler, vec2(0.5, 0.5), 0.25, 2.0);
      float cubeVisibility =
          textureCompareLod(shadowCubes, shadowSampler,
                            vec4(0.0, 1.0, 0.0, 2.0), 0.75, 3.0);
      values[0] = visibility + cubeVisibility;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "textureCompareLod shadow source builds HIR");
  if (!hir) {
    return;
  }

  const crossgl::HIRFunction &main = hir->stages.front().functions.front();
  expect(main.body.size() >= 2 &&
             main.body[0].value.kind ==
                 crossgl::HIRExpressionKind::TextureCompare &&
             main.body[0].value.value == "textureCompareLod" &&
             main.body[0].value.children.size() == 5 &&
             main.body[0].value.type.name == "float",
         "textureCompareLod is represented as float-producing comparison HIR");
  expect(main.body.size() >= 2 &&
             main.body[1].value.kind ==
                 crossgl::HIRExpressionKind::TextureCompare &&
             main.body[1].value.value == "textureCompareLod" &&
             main.body[1].value.children.size() == 5,
         "cube-array textureCompareLod keeps its explicit lod operand");

  const std::string hirDump = crossgl::printHIR(*hir);
  expect(hirDump.find("texture_compare_lod(shadowMap, shadowSampler, "
                      "vec2(0.5, 0.5), 0.25, 2.0)") != std::string::npos,
         "HIR dump prints canonical texture_compare_lod operation");

  const std::string metal = crossgl::printBackendIR(*hir, crossgl::TargetKind::Metal);
  expect(metal.find("shadowMap.sample_compare(shadowSampler, "
                    "float2(0.5, 0.5), 0.25, level(2.0))") !=
             std::string::npos,
         "Metal backend lowers textureCompareLod to sample_compare level sampling");
  expect(metal.find("shadowCubes.sample_compare(shadowSampler, "
                    "float3(0.0, 1.0, 0.0), uint(2.0), 0.75, "
                    "level(3.0))") != std::string::npos,
         "Metal backend preserves cube-array textureCompareLod layer and lod");

  const std::string directx =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::DirectX);
  expect(directx.find("Texture2D<float> shadowMap : register(t2, space0);") !=
             std::string::npos,
         "DirectX backend maps sampler2DShadow textureCompareLod resource");
  expect(directx.find("TextureCubeArray<float> shadowCubes : register(t3, "
                      "space0);") != std::string::npos,
         "DirectX backend maps samplerCubeArrayShadow textureCompareLod resource");
  expect(directx.find("SamplerComparisonState shadowSampler : register(s5, "
                      "space0);") != std::string::npos,
         "DirectX backend emits comparison sampler for textureCompareLod");
  expect(directx.find("float visibility = shadowMap.SampleCmpLevel("
                      "shadowSampler, float2(0.5, 0.5), 0.25, 2.0);") !=
             std::string::npos,
         "DirectX backend lowers 2D textureCompareLod to SampleCmpLevel");
  expect(directx.find("float cubeVisibility = shadowCubes.SampleCmpLevel("
                      "shadowSampler, float4(0.0, 1.0, 0.0, 2.0), 0.75, "
                      "3.0);") != std::string::npos,
         "DirectX backend lowers cube-array textureCompareLod to SampleCmpLevel");

  const std::vector<crossgl::TargetCapability> directxMissing =
      crossgl::missingTargetCapabilities(*hir, crossgl::TargetKind::DirectX);
  expect(!hasCapability(directxMissing, crossgl::TargetKind::DirectX,
                        "texture", "depth-compare-format") &&
             !hasCapability(directxMissing, crossgl::TargetKind::DirectX,
                            "texture", "array-dimension") &&
             !hasCapability(directxMissing, crossgl::TargetKind::DirectX,
                            "operation", "texture-shadow-compare") &&
             !hasCapability(directxMissing, crossgl::TargetKind::DirectX,
                            "operation",
                            "texture-shadow-compare-explicit-lod"),
         "DirectX textureCompareLod scaffold satisfies shadow LOD capability");

  const std::vector<crossgl::TargetCapability> fullOpenGLMissing =
      crossgl::missingTargetCapabilities(*hir, crossgl::TargetKind::OpenGL);
  expect(!hasCapability(fullOpenGLMissing, crossgl::TargetKind::OpenGL,
                        "diagnostic",
                        "opengl.unsupported-shadow-compare-explicit-lod-shape"),
         "OpenGL full textureCompareLod fixture satisfies explicit LOD "
         "source-package predicate diagnostics");

  constexpr std::string_view opengl2DSource = R"(
shader TextureCompare2DLodShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values;
    layout(set = 0, binding = 2) uniform sampler2DShadow shadowMap;
    layout(set = 0, binding = 5) sampler shadowSampler;

    void main() {
      float visibility =
          textureCompareLod(shadowMap, shadowSampler, vec2(0.5, 0.5), 0.25, 2.0);
      values[0] = visibility;
      return;
    }
  }
}
)";
  std::optional<crossgl::HIRModule> opengl2DHir = parseHIR(opengl2DSource);
  expect(opengl2DHir.has_value(),
         "2D textureCompareLod OpenGL source builds HIR");
  if (!opengl2DHir) {
    return;
  }
  const std::string opengl =
      crossgl::printBackendIR(*opengl2DHir, crossgl::TargetKind::OpenGL);
  expect(opengl.find("layout(binding = 2) uniform sampler2DShadow shadowMap;") !=
             std::string::npos,
         "OpenGL backend maps sampler2DShadow textureCompareLod resource");
  expect(opengl.find("float visibility = textureLod(shadowMap, "
                     "vec3(vec2(0.5, 0.5), 0.25), 2.0);") !=
             std::string::npos,
         "OpenGL backend lowers 2D textureCompareLod to textureLod");
  const std::vector<crossgl::TargetCapability> openglMissing =
      crossgl::missingTargetCapabilities(*opengl2DHir,
                                         crossgl::TargetKind::OpenGL);
  expect(!hasCapability(openglMissing, crossgl::TargetKind::OpenGL,
                        "operation",
                        "texture-shadow-compare-explicit-lod"),
         "OpenGL 2D textureCompareLod scaffold satisfies explicit LOD capability");

  crossgl::DiagnosticEngine assemblyDiagnostics;
  const std::string assembly =
      crossgl::generateVulkanPrototypeAssembly(*hir, assemblyDiagnostics);
  expect(!assemblyDiagnostics.hasErrors(),
         "textureCompareLod Vulkan prototype assembly has no diagnostics");
  expect(assembly.find("OpSampledImage %sampled_sampler2DShadow") !=
             std::string::npos,
         "Vulkan textureCompareLod assembly combines 2D depth image and sampler");
  expect(assembly.find("OpSampledImage %sampled_samplerCubeArrayShadow") !=
             std::string::npos,
         "Vulkan textureCompareLod assembly combines cube-array depth image and sampler");
  expect(countOccurrences(assembly, "OpImageSampleDrefExplicitLod %float") >= 2,
         "Vulkan textureCompareLod assembly emits depth-reference samples");
  expect(assembly.find(" Lod %const_float__2_0") != std::string::npos,
         "Vulkan textureCompareLod assembly uses the first source lod operand");
  expect(assembly.find(" Lod %const_float__3_0") != std::string::npos,
         "Vulkan textureCompareLod assembly uses the cube-array source lod operand");
  expect(assembly.find(" Lod %const_float__0_0") == std::string::npos,
         "Vulkan textureCompareLod assembly does not fall back to implicit lod zero");

  if (crossgl::findExecutable("spirv-as") &&
      crossgl::findExecutable("spirv-val")) {
    const std::filesystem::path packageDir =
        unitTestTempDirectoryPath() /
        "crossgl-vulkan-texture-compare-lod-test";
    std::error_code error;
    std::filesystem::remove_all(packageDir, error);

    crossgl::DiagnosticEngine buildDiagnostics;
    const crossgl::VulkanBuildResult result =
        crossgl::buildVulkanPrototypeBinary(*hir, packageDir, buildDiagnostics);
    expect(result.success,
           "textureCompareLod Vulkan binary assembles and validates");
    expect(!buildDiagnostics.hasErrors(),
           "textureCompareLod Vulkan binary build has no diagnostics");
    expect(std::filesystem::exists(result.spvPath),
           "textureCompareLod Vulkan binary exists");
  }

  if (crossgl::findExecutable("xcrun")) {
    const std::filesystem::path packageDir =
        unitTestTempDirectoryPath() /
        "crossgl-metal-texture-compare-lod-test";
    std::error_code error;
    std::filesystem::remove_all(packageDir, error);

    crossgl::DiagnosticEngine metalDiagnostics;
    const crossgl::MetalBuildResult metalResult =
        crossgl::buildMetalBinary(*hir, packageDir, metalDiagnostics);
    expect(metalResult.success,
           "textureCompareLod Metal binary compiles to metallib");
    expect(!metalDiagnostics.hasErrors(),
           "textureCompareLod Metal build has no diagnostics");
    expect(std::filesystem::exists(metalResult.metallibPath),
           "textureCompareLod Metal metallib exists");
  }
}

void testGraphicsShadowCompareLodBackends() {
  constexpr std::string_view source = R"(
shader GraphicsShadowCompareLodShader {
  struct VertexInput {
    vec3 position;
    vec2 texCoord;
  }
  struct VertexOutput {
    vec2 uv;
    vec4 position;
  }
  struct FragmentInput {
    vec2 uv;
  }
  struct FragmentOutput {
    vec4 color;
  }
  vertex {
    VertexOutput main(VertexInput input) {
      VertexOutput output;
      output.uv = input.texCoord;
      output.position = vec4(input.position, 1.0);
      return output;
    }
  }
  fragment {
    layout(set = 0, binding = 2) uniform sampler2DShadow shadowMap;
    layout(set = 0, binding = 5) comparison_sampler shadowSampler;
    FragmentOutput main(FragmentInput input) {
      FragmentOutput output;
      float visibility =
          textureCompareLod(shadowMap, shadowSampler,
                            vec2(0.5, 0.5), 0.25, 2.0);
      output.color = vec4(visibility, visibility, visibility, 1.0);
      return output;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(),
         "graphics textureCompareLod shadow source builds HIR");
  if (!hir) {
    return;
  }

  const auto fragmentStage =
      std::find_if(hir->stages.begin(), hir->stages.end(),
                   [](const crossgl::HIRStage &stage) {
                     return stage.stage == "fragment";
                   });
  expect(fragmentStage != hir->stages.end() &&
             fragmentStage->resources.size() == 2 &&
             fragmentStage->resources[0].kind ==
                 crossgl::HIRResourceKind::Texture &&
             fragmentStage->resources[0].type.name == "sampler2DShadow" &&
             fragmentStage->resources[1].kind ==
                 crossgl::HIRResourceKind::Sampler &&
             fragmentStage->resources[1].type.name == "comparison_sampler",
         "graphics fragment stage preserves shadow texture and comparison "
         "sampler resources");
  if (fragmentStage == hir->stages.end()) {
    return;
  }

  const crossgl::HIRFunction &fragmentMain =
      fragmentStage->functions.front();
  expect(fragmentMain.body.size() >= 2 &&
             fragmentMain.body[1].value.kind ==
                 crossgl::HIRExpressionKind::TextureCompare &&
             fragmentMain.body[1].value.value == "textureCompareLod" &&
             fragmentMain.body[1].value.children.size() == 5,
         "graphics fragment textureCompareLod keeps explicit LOD compare HIR");

  const std::string directx =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::DirectX);
  expect(directx.find("Texture2D<float> shadowMap : register(t2, space0);") !=
             std::string::npos &&
             directx.find("SamplerComparisonState shadowSampler : register(s5, "
                          "space0);") != std::string::npos,
         "DirectX graphics backend emits shadow texture and comparison sampler "
         "resources");
  expect(directx.find("float visibility = shadowMap.SampleCmpLevel("
                      "shadowSampler, float2(0.5, 0.5), 0.25, 2.0);") !=
             std::string::npos,
         "DirectX graphics backend lowers textureCompareLod to SampleCmpLevel");

  const std::string opengl =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::OpenGL);
  expect(opengl.find("layout(binding = 2) uniform sampler2DShadow shadowMap;") !=
             std::string::npos &&
             opengl.find("sampler shadowSampler is represented by OpenGL "
                         "combined sampler uniforms") != std::string::npos,
         "OpenGL graphics backend emits combined shadow sampler resources");
  expect(opengl.find("float visibility = textureLod(shadowMap, "
                     "vec3(vec2(0.5, 0.5), 0.25), 2.0);") !=
             std::string::npos,
         "OpenGL graphics backend lowers textureCompareLod to explicit LOD "
         "shadow sampling source");

  const std::string metal = crossgl::generateMetalSource(*hir);
  expect(metal.find("fragment FragmentOutput fragment_main(") !=
             std::string::npos &&
             metal.find("depth2d<float> shadowMap [[texture(2)]]") !=
                 std::string::npos &&
             metal.find("sampler shadowSampler [[sampler(5)]]") !=
                 std::string::npos,
         "Metal graphics backend emits shadow texture and sampler fragment "
         "arguments");
  expect(metal.find("float visibility = shadowMap.sample_compare("
                    "shadowSampler, float2(0.5, 0.5), 0.25, "
                    "level(2.0));") != std::string::npos,
         "Metal graphics backend lowers textureCompareLod to sample_compare "
         "level sampling");

  crossgl::DiagnosticEngine vulkanLodSupportDiagnostics;
  expect(crossgl::vulkanPrototypeBinarySupported(
             *hir, vulkanLodSupportDiagnostics) &&
             !vulkanLodSupportDiagnostics.hasErrors(),
         "Vulkan graphics prototype support accepts fragment textureCompareLod "
         "resources");

  crossgl::DiagnosticEngine vulkanLodAssemblyDiagnostics;
  const std::string lodAssembly =
      crossgl::generateVulkanPrototypeAssembly(*hir,
                                               vulkanLodAssemblyDiagnostics);
  expect(!lodAssembly.empty() && !vulkanLodAssemblyDiagnostics.hasErrors(),
         "Vulkan graphics textureCompareLod prototype assembly has no "
         "diagnostics");
  expect(lodAssembly.find("OpEntryPoint Fragment") != std::string::npos &&
             lodAssembly.find("resource_fragment_shadowMap") !=
                 std::string::npos &&
             lodAssembly.find("resource_fragment_shadowSampler") !=
                 std::string::npos,
         "Vulkan graphics textureCompareLod emits fragment shadow resource "
         "bindings");
  const std::size_t explicitSampleOffset =
      lodAssembly.find("OpImageSampleDrefExplicitLod");
  const std::size_t explicitSampleLineEnd =
      explicitSampleOffset == std::string::npos
          ? std::string::npos
          : lodAssembly.find('\n', explicitSampleOffset);
  const std::size_t explicitSampleLodOperand =
      explicitSampleOffset == std::string::npos
          ? std::string::npos
          : lodAssembly.find(" Lod ", explicitSampleOffset);
  expect(countOccurrences(lodAssembly, "OpImageSampleDrefExplicitLod") == 1 &&
             explicitSampleLodOperand != std::string::npos &&
             (explicitSampleLineEnd == std::string::npos ||
              explicitSampleLodOperand < explicitSampleLineEnd),
         "Vulkan graphics textureCompareLod emits explicit LOD Dref sampling");
  expect(lodAssembly.find("OpImageSampleDrefImplicitLod") == std::string::npos,
         "Vulkan graphics textureCompareLod does not use implicit LOD Dref "
         "sampling");

  constexpr std::string_view vulkanSource = R"(
shader VulkanGraphicsShadowCompareShader {
  struct VertexInput {
    vec3 position;
    vec2 texCoord;
  }
  struct VertexOutput {
    vec2 uv;
    vec4 position;
  }
  struct FragmentInput {
    vec2 uv;
  }
  struct FragmentOutput {
    vec4 color;
  }
  vertex {
    VertexOutput main(VertexInput input) {
      VertexOutput output;
      output.uv = input.texCoord;
      output.position = vec4(input.position, 1.0);
      return output;
    }
  }
  fragment {
    layout(set = 0, binding = 2) uniform sampler2DShadow shadowMap;
    layout(set = 0, binding = 5) comparison_sampler shadowSampler;
    FragmentOutput main(FragmentInput input) {
      FragmentOutput output;
      float visibility =
          textureCompare(shadowMap, shadowSampler, vec2(0.5, 0.5), 0.25);
      output.color = vec4(visibility, input.uv.x, input.uv.y, 1.0);
      return output;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> vulkanHir = parseHIR(vulkanSource);
  expect(vulkanHir.has_value(),
         "Vulkan graphics shadow compare source builds HIR");
  if (!vulkanHir) {
    return;
  }

  crossgl::DiagnosticEngine supportDiagnostics;
  expect(crossgl::vulkanPrototypeBinarySupported(*vulkanHir,
                                                 supportDiagnostics) &&
             !supportDiagnostics.hasErrors(),
         "Vulkan graphics prototype support accepts fragment shadow compare "
         "resources");

  crossgl::DiagnosticEngine assemblyDiagnostics;
  const std::string assembly =
      crossgl::generateVulkanPrototypeAssembly(*vulkanHir,
                                               assemblyDiagnostics);
  expect(!assembly.empty() && !assemblyDiagnostics.hasErrors(),
         "Vulkan graphics shadow compare prototype assembly has no diagnostics");
  expect(assembly.find("OpEntryPoint Fragment") != std::string::npos &&
             assembly.find("resource_fragment_shadowMap") !=
                 std::string::npos &&
             assembly.find("resource_fragment_shadowSampler") !=
                 std::string::npos,
         "Vulkan graphics prototype emits fragment shadow resource bindings");
  expect(assembly.find("OpTypeImage") != std::string::npos &&
             assembly.find(" 2D 1 0 0 1 Unknown") != std::string::npos &&
             assembly.find("OpSampledImage") != std::string::npos &&
             assembly.find("OpImageSampleDrefImplicitLod") !=
                 std::string::npos,
         "Vulkan graphics prototype emits Dref shadow sampling");
}

