void testVulkanGraphicsNonUniformDescriptorArrayPrototypeAssembly() {
  constexpr std::string_view source = R"(
shader VulkanGraphicsNonUniformDescriptorArrayShader {
  struct VertexInput {
    vec3 position;
    vec2 texCoord;
  }
  struct VertexOutput {
    vec2 uv;
    vec4 position;
  }
  struct FragmentInput {
    vec2 uv;
  }
  struct FragmentOutput {
    vec4 color;
  }
  vertex {
    VertexOutput main(VertexInput input) {
      VertexOutput output;
      output.uv = input.texCoord;
      output.position = vec4(input.position, 1.0);
      return output;
    }
  }
  fragment {
    layout(set = 0, binding = 2) uniform sampler2D colorMaps[2];
    layout(set = 0, binding = 5) sampler linearSamplers[2];

    FragmentOutput main(FragmentInput input) {
      FragmentOutput output;
      int material = input.uv.x > 0.5 ? 1 : 0;
      output.color = texture(colorMaps[nonuniform(material)],
                             linearSamplers[nonuniform(material)],
                             input.uv);
      return output;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(),
         "Vulkan graphics nonuniform descriptor-array source builds HIR");
  if (!hir) {
    return;
  }

  crossgl::DiagnosticEngine supportDiagnostics;
  expect(crossgl::vulkanPrototypeBinarySupported(*hir, supportDiagnostics) &&
             !supportDiagnostics.hasErrors(),
         "Vulkan graphics prototype support accepts nonuniform sampled "
         "descriptor arrays");

  crossgl::DiagnosticEngine assemblyDiagnostics;
  const std::string assembly =
      crossgl::generateVulkanPrototypeAssembly(*hir, assemblyDiagnostics);
  expect(!assembly.empty() && !assemblyDiagnostics.hasErrors(),
         "Vulkan graphics nonuniform descriptor-array assembly has no "
         "diagnostics");
  expect(assembly.find("OpExtension \"SPV_EXT_descriptor_indexing\"") !=
             std::string::npos &&
             assembly.find("OpCapability ShaderNonUniformEXT") !=
                 std::string::npos &&
             assembly.find("OpCapability "
                           "SampledImageArrayNonUniformIndexingEXT") !=
                 std::string::npos,
         "Vulkan graphics nonuniform descriptor-array assembly declares "
         "descriptor indexing requirements");
  expect(assembly.find("OpCapability "
                       "StorageBufferArrayNonUniformIndexingEXT") ==
             std::string::npos,
         "Vulkan graphics sampled-only nonuniform descriptors do not request "
         "storage-buffer nonuniform capability");
  expect(assembly.find("NonUniformEXT") != std::string::npos &&
             assembly.find("OpAccessChain") != std::string::npos &&
             assembly.find("OpSampledImage") != std::string::npos &&
             assembly.find("OpImageSampleImplicitLod") != std::string::npos,
         "Vulkan graphics prototype decorates and samples nonuniform "
         "texture/sampler descriptor arrays");
  expect(assembly.find("resource_fragment_colorMaps") != std::string::npos &&
             assembly.find("resource_fragment_linearSamplers") !=
                 std::string::npos,
         "Vulkan graphics nonuniform assembly emits fragment descriptor-array "
         "resources");

  constexpr std::string_view invalidSource = R"(
shader VulkanGraphicsGenericNonUniformRejectedShader {
  struct VertexInput {
    vec3 position;
    vec2 texCoord;
  }
  struct VertexOutput {
    vec2 uv;
    vec4 position;
  }
  struct FragmentInput {
    vec2 uv;
  }
  struct FragmentOutput {
    vec4 color;
  }
  vertex {
    VertexOutput main(VertexInput input) {
      VertexOutput output;
      output.uv = input.texCoord;
      output.position = vec4(input.position, 1.0);
      return output;
    }
  }
  fragment {
    FragmentOutput main(FragmentInput input) {
      FragmentOutput output;
      int material = input.uv.x > 0.5 ? 1 : 0;
      int invalid = nonuniform(material);
      output.color = vec4(float(invalid), input.uv, 1.0);
      return output;
    }
  }
}
)";

  const std::vector<crossgl::Diagnostic> invalidDiagnostics =
      collectDiagnostics(invalidSource);
  expect(hasDiagnostic(invalidDiagnostics, "sema.nonuniform-index-placement"),
         "generic graphics nonuniform expressions remain rejected outside "
         "descriptor-array indices");

  if (!crossgl::findExecutable("spirv-as") ||
      !crossgl::findExecutable("spirv-val")) {
    return;
  }

  const std::filesystem::path packageDir =
      unitTestTempDirectoryPath() /
      "crossgl-vulkan-graphics-nonuniform-descriptor-array-prototype-test";
  std::error_code error;
  std::filesystem::remove_all(packageDir, error);

  crossgl::DiagnosticEngine buildDiagnostics;
  const crossgl::VulkanBuildResult result =
      crossgl::buildVulkanPrototypeBinary(*hir, packageDir, buildDiagnostics);
  expect(result.success,
         "Vulkan graphics nonuniform descriptor-array prototype binary "
         "assembles and validates");
  expect(!buildDiagnostics.hasErrors(),
         "Vulkan graphics nonuniform descriptor-array prototype binary build "
         "has no diagnostics");
  expect(std::filesystem::exists(result.assemblyPath),
         "Vulkan graphics nonuniform descriptor-array prototype assembly file "
         "exists");
  expect(std::filesystem::exists(result.spvPath),
         "Vulkan graphics nonuniform descriptor-array SPIR-V binary exists");

  std::filesystem::remove_all(packageDir, error);
}

void testVulkanGraphicsLoopPrototypeAssembly() {
  constexpr std::string_view source = R"(
shader VulkanGraphicsLoopShader {
  struct VertexInput {
    vec3 position;
    vec2 texCoord;
  }
  struct VertexOutput {
    vec2 uv;
    vec4 position;
  }
  struct FragmentInput {
    vec2 uv;
  }
  struct FragmentOutput {
    vec4 color;
  }
  vertex {
    VertexOutput main(VertexInput input) {
      VertexOutput output;
      output.uv = input.texCoord;
      output.position = vec4(input.position, 1.0);
      return output;
    }
  }
  fragment {
    FragmentOutput main(FragmentInput input) {
      FragmentOutput output;
      vec4 accum = vec4(input.uv, 0.0, 1.0);
      for (int i = 0; i < 3; i = i + 1) {
        vec4 tint = vec4(0.1, 0.0, 0.0, 0.0);
        accum = accum + tint;
      }
      output.color = accum;
      return output;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "Vulkan graphics loop source builds HIR");
  if (!hir) {
    return;
  }

  crossgl::DiagnosticEngine supportDiagnostics;
  expect(crossgl::vulkanPrototypeBinarySupported(*hir, supportDiagnostics) &&
             !supportDiagnostics.hasErrors(),
         "Vulkan graphics prototype support accepts conservative for loops");

  crossgl::DiagnosticEngine assemblyDiagnostics;
  const std::string assembly =
      crossgl::generateVulkanPrototypeAssembly(*hir, assemblyDiagnostics);
  expect(!assembly.empty() && !assemblyDiagnostics.hasErrors(),
         "Vulkan graphics loop prototype assembly has no diagnostics");
  expect(assembly.find("OpLoopMerge") != std::string::npos &&
             assembly.find("OpBranchConditional") != std::string::npos &&
             assembly.find("OpSLessThan") != std::string::npos &&
             assembly.find("OpIAdd") != std::string::npos,
         "Vulkan graphics prototype lowers for loops to structured SPIR-V");
  expect(assembly.find("OpName") != std::string::npos &&
             assembly.find("\"tint\"") != std::string::npos,
         "Vulkan graphics loop predeclares loop-body locals");

  constexpr std::string_view controlSource = R"(
shader VulkanGraphicsLoopControlShader {
  struct VertexInput {
    vec3 position;
    vec2 texCoord;
  }
  struct VertexOutput {
    vec2 uv;
    vec4 position;
  }
  struct FragmentInput {
    vec2 uv;
  }
  struct FragmentOutput {
    vec4 color;
  }
  vertex {
    VertexOutput main(VertexInput input) {
      VertexOutput output;
      output.uv = input.texCoord;
      output.position = vec4(input.position, 1.0);
      return output;
    }
  }
  fragment {
    FragmentOutput main(FragmentInput input) {
      FragmentOutput output;
      vec4 accum = vec4(input.uv, 0.0, 1.0);
      for (int i = 0; i < 3; i++) {
        if (i == 1) {
          continue;
        }
        if (i == 2) {
          break;
        }
        accum = accum + vec4(0.1, 0.0, 0.0, 0.0);
      }
      output.color = accum;
      return output;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> controlHir = parseHIR(controlSource);
  expect(controlHir.has_value(),
         "Vulkan graphics loop control source builds HIR");
  if (controlHir) {
    crossgl::DiagnosticEngine controlSupportDiagnostics;
    expect(crossgl::vulkanPrototypeBinarySupported(
               *controlHir, controlSupportDiagnostics) &&
               !controlSupportDiagnostics.hasErrors(),
           "Vulkan graphics prototype support accepts break and continue "
           "inside loops");

    crossgl::DiagnosticEngine controlAssemblyDiagnostics;
    const std::string controlAssembly =
        crossgl::generateVulkanPrototypeAssembly(
            *controlHir, controlAssemblyDiagnostics);
    expect(!controlAssembly.empty() &&
               !controlAssemblyDiagnostics.hasErrors(),
           "Vulkan graphics loop control assembly has no diagnostics");

    const std::string loopMergePrefix = "OpLoopMerge ";
    const std::size_t loopMergePos = controlAssembly.find(loopMergePrefix);
    expect(loopMergePos != std::string::npos,
           "Vulkan graphics loop control emits OpLoopMerge");
    if (loopMergePos != std::string::npos) {
      const std::size_t lineEnd = controlAssembly.find('\n', loopMergePos);
      const std::string loopMergeLine = controlAssembly.substr(
          loopMergePos, lineEnd == std::string::npos
                            ? std::string::npos
                            : lineEnd - loopMergePos);
      std::istringstream loopMergeStream(loopMergeLine);
      std::string op;
      std::string mergeLabel;
      std::string continueLabel;
      loopMergeStream >> op >> mergeLabel >> continueLabel;
      expect(!mergeLabel.empty() && !continueLabel.empty(),
             "Vulkan graphics loop control exposes merge and continue labels");
      expect(controlAssembly.find("OpBranch " + mergeLabel) !=
                 std::string::npos,
             "Vulkan graphics loop control lowers break to the loop merge "
             "label");
      expect(countOccurrences(controlAssembly,
                              "OpBranch " + continueLabel) >= 2,
             "Vulkan graphics loop control lowers continue to the loop "
             "continue label");
    }
  }

  if (!crossgl::findExecutable("spirv-as") ||
      !crossgl::findExecutable("spirv-val")) {
    return;
  }

  const std::filesystem::path packageDir =
      unitTestTempDirectoryPath() / "crossgl-vulkan-graphics-loop-test";
  std::error_code error;
  std::filesystem::remove_all(packageDir, error);

  crossgl::DiagnosticEngine buildDiagnostics;
  const crossgl::VulkanBuildResult result =
      crossgl::buildVulkanPrototypeBinary(*hir, packageDir, buildDiagnostics);
  expect(result.success,
         "Vulkan graphics loop prototype binary assembles and validates");
  expect(!buildDiagnostics.hasErrors(),
         "Vulkan graphics loop prototype binary build has no diagnostics");
  expect(std::filesystem::exists(result.assemblyPath),
         "Vulkan graphics loop prototype assembly file exists");
  expect(std::filesystem::exists(result.spvPath),
         "Vulkan graphics loop SPIR-V binary exists");

  std::filesystem::remove_all(packageDir, error);
}

std::optional<std::string>
spirvEntryPointFunctionId(const std::string &assembly,
                          std::string_view executionModel,
                          std::string_view entryName) {
  std::istringstream stream(assembly);
  std::string line;
  const std::string prefix =
      "OpEntryPoint " + std::string(executionModel) + " ";
  const std::string nameNeedle = "\"" + std::string(entryName) + "\"";
  while (std::getline(stream, line)) {
    if (line.rfind(prefix, 0) != 0 ||
        line.find(nameNeedle) == std::string::npos) {
      continue;
    }
    std::istringstream lineStream(line.substr(prefix.size()));
    std::string functionId;
    lineStream >> functionId;
    if (!functionId.empty()) {
      return functionId;
    }
  }
  return std::nullopt;
}

void testVulkanGraphicsHelperFunctionPrototypeAssembly() {
  constexpr std::string_view source = R"(
shader VulkanGraphicsHelperFunctionShader {
  struct VertexInput {
    vec3 position;
    vec2 texCoord;
  }
  struct VertexOutput {
    vec2 uv;
    vec4 position;
  }
  struct FragmentInput {
    vec2 uv;
  }
  struct FragmentOutput {
    vec4 color;
  }
  vertex {
    VertexOutput main(VertexInput input) {
      VertexOutput output;
      output.uv = input.texCoord;
      output.position = vec4(input.position, 1.0);
      return output;
    }
  }
  fragment {
    vec4 tint(vec2 uv, float gain) {
      return vec4(uv.x * gain, uv.y + gain, 0.25, 1.0);
    }
    vec4 shade(FragmentInput input, float gain) {
      vec4 base = tint(input.uv, gain);
      return base + vec4(0.1, 0.0, 0.0, 0.0);
    }
    FragmentOutput main(FragmentInput input) {
      FragmentOutput output;
      output.color = shade(input, 2.0);
      return output;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(),
         "Vulkan graphics helper-function source builds HIR");
  if (!hir) {
    return;
  }

  crossgl::DiagnosticEngine supportDiagnostics;
  expect(crossgl::vulkanPrototypeBinarySupported(*hir, supportDiagnostics) &&
             !supportDiagnostics.hasErrors(),
         "Vulkan graphics prototype support accepts same-stage helper "
         "functions");

  crossgl::DiagnosticEngine assemblyDiagnostics;
  const std::string assembly =
      crossgl::generateVulkanPrototypeAssembly(*hir, assemblyDiagnostics);
  expect(!assembly.empty() && !assemblyDiagnostics.hasErrors(),
         "Vulkan graphics helper-function assembly has no diagnostics");

  const std::size_t tintHelper =
      assembly.find("%func_fragment_tint = OpFunction");
  const std::size_t fragmentHelper =
      assembly.find("%func_fragment_shade = OpFunction");
  const std::optional<std::string> fragmentEntryId =
      spirvEntryPointFunctionId(assembly, "Fragment", "fragment_main");
  const std::size_t fragmentEntry =
      fragmentEntryId.has_value()
          ? assembly.find(*fragmentEntryId + " = OpFunction")
          : std::string::npos;
  expect(tintHelper != std::string::npos &&
             fragmentHelper != std::string::npos &&
             fragmentEntry != std::string::npos &&
             tintHelper < fragmentHelper && fragmentHelper < fragmentEntry,
         "Vulkan graphics helper-function assembly emits helpers before "
         "stage entries");
  expect(countOccurrences(assembly, "OpFunctionParameter") >= 3,
         "Vulkan graphics helper-function assembly emits helper parameters");
  expect(countOccurrences(assembly, "OpReturnValue") >= 2,
         "Vulkan graphics helper-function assembly emits value returns");
  expect(assembly.find("OpFunctionCall") != std::string::npos &&
             assembly.find("%func_fragment_tint") != std::string::npos &&
             assembly.find("%func_fragment_shade") != std::string::npos,
         "Vulkan graphics helper-function assembly emits helper calls");

  if (!crossgl::findExecutable("spirv-as") ||
      !crossgl::findExecutable("spirv-val")) {
    return;
  }

  const std::filesystem::path packageDir =
      unitTestTempDirectoryPath() /
      "crossgl-vulkan-graphics-helper-function-prototype-test";
  std::error_code error;
  std::filesystem::remove_all(packageDir, error);

  crossgl::DiagnosticEngine buildDiagnostics;
  const crossgl::VulkanBuildResult result =
      crossgl::buildVulkanPrototypeBinary(*hir, packageDir, buildDiagnostics);
  expect(result.success,
         "Vulkan graphics helper-function prototype binary assembles and "
         "validates");
  expect(!buildDiagnostics.hasErrors(),
         "Vulkan graphics helper-function prototype binary build has no "
         "diagnostics");
  expect(std::filesystem::exists(result.assemblyPath),
         "Vulkan graphics helper-function prototype assembly file exists");
  expect(std::filesystem::exists(result.spvPath),
         "Vulkan graphics helper-function SPIR-V binary exists");

  std::filesystem::remove_all(packageDir, error);
}

