void testTextureCompareLodManualKernel4Backends() {
  constexpr std::string_view source = R"(
shader TextureCompareLodManualKernel4Shader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values;
    layout(set = 0, binding = 2) uniform sampler2DShadow shadowMap;
    layout(set = 0, binding = 4) uniform sampler2DArrayShadow shadowAtlas;
    layout(set = 0, binding = 6) sampler rawShadowSampler;

    void main() {
      float visibility2D =
          textureCompareLodManualKernel4(shadowMap, rawShadowSampler,
                                         vec2(0.5, 0.5), 0.25, 2.0, less,
                                         ivec2(-1, 0), 0.125,
                                         ivec2(0, 0), 0.375,
                                         ivec2(1, 0), 0.375,
                                         ivec2(0, 1), 0.125);
      float visibilityArray =
          textureCompareLodManualKernel4(shadowAtlas, rawShadowSampler,
                                         vec3(0.25, 0.5, 1.0), 0.33, 2.0,
                                         less_equal,
                                         ivec2(-1, -1), 0.20,
                                         ivec2(0, -1), 0.30,
                                         ivec2(-1, 0), 0.30,
                                         ivec2(0, 0), 0.20);
      values[0] = visibility2D + visibilityArray;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "textureCompareLodManualKernel4 source builds HIR");
  if (!hir) {
    return;
  }

  const crossgl::HIRFunction &main = hir->stages.front().functions.front();
  expect(main.body.size() >= 2 &&
             main.body[0].value.kind ==
                 crossgl::HIRExpressionKind::TextureCompareLodManual &&
             main.body[0].value.value == "textureCompareLodManualKernel4" &&
             main.body[0].value.children.size() == 14 &&
             main.body[0].value.children[6].type.name == "ivec2" &&
             main.body[0].value.children[7].type.name == "float" &&
             main.body[0].value.type.name == "float",
         "textureCompareLodManualKernel4 keeps distinct HIR spelling and tap "
         "operands");

  const std::string hirDump = crossgl::printHIR(*hir);
  expect(hirDump.find("texture_compare_lod_manual_kernel(shadowMap, "
                      "rawShadowSampler, vec2(0.5, 0.5), 0.25, 2.0, "
                      "less, texture_compare_kernel(ivec2(-1, 0), "
                      "0.125") != std::string::npos,
         "HIR dump canonicalizes Kernel4 compatibility spelling to the "
         "tap-list operation");

  expect(crossgl::directxTextualBackendSupported(*hir),
         "DirectX textual backend supports manual kernel4 compare fallback");
  const std::string directx =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::DirectX);
  expect(directx.find("cglCompareDepth(shadowMap.SampleLevel("
                      "rawShadowSampler, float2(0.5, 0.5), 2.0, "
                      "int2(1, 0)), 0.25, CGL_COMPARE_LESS) * 0.375") !=
             std::string::npos,
         "DirectX lowers manual kernel4 as weighted raw SampleLevel taps");
  expect(directx.find("cglCompareDepth(shadowAtlas.SampleLevel("
                      "rawShadowSampler, float3(0.25, 0.5, 1.0), 2.0, "
                      "int2(-1, 0)), 0.33, CGL_COMPARE_LESS_EQUAL) * 0.30") !=
             std::string::npos,
         "DirectX lowers 2D-array manual kernel4 as weighted taps");
  const std::vector<crossgl::TargetCapability> directxMissing =
      crossgl::missingTargetCapabilities(*hir, crossgl::TargetKind::DirectX);
  expect(!hasCapability(
             directxMissing, crossgl::TargetKind::DirectX, "operation",
             "texture-shadow-compare-explicit-lod-manual-kernel-list"),
         "DirectX scaffold satisfies canonical manual kernel capability for "
         "Kernel4 source");

  expect(crossgl::openglTextualBackendSupported(*hir),
         "OpenGL textual backend supports manual kernel4 compare fallback");
  const std::string opengl =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::OpenGL);
  expect(opengl.find("cglCompareDepth(textureLodOffset(sampler2D("
                     "shadowMap, rawShadowSampler), vec2(0.5, 0.5), 2.0, "
                     "ivec2(1, 0)).r, 0.25, CGL_COMPARE_LESS) * 0.375") !=
             std::string::npos,
         "OpenGL lowers manual kernel4 as weighted textureLodOffset taps");
  expect(opengl.find("cglCompareDepth(textureLodOffset(sampler2DArray("
                     "shadowAtlas, rawShadowSampler), "
                     "vec3(0.25, 0.5, 1.0), 2.0, ivec2(-1, 0)).r, 0.33, "
                     "CGL_COMPARE_LESS_EQUAL) * 0.30") != std::string::npos,
         "OpenGL lowers 2D-array manual kernel4 as weighted offset taps");
  const std::vector<crossgl::TargetCapability> openglMissing =
      crossgl::missingTargetCapabilities(*hir, crossgl::TargetKind::OpenGL);
  expect(!hasCapability(
             openglMissing, crossgl::TargetKind::OpenGL, "operation",
             "texture-shadow-compare-explicit-lod-manual-kernel-list"),
         "OpenGL scaffold satisfies canonical manual kernel capability for "
         "Kernel4 source");

  const std::string metal = crossgl::generateMetalSource(*hir);
  expect(metal.find("cglCompareDepth(shadowMap.sample(rawShadowSampler, "
                    "float2(0.5, 0.5), level(2.0), int2(1, 0)), 0.25, "
                    "CGL_COMPARE_LESS) * 0.375") != std::string::npos,
         "Metal lowers manual kernel4 as weighted depth sample taps");
  expect(metal.find("cglCompareDepth(shadowAtlas.sample(rawShadowSampler, "
                    "float2(0.25, 0.5), uint(1.0), level(2.0), "
                    "int2(-1, 0)), 0.33, CGL_COMPARE_LESS_EQUAL) * 0.30") !=
             std::string::npos,
         "Metal lowers 2D-array manual kernel4 as weighted offset taps");

  crossgl::DiagnosticEngine vulkanDiagnostics;
  const std::string vulkanAssembly =
      crossgl::generateVulkanPrototypeAssembly(*hir, vulkanDiagnostics);
  expect(!vulkanDiagnostics.hasErrors(),
         "textureCompareLodManualKernel4 Vulkan prototype assembly has no "
         "diagnostics");
  expect(countOccurrences(vulkanAssembly, "OpImageSampleExplicitLod %vec4") >=
             8,
         "Vulkan manual kernel4 compare assembly emits four raw samples per "
         "operation");
  expect(countOccurrences(vulkanAssembly, "ConstOffset") >= 8,
         "Vulkan manual kernel4 compare assembly attaches ConstOffset to each "
         "tap");
  expect(vulkanAssembly.find("OpImageSampleDrefExplicitLod") ==
             std::string::npos,
         "Vulkan manual kernel4 compare assembly does not use hardware Dref "
         "sampling");
  expect(countOccurrences(vulkanAssembly, "OpSelect %float") >= 8,
         "Vulkan manual kernel4 compare assembly selects float visibility per "
         "tap");
  expect(countOccurrences(vulkanAssembly, "OpFMul %float") >= 8 &&
             countOccurrences(vulkanAssembly, "OpFAdd %float") >= 6,
         "Vulkan manual kernel4 compare assembly emits weighted accumulation");

  const crossgl::ReflectionDocument reflection =
      crossgl::buildReflectionDocument(
          *hir, crossgl::TargetKind::Vulkan,
          "/tmp/TextureCompareLodManualKernel4Shader.spv");
  expect(reflection.manualTextureCompareKernelSummary.totalCount == 2 &&
             reflection.manualTextureCompareKernelSummary
                     .staticNormalizedCount == 2 &&
             reflection.manualTextureCompareKernelSummary.dynamicCount == 0,
         "reflection summarizes Kernel4 manual kernel bucket totals");
  const crossgl::ReflectionTargetResourceBinding *rawSampler =
      findTargetResourceBinding(reflection, "rawShadowSampler");
  expect(rawSampler != nullptr &&
             std::find(rawSampler->usageRoles.begin(),
                       rawSampler->usageRoles.end(),
                       "manual-raw-sampler") != rawSampler->usageRoles.end(),
         "reflection marks manual kernel raw sampler bindings");
  expect(std::any_of(reflection.manualTextureCompareKernels.begin(),
                     reflection.manualTextureCompareKernels.end(),
                     [](const crossgl::ReflectionManualTextureCompareKernel
                            &kernel) {
                       return kernel.sourceKind == "fixed4" &&
                              kernel.canonicalOperation ==
                                  "textureCompareLodManualKernel" &&
                              kernel.weightClass == "static-normalized" &&
                              kernel.compatibilityAlias &&
                              kernel.tapCount == 4;
                     }),
         "reflection classifies Kernel4 compatibility aliases");

  if (crossgl::findExecutable("spirv-as") &&
      crossgl::findExecutable("spirv-val")) {
    const std::filesystem::path packageDir =
        unitTestTempDirectoryPath() /
        "crossgl-vulkan-texture-compare-lod-manual-kernel-4-test";
    std::error_code error;
    std::filesystem::remove_all(packageDir, error);

    crossgl::DiagnosticEngine buildDiagnostics;
    const crossgl::VulkanBuildResult result =
        crossgl::buildVulkanPrototypeBinary(*hir, packageDir, buildDiagnostics);
    expect(result.success,
           "textureCompareLodManualKernel4 Vulkan binary assembles and "
           "validates");
    expect(!buildDiagnostics.hasErrors(),
           "textureCompareLodManualKernel4 Vulkan binary build has no "
           "diagnostics");
    expect(std::filesystem::exists(result.spvPath),
           "textureCompareLodManualKernel4 Vulkan binary exists");
  }

  if (crossgl::findExecutable("xcrun")) {
    const std::filesystem::path packageDir =
        unitTestTempDirectoryPath() /
        "crossgl-metal-texture-compare-lod-manual-kernel-4-test";
    std::error_code error;
    std::filesystem::remove_all(packageDir, error);

    crossgl::DiagnosticEngine metalDiagnostics;
    const crossgl::MetalBuildResult metalResult =
        crossgl::buildMetalBinary(*hir, packageDir, metalDiagnostics);
    expect(metalResult.success,
           "textureCompareLodManualKernel4 Metal binary compiles to metallib");
    expect(!metalDiagnostics.hasErrors(),
           "textureCompareLodManualKernel4 Metal build has no diagnostics");
    expect(std::filesystem::exists(metalResult.metallibPath),
           "textureCompareLodManualKernel4 Metal metallib exists");
  }
}

