void testDirectXFunctionParameterArrayHLSL() {
  constexpr std::string_view source = R"(
shader DirectXFunctionParameterArrayShader {
  const int WEIGHT_COUNT = 4;
  struct Particle {
    float weights[WEIGHT_COUNT];
    float mass;
  }
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer Particle* particles;
    void storeFirstWeight(float weights[WEIGHT_COUNT]) {
      float firstWeight = weights[0];
      particles[1].mass = firstWeight;
      return;
    }
    void storeForwardedWeight(float forwardedWeights[WEIGHT_COUNT]) {
      storeFirstWeight(forwardedWeights);
      return;
    }
    void main() {
      storeForwardedWeight(particles[0].weights);
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "DirectX function parameter array source builds HIR");
  if (!hir) {
    return;
  }

  expect(crossgl::directxTextualBackendSupported(*hir),
         "DirectX scaffold supports helper functions with fixed array parameters");
  const std::string directx = crossgl::generateDirectXSource(*hir);
  const std::size_t storeHelperPosition =
      directx.find("void storeFirstWeight(float weights[WEIGHT_COUNT])");
  const std::size_t forwardingHelperPosition = directx.find(
      "void storeForwardedWeight(float forwardedWeights[WEIGHT_COUNT])");
  const std::size_t entryPosition = directx.find("void compute_main(");
  expect(storeHelperPosition != std::string::npos &&
             forwardingHelperPosition != std::string::npos &&
             entryPosition != std::string::npos &&
             storeHelperPosition < forwardingHelperPosition &&
             forwardingHelperPosition < entryPosition,
         "DirectX backend emits fixed-array helpers before the compute entry");
  expect(directx.find("float firstWeight = weights[0];") !=
                 std::string::npos &&
             directx.find("particles[1].mass = firstWeight;") !=
                 std::string::npos &&
             directx.find("storeFirstWeight(forwardedWeights);") !=
                 std::string::npos &&
             directx.find("storeForwardedWeight(particles[0].weights);") !=
                 std::string::npos,
         "DirectX backend lowers fixed-array helper body, parameter-forwarding "
         "call, and storage-buffer field call");

  const std::vector<crossgl::TargetCapability> directxMissing =
      crossgl::missingTargetCapabilities(*hir, crossgl::TargetKind::DirectX);
  expect(!hasCapability(directxMissing, crossgl::TargetKind::DirectX,
                        "backend", "hlsl-lowering"),
         "DirectX function parameter array scaffold satisfies HLSL lowering");
}

void testDirectXLocalFunctionParameterArrayHLSL() {
  constexpr std::string_view source = R"(
shader DirectXLocalFunctionParameterArrayShader {
  const int COUNT = 2;
  struct Particle {
    float weights[COUNT];
    float mass;
  }
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer Particle* particles;
    float sumWeights(float weights[COUNT]) {
      return weights[0] + weights[1];
    }
    void main() {
      float localWeights[COUNT];
      localWeights[0] = particles[0].weights[0];
      localWeights[1] = particles[0].weights[1];
      float total = sumWeights(localWeights);
      particles[1].mass = total;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(),
         "DirectX local function-parameter array source builds HIR");
  if (!hir) {
    return;
  }

  expect(crossgl::directxTextualBackendSupported(*hir),
         "DirectX source package supports local arrays passed read-only to "
         "helper array parameters");
  const std::string directx = crossgl::generateDirectXSource(*hir);
  expect(directx.find("float sumWeights(float weights[COUNT])") !=
             std::string::npos &&
             directx.find("float localWeights[COUNT];") != std::string::npos &&
             directx.find("localWeights[0] = particles[0].weights[0];") !=
                 std::string::npos &&
             directx.find("localWeights[1] = particles[0].weights[1];") !=
                 std::string::npos &&
             directx.find("float total = sumWeights(localWeights);") !=
                 std::string::npos,
         "DirectX backend emits local fixed-array declaration, element writes, "
         "and helper array call");

  const std::vector<crossgl::TargetCapability> directxMissing =
      crossgl::missingTargetCapabilities(*hir, crossgl::TargetKind::DirectX);
  expect(!hasCapability(directxMissing, crossgl::TargetKind::DirectX,
                        "backend", "hlsl-lowering") &&
             !hasCapability(directxMissing, crossgl::TargetKind::DirectX,
                            "layout", "fixed-array") &&
             !hasCapability(directxMissing, crossgl::TargetKind::DirectX,
                            "operation", "local-declaration"),
         "DirectX local array argument source satisfies HLSL, fixed-array, "
         "and local-declaration capabilities");
}

