void testMetalStorageBufferDynamicDescriptorArrayIndexLowering() {
  constexpr std::string_view source = R"(
shader MetalStorageBufferDynamicDescriptorArrayShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values[2];
    void main() {
      int descriptor = int(values[0][0]);
      float first = values[descriptor][0];
      values[0][1] = first;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(),
         "Metal dynamic storage-buffer descriptor array index source builds HIR");
  if (!hir) {
    return;
  }

  const crossgl::HIRStage &stage = hir->stages.front();
  expect(stage.resources.size() == 1 &&
             stage.resources.front().kind == crossgl::HIRResourceKind::Buffer &&
             stage.resources.front().type.arraySize == "2",
         "Metal dynamic descriptor-index fixture keeps the fixed buffer-array size");

  crossgl::DiagnosticEngine diagnostics;
  expect(crossgl::metalNativeBackendSupported(*hir, diagnostics),
         "Metal storage-buffer descriptor arrays support dynamic descriptor indexes");
  expect(diagnostics.diagnostics().empty(),
         "Metal dynamic descriptor-index support has no diagnostics");

  const std::string metal = crossgl::generateMetalSource(*hir);
  expect(metal.find("device float* cgl_select_compute_values("
                    "int descriptorIndex, device float* values_0, "
                    "device float* values_1)") != std::string::npos,
         "Metal dynamic descriptor-index source emits buffer selector helper");
  expect(metal.find("switch (descriptorIndex)") != std::string::npos,
         "Metal dynamic descriptor-index source emits selector switch");
  expect(metal.find("if (descriptorIndex < 0 || descriptorIndex >= 2)") !=
             std::string::npos,
         "Metal dynamic descriptor-index selector guards descriptor bounds");
  expect(metal.find("float first = "
                    "cgl_select_compute_values(descriptor, values_0, values_1)"
                    "[0];") != std::string::npos,
         "Metal dynamic descriptor-index source selects the descriptor before element access");
  expect(metal.find("values_0[1] = first;") != std::string::npos,
         "Metal folded descriptor-index stores stay on the direct expanded buffer path");
}

void testMetalStorageBufferOutOfRangeDescriptorArrayIndexDiagnostic() {
  constexpr std::string_view source = R"(
shader MetalStorageBufferOutOfRangeDescriptorArrayUnsupportedShader {
  const int BAD_INDEX = 2;
  const int NEGATIVE_INDEX = -1;

  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer float* values[2];
    void main() {
      float first = values[BAD_INDEX][0];
      float second = values[+BAD_INDEX][0];
      float third = values[NEGATIVE_INDEX][0];
      values[0][1] = first + second + third;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(),
         "Metal out-of-range storage-buffer descriptor array index source builds HIR");
  if (!hir) {
    return;
  }

  expect(hir->constants.size() == 2 &&
             hir->constants[0].name == "BAD_INDEX" &&
             hir->constants[0].foldedValue.has_value() &&
             *hir->constants[0].foldedValue == "2" &&
             hir->constants[1].name == "NEGATIVE_INDEX" &&
             hir->constants[1].foldedValue.has_value() &&
             *hir->constants[1].foldedValue == "-1",
         "Metal out-of-range descriptor-index fixture records folded indexes");

  const crossgl::HIRStage &stage = hir->stages.front();
  expect(stage.resources.size() == 1 &&
             stage.resources.front().kind == crossgl::HIRResourceKind::Buffer &&
             stage.resources.front().type.arraySize == "2",
         "Metal out-of-range descriptor-index fixture keeps the fixed buffer-array size");

  const std::filesystem::path packageDir =
      unitTestTempDirectoryPath() /
      "crossgl-metal-storage-buffer-out-of-range-descriptor-array-unsupported-test";
  std::error_code error;
  std::filesystem::remove_all(packageDir, error);

  crossgl::DiagnosticEngine diagnostics;
  const crossgl::MetalBuildResult result =
      crossgl::buildMetalBinary(*hir, packageDir, diagnostics);
  expect(!result.success,
         "Metal storage-buffer descriptor arrays reject folded out-of-range descriptor indexes");
  expect(hasDiagnosticMessageFragment(
             diagnostics.diagnostics(),
             "metal.unsupported-storage-buffer-array-index", "values"),
         "Metal out-of-range descriptor-index failure names the targeted buffer");
  expect(hasDiagnosticMessageFragment(
             diagnostics.diagnostics(),
             "metal.unsupported-storage-buffer-array-index", "index 2"),
         "Metal out-of-range descriptor-index failure reports the folded index");
  expect(hasDiagnosticMessageFragment(
             diagnostics.diagnostics(),
             "metal.unsupported-storage-buffer-array-index", "index -1"),
         "Metal out-of-range descriptor-index failure reports negative folded indexes");
  expect(hasDiagnosticMessageFragment(
             diagnostics.diagnostics(),
             "metal.unsupported-storage-buffer-array-index",
             "outside the fixed descriptor count"),
         "Metal out-of-range descriptor-index failure reports bounds context");
  expect(!std::filesystem::exists(packageDir),
         "Metal out-of-range descriptor-index failure does not create package output");
}

void testMetalValidationTraversalMatchesRenderedLoopUpdates() {
  auto token = [](crossgl::TokenKind kind, std::string text) {
    crossgl::Token result;
    result.kind = kind;
    result.text = std::move(text);
    return result;
  };
  auto identifier = [](std::string name) {
    return crossgl::HIRExpression{crossgl::HIRExpressionKind::Identifier, {},
                                  std::move(name), {}};
  };
  auto literal = [](std::string value) {
    return crossgl::HIRExpression{crossgl::HIRExpressionKind::Literal, {},
                                  std::move(value), {}};
  };
  auto index = [](crossgl::HIRExpression base, crossgl::HIRExpression offset) {
    crossgl::HIRExpression expression;
    expression.kind = crossgl::HIRExpressionKind::IndexAccess;
    expression.children.push_back(std::move(base));
    expression.children.push_back(std::move(offset));
    return expression;
  };
  auto member = [](crossgl::HIRExpression base, std::string name) {
    crossgl::HIRExpression expression;
    expression.kind = crossgl::HIRExpressionKind::MemberAccess;
    expression.value = std::move(name);
    expression.children.push_back(std::move(base));
    return expression;
  };
  auto declaration = [](std::string name, crossgl::HIRExpression value) {
    crossgl::HIRStatement statement;
    statement.kind = crossgl::HIRStatementKind::Declaration;
    statement.declaredType = crossgl::HIRType{"int", std::nullopt};
    statement.name = std::move(name);
    statement.value = std::move(value);
    return statement;
  };
  auto assignment = [](crossgl::HIRExpression target,
                       crossgl::HIRExpression value) {
    crossgl::HIRStatement statement;
    statement.kind = crossgl::HIRStatementKind::Assignment;
    statement.target = std::move(target);
    statement.value = std::move(value);
    return statement;
  };
  auto useRawLoopUpdate = [&](crossgl::HIRStatement &loop) {
    loop.updateTokens = {token(crossgl::TokenKind::Identifier, "i"),
                         token(crossgl::TokenKind::Operator, "++")};
  };
  auto diagnosticsForMetalBuild = [](crossgl::HIRModule module,
                                     std::string_view suffix) {
    const std::filesystem::path packageDir =
        unitTestTempDirectoryPath() /
        ("crossgl-metal-validation-update-scope-" + std::string(suffix));
    std::error_code error;
    std::filesystem::remove_all(packageDir, error);

    crossgl::DiagnosticEngine diagnostics;
    const crossgl::MetalBuildResult result =
        crossgl::buildMetalBinary(module, packageDir, diagnostics);
    (void)result;
    std::vector<crossgl::Diagnostic> collected = diagnostics.diagnostics();
    std::filesystem::remove_all(packageDir, error);
    return collected;
  };

  auto buildRuntimeModule = [&](bool rawUpdateTokens) {
    crossgl::HIRModule module;
    module.name = "MetalRuntimeTailUpdateTraversal";
    module.structs.push_back(crossgl::HIRStruct{
        "RuntimePayload",
        {crossgl::HIRField{crossgl::HIRType{"float", std::nullopt}, "count"},
         crossgl::HIRField{crossgl::HIRType{"float", std::string{}},
                           "values"}}});
    crossgl::HIRStage stage;
    stage.stage = "compute";
    stage.entryPointName = "main";
    stage.workgroupSize = crossgl::HIRWorkgroupSize{};
    crossgl::HIRResource payloads;
    payloads.kind = crossgl::HIRResourceKind::Buffer;
    payloads.type = crossgl::HIRType{"RuntimePayload*", std::nullopt};
    payloads.name = "payloads";
    stage.resources.push_back(std::move(payloads));
    crossgl::HIRFunction main;
    main.returnType = crossgl::HIRType{"void", std::nullopt};
    main.name = "main";
    crossgl::HIRStatement loop;
    loop.kind = crossgl::HIRStatementKind::For;
    loop.initializer.push_back(declaration("i", literal("0")));
    loop.value = literal("false");
    loop.update.push_back(assignment(
        member(index(identifier("payloads"), literal("1")), "count"),
        literal("1.0")));
    if (rawUpdateTokens) {
      useRawLoopUpdate(loop);
    }
    main.body.push_back(std::move(loop));
    stage.functions.push_back(std::move(main));
    module.stages.push_back(std::move(stage));
    return module;
  };

  const std::vector<crossgl::Diagnostic> runtimeTokenlessDiagnostics =
      diagnosticsForMetalBuild(buildRuntimeModule(false),
                               "runtime-tail-tokenless");
  expect(hasDiagnostic(runtimeTokenlessDiagnostics,
                       "metal.unsupported-runtime-array-block-index"),
         "Metal runtime-tail block-index validation checks tokenless generated loop updates");

  const std::vector<crossgl::Diagnostic> runtimeRawTokenDiagnostics =
      diagnosticsForMetalBuild(buildRuntimeModule(true), "runtime-tail-raw");
  expect(!hasDiagnostic(runtimeRawTokenDiagnostics,
                        "metal.unsupported-runtime-array-block-index"),
         "Metal runtime-tail block-index validation skips parsed loop updates when raw update tokens render");

  auto buildStorageModule = [&](bool rawUpdateTokens) {
    crossgl::HIRModule module;
    module.name = "MetalStorageBufferArrayUpdateTraversal";
    crossgl::HIRStage stage;
    stage.stage = "compute";
    stage.entryPointName = "main";
    stage.workgroupSize = crossgl::HIRWorkgroupSize{};
    crossgl::HIRResource values;
    values.kind = crossgl::HIRResourceKind::Buffer;
    values.type = crossgl::HIRType{"float*", std::string{"2"}};
    values.name = "values";
    stage.resources.push_back(std::move(values));
    crossgl::HIRFunction main;
    main.returnType = crossgl::HIRType{"void", std::nullopt};
    main.name = "main";
    crossgl::HIRStatement loop;
    loop.kind = crossgl::HIRStatementKind::For;
    loop.initializer.push_back(declaration("i", literal("0")));
    loop.value = literal("false");
    loop.update.push_back(assignment(
        index(index(identifier("values"), literal("2")), literal("0")),
        literal("1.0")));
    if (rawUpdateTokens) {
      useRawLoopUpdate(loop);
    }
    main.body.push_back(std::move(loop));
    stage.functions.push_back(std::move(main));
    module.stages.push_back(std::move(stage));
    return module;
  };

  const std::vector<crossgl::Diagnostic> storageTokenlessDiagnostics =
      diagnosticsForMetalBuild(buildStorageModule(false),
                               "storage-array-tokenless");
  expect(hasDiagnostic(storageTokenlessDiagnostics,
                       "metal.unsupported-storage-buffer-array-index"),
         "Metal storage-buffer descriptor-array validation checks tokenless generated loop updates for folded out-of-range indices");

  const std::vector<crossgl::Diagnostic> storageRawTokenDiagnostics =
      diagnosticsForMetalBuild(buildStorageModule(true), "storage-array-raw");
  expect(!hasDiagnostic(storageRawTokenDiagnostics,
                        "metal.unsupported-storage-buffer-array-index"),
         "Metal storage-buffer descriptor-array validation skips parsed loop updates when raw update tokens render");
}

void testVulkanVectorStorageBufferReflectionLayouts() {
  constexpr std::string_view source = R"(
shader VectorLayoutShader {
  compute {
    layout(set = 0, binding = 0) buffer vec2* values2;
    layout(set = 0, binding = 1) buffer vec3* values3;
    layout(set = 0, binding = 2) buffer vec4* values4;
    void main() {
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "vector storage buffer reflection source builds HIR");
  if (!hir) {
    return;
  }

  const crossgl::ReflectionDocument document = crossgl::buildReflectionDocument(
      *hir, crossgl::TargetKind::Vulkan, "/tmp/VectorLayoutShader.spv");
  expect(document.targetResourceBindings.size() == 3,
         "vector storage buffer reflection records all bindings");
  if (document.targetResourceBindings.size() != 3) {
    return;
  }
  expect(document.targetResourceBindings[0].storageBufferLayout.has_value() &&
             document.targetResourceBindings[1].storageBufferLayout.has_value() &&
             document.targetResourceBindings[2].storageBufferLayout.has_value(),
         "vector storage buffer reflection records layout for every binding");
  if (!document.targetResourceBindings[0].storageBufferLayout.has_value() ||
      !document.targetResourceBindings[1].storageBufferLayout.has_value() ||
      !document.targetResourceBindings[2].storageBufferLayout.has_value()) {
    return;
  }

  const crossgl::ReflectionStorageBufferLayout &vec2Layout =
      *document.targetResourceBindings[0].storageBufferLayout;
  expect(vec2Layout.elementType == "vec2",
         "vec2 storage buffer reflection records element type");
  expect(vec2Layout.elementSizeBytes == 8 && vec2Layout.arrayStrideBytes == 8 &&
             vec2Layout.alignmentBytes == 8,
         "vec2 storage buffer reflection records std430 layout");

  const crossgl::ReflectionStorageBufferLayout &vec3Layout =
      *document.targetResourceBindings[1].storageBufferLayout;
  expect(vec3Layout.elementType == "vec3",
         "vec3 storage buffer reflection records element type");
  expect(vec3Layout.elementSizeBytes == 12 && vec3Layout.arrayStrideBytes == 16 &&
             vec3Layout.alignmentBytes == 16,
         "vec3 storage buffer reflection records padded std430 layout");

  const crossgl::ReflectionStorageBufferLayout &vec4Layout =
      *document.targetResourceBindings[2].storageBufferLayout;
  expect(vec4Layout.elementType == "vec4",
         "vec4 storage buffer reflection records element type");
  expect(vec4Layout.elementSizeBytes == 16 && vec4Layout.arrayStrideBytes == 16 &&
             vec4Layout.alignmentBytes == 16,
         "vec4 storage buffer reflection records std430 layout");
}

void testSharedStorageLayoutHelper() {
  constexpr std::string_view source = R"(
shader SharedStorageLayoutHelperShader {
  const int COUNT = 2;

  struct FixedPayload {
    vec3 positions[COUNT];
    float mass;
  }

  struct RuntimePayload {
    float count;
    vec4 values[];
  }

  struct BadPayload {
    float values[];
    float after;
  }

  compute {
    layout(set = 0, binding = 0) buffer FixedPayload* fixeds;
    layout(set = 0, binding = 1) buffer RuntimePayload* payloads;
    layout(set = 0, binding = 2) buffer BadPayload* bads;
    layout(local_size_x = 1) in;
    void main() {
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "shared storage layout helper source builds HIR");
  if (!hir) {
    return;
  }
  expect(!hir->stages.empty(),
         "shared storage layout helper source records a stage");
  if (hir->stages.empty()) {
    return;
  }

  auto findResource = [&](std::string_view name) -> const crossgl::HIRResource * {
    for (const crossgl::HIRResource &resource : hir->stages.front().resources) {
      if (resource.name == name) {
        return &resource;
      }
    }
    return nullptr;
  };
  auto findStruct = [&](std::string_view name) -> const crossgl::HIRStruct * {
    return crossgl::findStructByName(hir->structs, name);
  };

  const crossgl::HIRResource *fixeds = findResource("fixeds");
  const crossgl::HIRResource *payloads = findResource("payloads");
  const crossgl::HIRResource *bads = findResource("bads");
  expect(fixeds != nullptr && payloads != nullptr && bads != nullptr,
         "shared storage layout helper source records test resources");
  if (fixeds == nullptr || payloads == nullptr || bads == nullptr) {
    return;
  }

  const crossgl::StorageLayoutContext layoutContext(hir->structs,
                                                    hir->constants);

  const std::optional<crossgl::StorageBufferLayout> fixedStd430 =
      crossgl::computeStorageBufferLayoutForResource(
          *fixeds, crossgl::StorageLayoutKind::Std430, layoutContext);
  expect(fixedStd430.has_value(),
         "shared storage layout helper computes std430 fixed-array block");
  if (fixedStd430.has_value()) {
    expect(fixedStd430->elementSizeBytes == 36 &&
               fixedStd430->arrayStrideBytes == 48 &&
               fixedStd430->fields.size() == 2,
           "shared storage layout helper records std430 fixed-array block size");
    expect(fixedStd430->fields[0].offsetBytes == 0 &&
               fixedStd430->fields[0].arrayElementCount.has_value() &&
               *fixedStd430->fields[0].arrayElementCount == 2 &&
               fixedStd430->fields[0].arrayStrideBytes.has_value() &&
               *fixedStd430->fields[0].arrayStrideBytes == 16 &&
               fixedStd430->fields[1].offsetBytes == 32,
           "shared storage layout helper records folded array field layout");
  }

  const std::optional<crossgl::StorageBufferLayout> runtimeStd430 =
      crossgl::computeStorageBufferLayoutForResource(
          *payloads, crossgl::StorageLayoutKind::Std430, layoutContext);
  const std::optional<crossgl::StorageBufferLayout> runtimeMetal =
      crossgl::computeStorageBufferLayoutForResource(
          *payloads, crossgl::StorageLayoutKind::MetalDevice, layoutContext);
  expect(runtimeStd430.has_value() && runtimeMetal.has_value(),
         "shared storage layout helper computes runtime-tail layouts");
  if (runtimeStd430.has_value() && runtimeMetal.has_value()) {
    expect(runtimeStd430->elementSizeBytes == 16 &&
               runtimeStd430->arrayStrideBytes == 0 &&
               runtimeStd430->fields[1].arrayStrideBytes.has_value() &&
               *runtimeStd430->fields[1].arrayStrideBytes == 16,
           "shared storage layout helper records std430 runtime-tail layout");
    expect(runtimeMetal->elementSizeBytes == 16 &&
               runtimeMetal->arrayStrideBytes == 0 &&
               runtimeMetal->fields[1].arrayStrideBytes.has_value() &&
               *runtimeMetal->fields[1].arrayStrideBytes == 16,
           "shared storage layout helper records metal runtime-tail layout");
  }

  const crossgl::HIRStruct *runtimePayload = findStruct("RuntimePayload");
  expect(runtimePayload != nullptr,
         "shared storage layout helper finds runtime payload struct");
  if (runtimePayload != nullptr) {
    const std::optional<std::size_t> std430Offset =
        crossgl::runtimeTailFieldOffset(
            *runtimePayload, 1, crossgl::StorageLayoutKind::Std430,
            layoutContext);
    const std::optional<std::size_t> metalOffset =
        crossgl::runtimeTailFieldOffset(
            *runtimePayload, 1, crossgl::StorageLayoutKind::MetalDevice,
            layoutContext);
    expect(std430Offset.has_value() && *std430Offset == 16 &&
               metalOffset.has_value() && *metalOffset == 16,
           "shared storage layout helper computes target runtime-tail offsets");
  }

  const std::optional<crossgl::StorageBufferLayout> badLayout =
      crossgl::computeStorageBufferLayoutForResource(
          *bads, crossgl::StorageLayoutKind::Std430, layoutContext);
  expect(!badLayout.has_value(),
         "shared storage layout helper rejects non-final runtime array fields");

  const std::vector<crossgl::HIRStruct> recursiveStructs{
      crossgl::HIRStruct{
          "Node",
          {crossgl::HIRField{crossgl::HIRType{"Node", std::nullopt}, "next"},
           crossgl::HIRField{crossgl::HIRType{"float", std::nullopt},
                             "mass"}}}};
  const crossgl::StorageLayoutContext recursiveLayoutContext(recursiveStructs,
                                                            {});
  crossgl::HIRResource recursivePayloads;
  recursivePayloads.kind = crossgl::HIRResourceKind::Buffer;
  recursivePayloads.type = crossgl::HIRType{"Node*", std::nullopt};
  recursivePayloads.name = "payloads";
  const std::optional<crossgl::StorageBufferLayout> recursiveLayout =
      crossgl::computeStorageBufferLayoutForResource(
          recursivePayloads, crossgl::StorageLayoutKind::Std430,
          recursiveLayoutContext);
  expect(!recursiveLayout.has_value(),
         "shared storage layout helper rejects recursive storage-buffer "
         "element structs");

  crossgl::StorageCapabilityPolicy recursivePolicy;
  recursivePolicy.supportedScalarTypes = {"float"};
  const std::optional<crossgl::StorageCapabilityIssue> recursiveIssue =
      crossgl::checkStorageCapabilities(
          crossgl::HIRType{"Node", std::nullopt}, recursiveLayoutContext,
          recursivePolicy, true, "payloads");
  expect(recursiveIssue.has_value() &&
             recursiveIssue->kind ==
                 crossgl::StorageCapabilityIssueKind::UnsupportedLayout &&
             recursiveIssue->path == "payloads.next",
         "storage capability helper rejects recursive storage-buffer "
         "element structs without recursing indefinitely");
}

