void testVulkanTextureSamplerArrayImplicitSamplePrototypeAssembly() {
  constexpr std::string_view source = R"(
shader VulkanTextureSamplerArrayAccessUnsupportedShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer vec4* values;
    layout(set = 0, binding = 2) uniform sampler2D shadowMaps[2];
    layout(set = 0, binding = 5) sampler comparisonSamplers[2];
    void main() {
      vec4 color = shadowMaps[0].sample(comparisonSamplers[0], vec2(0.5, 0.5));
      values[0] = color;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "implicit sample Vulkan source builds HIR");
  if (!hir) {
    return;
  }

  const std::vector<crossgl::HIRStatement> &body =
      hir->stages.front().functions.front().body;
  expect(!body.empty() &&
             body.front().value.kind == crossgl::HIRExpressionKind::TextureSample &&
             body.front().value.value == "sample" &&
             body.front().value.children.size() == 3,
         "method .sample is represented as explicit-sampler texture sample HIR");

  crossgl::DiagnosticEngine supportDiagnostics;
  expect(crossgl::vulkanPrototypeBinarySupported(*hir, supportDiagnostics) &&
             !supportDiagnostics.hasErrors(),
         "Vulkan prototype accepts compute method sample with explicit sampler");

  const crossgl::TargetPackageDecision vulkanDecision =
      crossgl::targetPackageDecision(*hir, crossgl::TargetKind::Vulkan);
  expect(vulkanDecision.nativeImplemented &&
             vulkanDecision.packageBuildSupported &&
             vulkanDecision.packageMode == "native" &&
             vulkanDecision.missingCapabilities.empty(),
         "Vulkan package decision treats compute method sample as native");

  crossgl::DiagnosticEngine assemblyDiagnostics;
  const std::string assembly =
      crossgl::generateVulkanPrototypeAssembly(*hir, assemblyDiagnostics);
  expect(!assemblyDiagnostics.hasErrors(),
         "implicit sample Vulkan prototype assembly has no diagnostics");
  expect(assembly.find("OpAccessChain %ptr_UniformConstant_sampledImage_sampler2D "
                       "%resource_shadowMaps") != std::string::npos,
         "Vulkan implicit sample assembly indexes sampled image descriptor array");
  expect(assembly.find("OpAccessChain %ptr_UniformConstant_sampler_sampler "
                       "%resource_comparisonSamplers") != std::string::npos,
         "Vulkan implicit sample assembly indexes sampler descriptor array");
  expect(assembly.find("OpImageSampleExplicitLod %vec4") != std::string::npos,
         "Vulkan implicit sample assembly emits explicit-lod sample");
  expect(assembly.find(" Lod %const_float__0_0") != std::string::npos,
         "Vulkan implicit sample assembly synthesizes lod zero");
}

void testVulkanTextureSamplerArrayLodPrototypeAssembly() {
  constexpr std::string_view source = R"(
shader VulkanTextureSamplerArrayLodShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer vec4* values;
    layout(set = 0, binding = 2) uniform sampler2D shadowMaps[2];
    layout(set = 0, binding = 5) sampler comparisonSamplers[2];
    void main() {
      vec4 color = textureLod(shadowMaps[0], comparisonSamplers[0],
                              vec2(0.5, 0.5), 0.0);
      values[0] = color;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "textureLod Vulkan source builds HIR");
  if (!hir) {
    return;
  }

  const std::vector<crossgl::HIRStatement> &body =
      hir->stages.front().functions.front().body;
  expect(!body.empty() &&
             body.front().value.kind == crossgl::HIRExpressionKind::TextureSample &&
             body.front().value.value == "textureLod" &&
             body.front().value.children.size() == 4,
         "textureLod is represented as explicit-lod texture sample HIR");
  const std::string hirDump = crossgl::printHIR(*hir);
  expect(hirDump.find("texture_sample_lod(shadowMaps[0], "
                      "comparisonSamplers[0], vec2(0.5, 0.5), 0.0)") !=
             std::string::npos,
         "HIR dump prints explicit-lod texture sample");

  const std::string metal =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::Metal);
  expect(metal.find("shadowMaps[0].sample(comparisonSamplers[0], "
                    "float2(0.5, 0.5), level(0.0))") != std::string::npos,
         "Metal backend lowers textureLod to level sampling");

  const std::string directx =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::DirectX);
  expect(directx.find("Texture2D<float4> shadowMaps[2] : register(t2, "
                      "space0);") != std::string::npos,
         "DirectX backend emits indexed 2D texture descriptor array");
  expect(directx.find("SamplerState comparisonSamplers[2] : register(s5, "
                      "space0);") != std::string::npos,
         "DirectX backend emits indexed sampler descriptor array");
  expect(directx.find("float4 color = shadowMaps[0].SampleLevel("
                      "comparisonSamplers[0], float2(0.5, 0.5), 0.0);") !=
             std::string::npos,
         "DirectX backend lowers indexed 2D textureLod to SampleLevel");

  const std::string opengl =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::OpenGL);
  expect(opengl.find("layout(binding = 2) uniform texture2D shadowMaps[2];") !=
             std::string::npos,
         "OpenGL backend emits indexed 2D texture descriptor array");
  expect(opengl.find("layout(binding = 5) uniform sampler "
                     "comparisonSamplers[2];") != std::string::npos,
         "OpenGL backend emits indexed sampler descriptor array");
  expect(opengl.find("vec4 color = textureLod(sampler2D(shadowMaps[0], "
                     "comparisonSamplers[0]), vec2(0.5, 0.5), 0.0);") !=
             std::string::npos,
         "OpenGL backend lowers indexed 2D textureLod to sampler constructor");

  crossgl::DiagnosticEngine assemblyDiagnostics;
  const std::string assembly =
      crossgl::generateVulkanPrototypeAssembly(*hir, assemblyDiagnostics);
  expect(!assemblyDiagnostics.hasErrors(),
         "textureLod Vulkan prototype assembly has no diagnostics");
  expect(assembly.find("OpAccessChain %ptr_UniformConstant_sampledImage_sampler2D "
                       "%resource_shadowMaps") != std::string::npos,
         "Vulkan textureLod assembly indexes sampled image descriptor array");
  expect(assembly.find("OpAccessChain %ptr_UniformConstant_sampler_sampler "
                       "%resource_comparisonSamplers") != std::string::npos,
         "Vulkan textureLod assembly indexes sampler descriptor array");
  expect(assembly.find("OpSampledImage") != std::string::npos,
         "Vulkan textureLod assembly combines image and sampler");
  expect(assembly.find("OpImageSampleExplicitLod %vec4") != std::string::npos,
         "Vulkan textureLod assembly emits explicit-lod sample");
  expect(assembly.find(" Lod %const_float__0_0") != std::string::npos,
         "Vulkan textureLod assembly uses the source lod operand");

  if (!crossgl::findExecutable("spirv-as") ||
      !crossgl::findExecutable("spirv-val")) {
    return;
  }

  const std::filesystem::path packageDir =
      unitTestTempDirectoryPath() /
      "crossgl-vulkan-texture-sampler-array-lod-prototype-test";
  std::error_code error;
  std::filesystem::remove_all(packageDir, error);

  crossgl::DiagnosticEngine buildDiagnostics;
  const crossgl::VulkanBuildResult result =
      crossgl::buildVulkanPrototypeBinary(*hir, packageDir, buildDiagnostics);
  expect(result.success,
         "textureLod Vulkan binary assembles and validates");
  expect(!buildDiagnostics.hasErrors(),
         "textureLod Vulkan binary build has no diagnostics");
  expect(std::filesystem::exists(result.assemblyPath),
         "textureLod Vulkan assembly file exists");
  expect(std::filesystem::exists(result.spvPath),
         "textureLod Vulkan binary exists");
}

void testVulkanTextureSamplerLodPrototypeAssembly() {
  constexpr std::string_view source = R"(
shader VulkanTextureSamplerLodShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer vec4* values;
    layout(set = 0, binding = 2) uniform sampler2D shadowMap;
    layout(set = 0, binding = 5) sampler comparisonSampler;
    void main() {
      vec4 color = textureLod(shadowMap, comparisonSampler, vec2(0.25, 0.75), 1.0);
      values[0] = color;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "direct textureLod Vulkan source builds HIR");
  if (!hir) {
    return;
  }

  const std::string metal =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::Metal);
  expect(metal.find("shadowMap.sample(comparisonSampler, "
                    "float2(0.25, 0.75), level(1.0))") != std::string::npos,
         "Metal backend lowers direct textureLod to level sampling");

  crossgl::DiagnosticEngine assemblyDiagnostics;
  const std::string assembly =
      crossgl::generateVulkanPrototypeAssembly(*hir, assemblyDiagnostics);
  expect(!assemblyDiagnostics.hasErrors(),
         "direct textureLod Vulkan prototype assembly has no diagnostics");
  expect(assembly.find("%resource_shadowMap = OpVariable "
                       "%ptr_UniformConstant_sampledImage_sampler2D "
                       "UniformConstant") != std::string::npos,
         "Vulkan direct textureLod assembly declares sampled image descriptor");
  expect(assembly.find("%resource_comparisonSampler = OpVariable "
                       "%ptr_UniformConstant_sampler_sampler "
                       "UniformConstant") != std::string::npos,
         "Vulkan direct textureLod assembly declares sampler descriptor");
  expect(assembly.find("OpAccessChain %ptr_UniformConstant_sampledImage") ==
             std::string::npos,
         "Vulkan direct textureLod assembly does not index descriptor arrays");
  expect(assembly.find("OpSampledImage %sampled_sampler2D") != std::string::npos,
         "Vulkan direct textureLod assembly combines image and sampler");
  expect(assembly.find("OpImageSampleExplicitLod %vec4") != std::string::npos,
         "Vulkan direct textureLod assembly emits explicit-lod sample");
  expect(assembly.find(" Lod %const_float__1_0") != std::string::npos,
         "Vulkan direct textureLod assembly uses direct source lod operand");

  const crossgl::ReflectionDocument reflection =
      crossgl::buildReflectionDocument(*hir, crossgl::TargetKind::Vulkan,
                                       "/tmp/VulkanTextureSamplerLodShader.spv");
  const crossgl::ReflectionTargetResourceBinding *shadowMap =
      findTargetResourceBinding(reflection, "shadowMap");
  expect(shadowMap != nullptr &&
             shadowMap->descriptorType == "VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE" &&
             !shadowMap->arrayElementCount.has_value(),
         "Vulkan reflection records direct sampled image descriptor");
  const crossgl::ReflectionTargetResourceBinding *comparisonSampler =
      findTargetResourceBinding(reflection, "comparisonSampler");
  expect(comparisonSampler != nullptr &&
             comparisonSampler->descriptorType == "VK_DESCRIPTOR_TYPE_SAMPLER" &&
             !comparisonSampler->arrayElementCount.has_value(),
         "Vulkan reflection records direct sampler descriptor");

  if (!crossgl::findExecutable("spirv-as") ||
      !crossgl::findExecutable("spirv-val")) {
    return;
  }

  const std::filesystem::path packageDir =
      unitTestTempDirectoryPath() /
      "crossgl-vulkan-texture-sampler-lod-prototype-test";
  std::error_code error;
  std::filesystem::remove_all(packageDir, error);

  crossgl::DiagnosticEngine buildDiagnostics;
  const crossgl::VulkanBuildResult result =
      crossgl::buildVulkanPrototypeBinary(*hir, packageDir, buildDiagnostics);
  expect(result.success,
         "direct textureLod Vulkan binary assembles and validates");
  expect(!buildDiagnostics.hasErrors(),
         "direct textureLod Vulkan binary build has no diagnostics");
  expect(std::filesystem::exists(result.assemblyPath),
         "direct textureLod Vulkan assembly file exists");
  expect(std::filesystem::exists(result.spvPath),
         "direct textureLod Vulkan binary exists");
}

