void testVulkanTextureSamplerCubeLodPrototypeAssembly() {
  constexpr std::string_view source = R"(
shader VulkanTextureSamplerCubeLodShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer vec4* values;
    layout(set = 0, binding = 2) uniform samplerCube skyMap;
    layout(set = 0, binding = 5) sampler skySampler;
    void main() {
      vec4 color = textureLod(skyMap, skySampler, vec3(0.0, 1.0, 0.0), 1.0);
      values[0] = color;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "cube textureLod Vulkan source builds HIR");
  if (!hir) {
    return;
  }

  const std::string hirDump = crossgl::printHIR(*hir);
  expect(hirDump.find("texture_sample_lod(skyMap, skySampler, "
                      "vec3(0.0, 1.0, 0.0), 1.0)") != std::string::npos,
         "HIR dump prints cube explicit-lod texture sample");
  const std::string crossglIr = crossgl::printCrossGLIR(*hir);
  expect(crossglIr.find("!crossgl.texture<cube, f32>") != std::string::npos,
         "CrossGL IR preserves cube texture resource type");

  const std::string metal =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::Metal);
  expect(metal.find("texturecube<float> skyMap [[texture(2)]]") !=
             std::string::npos,
         "Metal backend emits texturecube resource argument");
  expect(metal.find("skyMap.sample(skySampler, float3(0.0, 1.0, 0.0), "
                    "level(1.0))") != std::string::npos,
         "Metal backend lowers cube textureLod to level sampling");

  crossgl::DiagnosticEngine assemblyDiagnostics;
  const std::string assembly =
      crossgl::generateVulkanPrototypeAssembly(*hir, assemblyDiagnostics);
  expect(!assemblyDiagnostics.hasErrors(),
         "cube textureLod Vulkan prototype assembly has no diagnostics");
  expect(assembly.find("OpTypeImage %float Cube 0 0 0 1 Unknown") !=
             std::string::npos,
         "Vulkan cube textureLod assembly emits cube image type");
  expect(assembly.find("%resource_skyMap = OpVariable "
                       "%ptr_UniformConstant_sampledImage_samplerCube "
                       "UniformConstant") != std::string::npos,
         "Vulkan cube textureLod assembly declares sampled image descriptor");
  expect(assembly.find("OpCompositeConstruct %vec3") != std::string::npos,
         "Vulkan cube textureLod assembly constructs vec3 direction");
  expect(assembly.find("OpSampledImage %sampled_samplerCube") !=
             std::string::npos,
         "Vulkan cube textureLod assembly combines cube image and sampler");
  expect(assembly.find("OpImageSampleExplicitLod %vec4") != std::string::npos,
         "Vulkan cube textureLod assembly emits explicit-lod sample");
  expect(assembly.find(" Lod %const_float__1_0") != std::string::npos,
         "Vulkan cube textureLod assembly uses source lod operand");

  const crossgl::ReflectionDocument reflection =
      crossgl::buildReflectionDocument(*hir, crossgl::TargetKind::Vulkan,
                                       "/tmp/VulkanTextureSamplerCubeLodShader.spv");
  const crossgl::ReflectionTargetResourceBinding *skyMap =
      findTargetResourceBinding(reflection, "skyMap");
  expect(skyMap != nullptr &&
             skyMap->descriptorType == "VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE",
         "Vulkan reflection records cube sampled image descriptor");
  const crossgl::ReflectionTargetResourceBinding *skySampler =
      findTargetResourceBinding(reflection, "skySampler");
  expect(skySampler != nullptr &&
             skySampler->descriptorType == "VK_DESCRIPTOR_TYPE_SAMPLER",
         "Vulkan reflection records cube sampler descriptor");

  if (!crossgl::findExecutable("spirv-as") ||
      !crossgl::findExecutable("spirv-val")) {
    return;
  }

  const std::filesystem::path packageDir =
      unitTestTempDirectoryPath() /
      "crossgl-vulkan-texture-sampler-cube-lod-prototype-test";
  std::error_code error;
  std::filesystem::remove_all(packageDir, error);

  crossgl::DiagnosticEngine buildDiagnostics;
  const crossgl::VulkanBuildResult result =
      crossgl::buildVulkanPrototypeBinary(*hir, packageDir, buildDiagnostics);
  expect(result.success,
         "cube textureLod Vulkan binary assembles and validates");
  expect(!buildDiagnostics.hasErrors(),
         "cube textureLod Vulkan binary build has no diagnostics");
  expect(std::filesystem::exists(result.assemblyPath),
         "cube textureLod Vulkan assembly file exists");
  expect(std::filesystem::exists(result.spvPath),
         "cube textureLod Vulkan binary exists");
}

void testVulkanTextureSamplerCubeArrayLodPrototypeAssembly() {
  constexpr std::string_view source = R"(
shader VulkanTextureSamplerCubeArrayLodShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer vec4* values;
    layout(set = 0, binding = 2) uniform samplerCube skyMaps[2];
    layout(set = 0, binding = 5) sampler skySamplers[2];
    void main() {
      vec4 color = textureLod(skyMaps[1], skySamplers[0],
                              vec3(0.0, 1.0, 0.0), 2.0);
      values[0] = color;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "cube textureLod array Vulkan source builds HIR");
  if (!hir) {
    return;
  }

  const std::string hirDump = crossgl::printHIR(*hir);
  expect(hirDump.find("texture_sample_lod(skyMaps[1], skySamplers[0], "
                      "vec3(0.0, 1.0, 0.0), 2.0)") != std::string::npos,
         "HIR dump prints indexed cube explicit-lod texture sample");

  const std::string metal =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::Metal);
  expect(metal.find("array<texturecube<float>, 2> skyMaps [[texture(2)]]") !=
             std::string::npos,
         "Metal backend emits texturecube descriptor-array argument");
  expect(metal.find("skyMaps[1].sample(skySamplers[0], "
                    "float3(0.0, 1.0, 0.0), level(2.0))") !=
             std::string::npos,
         "Metal backend lowers indexed cube textureLod to level sampling");

  const std::string directx =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::DirectX);
  expect(directx.find("TextureCube<float4> skyMaps[2] : register(t2, "
                      "space0);") != std::string::npos,
         "DirectX backend emits indexed cube texture descriptor array");
  expect(directx.find("SamplerState skySamplers[2] : register(s5, space0);") !=
             std::string::npos,
         "DirectX backend emits indexed cube sampler descriptor array");
  expect(directx.find("float4 color = skyMaps[1].SampleLevel(skySamplers[0], "
                      "float3(0.0, 1.0, 0.0), 2.0);") != std::string::npos,
         "DirectX backend lowers indexed cube textureLod to SampleLevel");

  const std::string opengl =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::OpenGL);
  expect(opengl.find("layout(binding = 2) uniform textureCube skyMaps[2];") !=
             std::string::npos,
         "OpenGL backend emits indexed cube texture descriptor array");
  expect(opengl.find("layout(binding = 5) uniform sampler skySamplers[2];") !=
             std::string::npos,
         "OpenGL backend emits indexed cube sampler descriptor array");
  expect(opengl.find("vec4 color = textureLod(samplerCube(skyMaps[1], "
                     "skySamplers[0]), vec3(0.0, 1.0, 0.0), 2.0);") !=
             std::string::npos,
         "OpenGL backend lowers indexed cube textureLod to sampler constructor");

  crossgl::DiagnosticEngine assemblyDiagnostics;
  const std::string assembly =
      crossgl::generateVulkanPrototypeAssembly(*hir, assemblyDiagnostics);
  expect(!assemblyDiagnostics.hasErrors(),
         "cube textureLod array Vulkan prototype assembly has no diagnostics");
  expect(assembly.find("%arr_image_samplerCube_2_ = OpTypeArray %image_Cube "
                       "%const_uint_2") != std::string::npos,
         "Vulkan cube textureLod array assembly emits fixed cube image array type");
  expect(assembly.find("%resource_skyMaps = OpVariable "
                       "%ptr_UniformConstant_sampledImage_samplerCube_2_ "
                       "UniformConstant") != std::string::npos,
         "Vulkan cube textureLod array assembly declares sampled image array");
  expect(assembly.find("OpAccessChain %ptr_UniformConstant_sampledImage_samplerCube "
                       "%resource_skyMaps") != std::string::npos,
         "Vulkan cube textureLod array assembly indexes sampled image array");
  expect(assembly.find("OpAccessChain %ptr_UniformConstant_sampler_sampler "
                       "%resource_skySamplers") != std::string::npos,
         "Vulkan cube textureLod array assembly indexes sampler array");
  expect(assembly.find("OpSampledImage %sampled_samplerCube") !=
             std::string::npos,
         "Vulkan cube textureLod array assembly combines image and sampler");
  expect(assembly.find("OpImageSampleExplicitLod %vec4") != std::string::npos,
         "Vulkan cube textureLod array assembly emits explicit-lod sample");
  expect(assembly.find(" Lod %const_float__2_0") != std::string::npos,
         "Vulkan cube textureLod array assembly uses source lod operand");

  const crossgl::ReflectionDocument reflection =
      crossgl::buildReflectionDocument(*hir, crossgl::TargetKind::Vulkan,
                                       "/tmp/VulkanTextureSamplerCubeArrayLodShader.spv");
  const crossgl::ReflectionTargetResourceBinding *skyMaps =
      findTargetResourceBinding(reflection, "skyMaps");
  expect(skyMaps != nullptr &&
             skyMaps->descriptorType == "VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE" &&
             skyMaps->arrayElementCount == 2,
         "Vulkan reflection records cube sampled image descriptor-array count");
  const crossgl::ReflectionTargetResourceBinding *skySamplers =
      findTargetResourceBinding(reflection, "skySamplers");
  expect(skySamplers != nullptr &&
             skySamplers->descriptorType == "VK_DESCRIPTOR_TYPE_SAMPLER" &&
             skySamplers->arrayElementCount == 2,
         "Vulkan reflection records cube sampler descriptor-array count");

  if (!crossgl::findExecutable("spirv-as") ||
      !crossgl::findExecutable("spirv-val")) {
    return;
  }

  const std::filesystem::path packageDir =
      unitTestTempDirectoryPath() /
      "crossgl-vulkan-texture-sampler-cube-array-lod-prototype-test";
  std::error_code error;
  std::filesystem::remove_all(packageDir, error);

  crossgl::DiagnosticEngine buildDiagnostics;
  const crossgl::VulkanBuildResult result =
      crossgl::buildVulkanPrototypeBinary(*hir, packageDir, buildDiagnostics);
  expect(result.success,
         "cube textureLod array Vulkan binary assembles and validates");
  expect(!buildDiagnostics.hasErrors(),
         "cube textureLod array Vulkan binary build has no diagnostics");
  expect(std::filesystem::exists(result.assemblyPath),
         "cube textureLod array Vulkan assembly file exists");
  expect(std::filesystem::exists(result.spvPath),
         "cube textureLod array Vulkan binary exists");
}

void testIntegerTextureSampleResultTypes() {
  constexpr std::string_view source = R"(
shader VulkanIntegerTextureSamplerLodShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer ivec4* values;
    layout(set = 0, binding = 1) buffer uvec4* masks;
    layout(set = 0, binding = 2) uniform isampler2D labelMap;
    layout(set = 0, binding = 3) uniform usamplerCube maskMap;
    layout(set = 0, binding = 5) sampler labelSampler;
    layout(set = 0, binding = 6) sampler maskSampler;

    void main() {
      ivec4 label = textureLod(labelMap, labelSampler, vec2(0.5, 0.5), 0.0);
      uvec4 mask = textureLod(maskMap, maskSampler, vec3(0.0, 1.0, 0.0), 0.0);
      values[0] = label;
      masks[0] = mask;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "integer texture sample source builds HIR");
  if (!hir) {
    return;
  }

  const crossgl::HIRFunction &main = hir->stages.front().functions.front();
  const std::vector<crossgl::HIRStatement> &body = main.body;
  expect(!body.empty() &&
             body.front().value.kind == crossgl::HIRExpressionKind::TextureSample &&
             body.front().value.type.name == "ivec4",
         "isampler2D textureLod infers ivec4 sample result");
  expect(body.size() > 1 &&
             body[1].value.kind == crossgl::HIRExpressionKind::TextureSample &&
             body[1].value.type.name == "uvec4",
         "usamplerCube textureLod infers uvec4 sample result");

  const std::string crossglIR = crossgl::printCrossGLIR(*hir);
  expect(crossglIR.find("!crossgl.texture<2d, i32>") != std::string::npos,
         "HIR dump records signed integer 2D texture element type");
  expect(crossglIR.find("!crossgl.texture<cube, u32>") != std::string::npos,
         "HIR dump records unsigned integer cube texture element type");

  const std::string metal = crossgl::generateMetalSource(*hir);
  expect(metal.find("texture2d<int> labelMap [[texture(2)]]") !=
             std::string::npos,
         "Metal backend maps isampler2D to texture2d<int>");
  expect(metal.find("texturecube<uint> maskMap [[texture(3)]]") !=
             std::string::npos,
         "Metal backend maps usamplerCube to texturecube<uint>");
  expect(metal.find("int4 label = labelMap.sample(labelSampler, "
                    "float2(0.5, 0.5), level(0.0));") != std::string::npos,
         "Metal backend keeps integer texture sample result type");
  expect(metal.find("uint4 mask = maskMap.sample(maskSampler, "
                    "float3(0.0, 1.0, 0.0), level(0.0));") != std::string::npos,
         "Metal backend keeps unsigned integer cube texture sample result type");

  const std::string directx =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::DirectX);
  expect(directx.find("Texture2D<int4> labelMap : register(t2, space0);") !=
             std::string::npos,
         "DirectX backend maps isampler2D to Texture2D<int4>");
  expect(directx.find("TextureCube<uint4> maskMap : register(t3, space0);") !=
             std::string::npos,
         "DirectX backend maps usamplerCube to TextureCube<uint4>");
  expect(directx.find("int4 label = labelMap.SampleLevel(labelSampler, "
                      "float2(0.5, 0.5), 0.0);") != std::string::npos,
         "DirectX backend lowers signed integer textureLod");
  expect(directx.find("uint4 mask = maskMap.SampleLevel(maskSampler, "
                      "float3(0.0, 1.0, 0.0), 0.0);") != std::string::npos,
         "DirectX backend lowers unsigned integer cube textureLod");

  const std::string opengl =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::OpenGL);
  expect(opengl.find("layout(binding = 2) uniform itexture2D labelMap;") !=
             std::string::npos,
         "OpenGL backend maps isampler2D to itexture2D");
  expect(opengl.find("layout(binding = 3) uniform utextureCube maskMap;") !=
             std::string::npos,
         "OpenGL backend maps usamplerCube to utextureCube");
  expect(opengl.find("ivec4 label = textureLod(isampler2D(labelMap, "
                     "labelSampler), vec2(0.5, 0.5), 0.0);") !=
             std::string::npos,
         "OpenGL backend lowers signed integer textureLod");
  expect(opengl.find("uvec4 mask = textureLod(usamplerCube(maskMap, "
                     "maskSampler), vec3(0.0, 1.0, 0.0), 0.0);") !=
             std::string::npos,
         "OpenGL backend lowers unsigned integer cube textureLod");

  const std::vector<crossgl::TargetCapability> directxMissing =
      crossgl::missingTargetCapabilities(*hir, crossgl::TargetKind::DirectX);
  expect(!hasCapability(directxMissing, crossgl::TargetKind::DirectX,
                        "operation", "texture-explicit-lod"),
         "DirectX integer textureLod scaffold satisfies texture capability");

  const std::vector<crossgl::TargetCapability> openglMissing =
      crossgl::missingTargetCapabilities(*hir, crossgl::TargetKind::OpenGL);
  expect(!hasCapability(openglMissing, crossgl::TargetKind::OpenGL,
                        "operation", "texture-explicit-lod"),
         "OpenGL integer textureLod scaffold satisfies texture capability");

  crossgl::DiagnosticEngine assemblyDiagnostics;
  const std::string assembly =
      crossgl::generateVulkanPrototypeAssembly(*hir, assemblyDiagnostics);
  expect(!assemblyDiagnostics.hasErrors(),
         "integer textureLod Vulkan prototype assembly has no diagnostics");
  expect(assembly.find("%ivec4 = OpTypeVector %int 4") != std::string::npos,
         "Vulkan integer texture assembly emits signed vector result type");
  expect(assembly.find("OpTypeImage %int 2D") != std::string::npos,
         "Vulkan integer texture assembly emits signed image sampled type");
  expect(assembly.find("OpImageSampleExplicitLod %ivec4") != std::string::npos,
         "Vulkan integer texture assembly samples to ivec4");
  expect(assembly.find("%uvec4 = OpTypeVector %uint 4") != std::string::npos,
         "Vulkan integer texture assembly emits unsigned vector result type");
  expect(assembly.find("OpTypeImage %uint Cube") != std::string::npos,
         "Vulkan integer texture assembly emits unsigned cube image sampled type");
  expect(assembly.find("OpImageSampleExplicitLod %uvec4") != std::string::npos,
         "Vulkan integer texture assembly samples to uvec4");

  const crossgl::ReflectionDocument reflection =
      crossgl::buildReflectionDocument(
          *hir, crossgl::TargetKind::Vulkan,
          "/tmp/VulkanIntegerTextureSamplerLodShader.spv");
  const crossgl::ReflectionStorageBufferLayout *layout =
      firstStorageBufferLayout(reflection);
  expect(layout != nullptr && layout->elementType == "ivec4" &&
             layout->arrayStrideBytes == 16,
         "reflection records signed integer vector storage layout");

  if (!crossgl::findExecutable("spirv-as") ||
      !crossgl::findExecutable("spirv-val")) {
    return;
  }

  const std::filesystem::path packageDir =
      unitTestTempDirectoryPath() /
      "crossgl-vulkan-integer-texture-sampler-lod-test";
  std::error_code error;
  std::filesystem::remove_all(packageDir, error);

  crossgl::DiagnosticEngine buildDiagnostics;
  const crossgl::VulkanBuildResult result =
      crossgl::buildVulkanPrototypeBinary(*hir, packageDir, buildDiagnostics);
  expect(result.success,
         "integer textureLod Vulkan binary assembles and validates");
  expect(!buildDiagnostics.hasErrors(),
         "integer textureLod Vulkan binary build has no diagnostics");
  expect(std::filesystem::exists(result.assemblyPath),
         "integer textureLod Vulkan assembly file exists");
  expect(std::filesystem::exists(result.spvPath),
         "integer textureLod Vulkan binary exists");
}

void testIntegerArrayTextureSampleResultTypes() {
  constexpr std::string_view source = R"(
shader VulkanIntegerTextureArraySamplerLodShader {
  compute {
    layout(local_size_x = 1, local_size_y = 1, local_size_z = 1) in;
    layout(set = 0, binding = 0) buffer ivec4* values;
    layout(set = 0, binding = 1) buffer uvec4* masks;
    layout(set = 0, binding = 2) uniform isampler2DArray labelAtlas;
    layout(set = 0, binding = 3) uniform usamplerCubeArray maskCubes;
    layout(set = 0, binding = 5) sampler labelSampler;
    layout(set = 0, binding = 6) sampler maskSampler;

    void main() {
      ivec4 label =
          textureLod(labelAtlas, labelSampler, vec3(0.5, 0.5, 1.0), 0.0);
      uvec4 mask =
          textureLod(maskCubes, maskSampler, vec4(0.0, 1.0, 0.0, 2.0), 0.0);
      values[0] = label;
      masks[0] = mask;
      return;
    }
  }
}
)";

  std::optional<crossgl::HIRModule> hir = parseHIR(source);
  expect(hir.has_value(), "integer array texture sample source builds HIR");
  if (!hir) {
    return;
  }

  const crossgl::HIRStage &stage = hir->stages.front();
  expect(stage.resources.size() >= 4 &&
             stage.resources[2].kind == crossgl::HIRResourceKind::Texture &&
             stage.resources[2].type.name == "isampler2DArray",
         "isampler2DArray resource is modeled as a signed integer array texture");
  expect(stage.resources.size() >= 4 &&
             stage.resources[3].kind == crossgl::HIRResourceKind::Texture &&
             stage.resources[3].type.name == "usamplerCubeArray",
         "usamplerCubeArray resource is modeled as an unsigned integer cube-array texture");

  const crossgl::HIRFunction &main = stage.functions.front();
  const std::vector<crossgl::HIRStatement> &body = main.body;
  expect(!body.empty() &&
             body.front().value.kind == crossgl::HIRExpressionKind::TextureSample &&
             body.front().value.type.name == "ivec4" &&
             body.front().value.children.size() == 4 &&
             body.front().value.children[2].type.name == "vec3",
         "isampler2DArray textureLod infers ivec4 and vec3 coordinates");
  expect(body.size() > 1 &&
             body[1].value.kind == crossgl::HIRExpressionKind::TextureSample &&
             body[1].value.type.name == "uvec4" &&
             body[1].value.children.size() == 4 &&
             body[1].value.children[2].type.name == "vec4",
         "usamplerCubeArray textureLod infers uvec4 and vec4 coordinates");

  const std::string hirDump = crossgl::printHIR(*hir);
  expect(hirDump.find("texture_sample_lod(labelAtlas, labelSampler, "
                      "vec3(0.5, 0.5, 1.0), 0.0)") != std::string::npos,
         "HIR dump prints signed integer 2D-array texture sample");
  expect(hirDump.find("texture_sample_lod(maskCubes, maskSampler, "
                      "vec4(0.0, 1.0, 0.0, 2.0), 0.0)") != std::string::npos,
         "HIR dump prints unsigned integer cube-array texture sample");

  const std::string crossglIR = crossgl::printCrossGLIR(*hir);
  expect(crossglIR.find("!crossgl.texture<2d_array, i32>") !=
             std::string::npos,
         "CrossGL IR records signed integer 2D-array texture element type");
  expect(crossglIR.find("!crossgl.texture<cube_array, u32>") !=
             std::string::npos,
         "CrossGL IR records unsigned integer cube-array texture element type");

  const std::string metal = crossgl::generateMetalSource(*hir);
  expect(metal.find("texture2d_array<int> labelAtlas [[texture(2)]]") !=
             std::string::npos,
         "Metal backend maps isampler2DArray to texture2d_array<int>");
  expect(metal.find("texturecube_array<uint> maskCubes [[texture(3)]]") !=
             std::string::npos,
         "Metal backend maps usamplerCubeArray to texturecube_array<uint>");
  expect(metal.find("int4 label = labelAtlas.sample(labelSampler, "
                    "float2(0.5, 0.5), uint(1.0), level(0.0));") !=
             std::string::npos,
         "Metal backend splits integer 2D-array coordinates into uv and layer");
  expect(metal.find("uint4 mask = maskCubes.sample(maskSampler, "
                    "float3(0.0, 1.0, 0.0), uint(2.0), level(0.0));") !=
             std::string::npos,
         "Metal backend splits unsigned cube-array coordinates into direction and layer");

  const std::string directx =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::DirectX);
  expect(directx.find("Texture2DArray<int4> labelAtlas : register(t2, space0);") !=
             std::string::npos,
         "DirectX backend maps isampler2DArray to Texture2DArray<int4>");
  expect(directx.find("TextureCubeArray<uint4> maskCubes : "
                      "register(t3, space0);") != std::string::npos,
         "DirectX backend maps usamplerCubeArray to TextureCubeArray<uint4>");
  expect(directx.find("int4 label = labelAtlas.SampleLevel(labelSampler, "
                      "float3(0.5, 0.5, 1.0), 0.0);") != std::string::npos,
         "DirectX backend lowers signed integer 2D-array textureLod");
  expect(directx.find("uint4 mask = maskCubes.SampleLevel(maskSampler, "
                      "float4(0.0, 1.0, 0.0, 2.0), 0.0);") !=
             std::string::npos,
         "DirectX backend lowers unsigned integer cube-array textureLod");

  const std::string opengl =
      crossgl::printBackendIR(*hir, crossgl::TargetKind::OpenGL);
  expect(opengl.find("layout(binding = 2) uniform itexture2DArray "
                     "labelAtlas;") != std::string::npos,
         "OpenGL backend maps isampler2DArray to itexture2DArray");
  expect(opengl.find("layout(binding = 3) uniform utextureCubeArray "
                     "maskCubes;") != std::string::npos,
         "OpenGL backend maps usamplerCubeArray to utextureCubeArray");
  expect(opengl.find("ivec4 label = textureLod(isampler2DArray(labelAtlas, "
                     "labelSampler), vec3(0.5, 0.5, 1.0), 0.0);") !=
             std::string::npos,
         "OpenGL backend lowers signed integer 2D-array textureLod");
  expect(opengl.find("uvec4 mask = textureLod(usamplerCubeArray(maskCubes, "
                     "maskSampler), vec4(0.0, 1.0, 0.0, 2.0), 0.0);") !=
             std::string::npos,
         "OpenGL backend lowers unsigned integer cube-array textureLod");

  const std::vector<crossgl::TargetCapability> directxMissing =
      crossgl::missingTargetCapabilities(*hir, crossgl::TargetKind::DirectX);
  expect(!hasCapability(directxMissing, crossgl::TargetKind::DirectX,
                        "texture", "array-dimension"),
         "DirectX integer texture-array scaffold satisfies array texture capability");

  const std::vector<crossgl::TargetCapability> openglMissing =
      crossgl::missingTargetCapabilities(*hir, crossgl::TargetKind::OpenGL);
  expect(!hasCapability(openglMissing, crossgl::TargetKind::OpenGL, "texture",
                        "array-dimension"),
         "OpenGL integer texture-array scaffold satisfies array texture capability");

  crossgl::DiagnosticEngine assemblyDiagnostics;
  const std::string assembly =
      crossgl::generateVulkanPrototypeAssembly(*hir, assemblyDiagnostics);
  expect(!assemblyDiagnostics.hasErrors(),
         "integer array textureLod Vulkan prototype assembly has no diagnostics");
  expect(assembly.find("%ivec4 = OpTypeVector %int 4") != std::string::npos,
         "Vulkan integer array texture assembly emits signed vector result type");
  expect(assembly.find("OpTypeImage %int 2D 0 1 0 1 Unknown") !=
             std::string::npos,
         "Vulkan integer array texture assembly emits signed arrayed 2D image type");
  expect(assembly.find("OpSampledImage %sampled_isampler2DArray") !=
             std::string::npos,
         "Vulkan integer array texture assembly combines signed array image and sampler");
  expect(assembly.find("OpImageSampleExplicitLod %ivec4") !=
             std::string::npos,
         "Vulkan integer array texture assembly samples to ivec4");
  expect(assembly.find("%uvec4 = OpTypeVector %uint 4") != std::string::npos,
         "Vulkan integer array texture assembly emits unsigned vector result type");
  expect(assembly.find("OpTypeImage %uint Cube 0 1 0 1 Unknown") !=
             std::string::npos,
         "Vulkan integer array texture assembly emits unsigned arrayed cube image type");
  expect(assembly.find("OpSampledImage %sampled_usamplerCubeArray") !=
             std::string::npos,
         "Vulkan integer array texture assembly combines unsigned cube-array image and sampler");
  expect(assembly.find("OpImageSampleExplicitLod %uvec4") !=
             std::string::npos,
         "Vulkan integer array texture assembly samples to uvec4");

  const crossgl::ReflectionDocument reflection =
      crossgl::buildReflectionDocument(
          *hir, crossgl::TargetKind::Vulkan,
          "/tmp/VulkanIntegerTextureArraySamplerLodShader.spv");
  const crossgl::ReflectionTargetResourceBinding *labelAtlas =
      findTargetResourceBinding(reflection, "labelAtlas");
  expect(labelAtlas != nullptr && labelAtlas->spirvType.has_value() &&
             *labelAtlas->spirvType == "OpTypeImage<int, 2DArray, sampled=1>",
         "Vulkan reflection records signed integer 2D-array sampled image type");
  const crossgl::ReflectionTargetResourceBinding *maskCubes =
      findTargetResourceBinding(reflection, "maskCubes");
  expect(maskCubes != nullptr && maskCubes->spirvType.has_value() &&
             *maskCubes->spirvType ==
                 "OpTypeImage<uint, CubeArray, sampled=1>",
         "Vulkan reflection records unsigned integer cube-array sampled image type");

  const crossgl::ReflectionDocument directxReflection =
      crossgl::buildReflectionDocument(
          *hir, crossgl::TargetKind::DirectX,
          "/tmp/VulkanIntegerTextureArraySamplerLodShader.dxil");
  const crossgl::ReflectionTargetResourceBinding *directxLabelAtlas =
      findTargetResourceBinding(directxReflection, "labelAtlas");
  expect(directxLabelAtlas != nullptr &&
             directxLabelAtlas->hlslType.has_value() &&
             *directxLabelAtlas->hlslType == "Texture2DArray<int4>",
         "DirectX reflection records signed integer 2D-array texture HLSL type");
  const crossgl::ReflectionTargetResourceBinding *directxMaskCubes =
      findTargetResourceBinding(directxReflection, "maskCubes");
  expect(directxMaskCubes != nullptr &&
             directxMaskCubes->hlslType.has_value() &&
             *directxMaskCubes->hlslType == "TextureCubeArray<uint4>",
         "DirectX reflection records unsigned integer cube-array texture HLSL type");

  if (crossgl::findExecutable("spirv-as") &&
      crossgl::findExecutable("spirv-val")) {
    const std::filesystem::path packageDir =
        unitTestTempDirectoryPath() /
        "crossgl-vulkan-integer-texture-array-sampler-lod-test";
    std::error_code error;
    std::filesystem::remove_all(packageDir, error);

    crossgl::DiagnosticEngine buildDiagnostics;
    const crossgl::VulkanBuildResult result =
        crossgl::buildVulkanPrototypeBinary(*hir, packageDir, buildDiagnostics);
    expect(result.success,
           "integer array textureLod Vulkan binary assembles and validates");
    expect(!buildDiagnostics.hasErrors(),
           "integer array textureLod Vulkan binary build has no diagnostics");
    expect(std::filesystem::exists(result.assemblyPath),
           "integer array textureLod Vulkan assembly file exists");
    expect(std::filesystem::exists(result.spvPath),
           "integer array textureLod Vulkan binary exists");
  }

  if (crossgl::findExecutable("xcrun")) {
    const std::filesystem::path packageDir =
        unitTestTempDirectoryPath() /
        "crossgl-metal-integer-texture-array-sampler-lod-test";
    std::error_code error;
    std::filesystem::remove_all(packageDir, error);

    crossgl::DiagnosticEngine metalDiagnostics;
    const crossgl::MetalBuildResult metalResult =
        crossgl::buildMetalBinary(*hir, packageDir, metalDiagnostics);
    expect(metalResult.success,
           "integer array textureLod Metal binary compiles to metallib");
    expect(!metalDiagnostics.hasErrors(),
           "integer array textureLod Metal build has no diagnostics");
    expect(std::filesystem::exists(metalResult.metallibPath),
           "integer array textureLod Metal metallib exists");
  }
}

