      crossgl::generateVulkanPrototypeAssemblyArtifact(*hir,
                                                       assemblyDiagnostics);
  const std::string &assembly = artifact.assembly;
  expect(!assemblyDiagnostics.hasErrors(),
         "math intrinsic Vulkan prototype assembly has no diagnostics");
  expect(artifact.extendedInstructionImports.size() == 1 &&
             artifact.extendedInstructionImports.front().resultId ==
                 "%glsl_std_450" &&
             artifact.extendedInstructionImports.front().instructionSet ==
                 "GLSL.std.450",
         "math intrinsic Vulkan prototype assembly exposes GLSL.std.450 "
         "metadata");
  expect(assembly.find("%glsl_std_450 = OpExtInstImport \"GLSL.std.450\"") !=
             std::string::npos,
         "math intrinsic Vulkan prototype assembly imports GLSL.std.450");
  expect(assembly.find("OpExtInst %float %glsl_std_450 FAbs ") !=
             std::string::npos,
         "math intrinsic Vulkan prototype assembly emits scalar FAbs");
  expect(assembly.find("OpExtInst %float %glsl_std_450 Sin ") !=
             std::string::npos,
         "math intrinsic Vulkan prototype assembly emits Sin");
  expect(assembly.find("OpExtInst %float %glsl_std_450 Sqrt ") !=
             std::string::npos,
         "math intrinsic Vulkan prototype assembly emits Sqrt");
  expect(assembly.find("OpExtInst %float %glsl_std_450 Pow ") !=
             std::string::npos,
         "math intrinsic Vulkan prototype assembly emits scalar Pow");
  expect(assembly.find("OpExtInst %float %glsl_std_450 FMin ") !=
             std::string::npos,
         "math intrinsic Vulkan prototype assembly emits scalar FMin");
  expect(assembly.find("OpExtInst %float %glsl_std_450 FMax ") !=
             std::string::npos,
         "math intrinsic Vulkan prototype assembly emits scalar FMax");
  expect(assembly.find("OpExtInst %float %glsl_std_450 Fract ") !=
             std::string::npos,
         "math intrinsic Vulkan prototype assembly emits Fract");
  expect(assembly.find("OpExtInst %float %glsl_std_450 Length ") !=
             std::string::npos,
         "math intrinsic Vulkan prototype assembly emits Length");
  expect(assembly.find("OpDot %float") != std::string::npos,
         "math intrinsic Vulkan prototype assembly emits core OpDot");
  expect(assembly.find("OpExtInst %vec4 %glsl_std_450 Normalize ") !=
             std::string::npos,
         "math intrinsic Vulkan prototype assembly emits Normalize");
